  {
    title: "Today's New Enquiries",
    value: '0',
    bgColor: 'bg-gradient-to-br from-yellow-100 to-amber-100',
    borderColor: 'border-yellow-200',
    textColor: 'text-yellow-700',
    icon: FileText,
  },
  {
    title: 'Total Pending Enquiries',
    value: '2369',
    bgColor: 'bg-gradient-to-br from-blue-100 to-indigo-100',
    borderColor: 'border-blue-200',
    textColor: 'text-blue-700',
    icon: FileText,
  },
  {
    title: "Today's New Admission",
    value: '0',
    bgColor: 'bg-gradient-to-br from-emerald-100 to-teal-100',
    borderColor: 'border-emerald-200',
    textColor: 'text-emerald-700',
    icon: UserPlus,
  },
  {
    title: 'Total New Admission',
    value: '0',
    bgColor: 'bg-gradient-to-br from-pink-100 to-rose-100',
    borderColor: 'border-pink-200',
    textColor: 'text-pink-700',
    icon: Users,
  },
];

export default function AdmissionDashboard() {
  const [chartKey, setChartKey] = useState(0);

  const handleRefresh = () => {
    setChartKey(prev => prev + 1);
  };

  const handleCardClick = (card) => {
    alert(`${card.title}\n\nValue: ${card.value}`);
  };

  return (
    <div className="min-h-screen overflow-x-hidden bg-[linear-gradient(135deg,#f8fafc_0%,#eef2ff_45%,#f0fdf4_100%)] p-0">
      <div className="m-2.5 overflow-hidden rounded-[22px] border border-slate-200/80 bg-white/90 p-3 shadow-[0_22px_70px_-24px_rgba(2,8,23,0.35)] backdrop-blur sm:p-4 lg:p-6">
        <div className="flex flex-col gap-4">
          {/* Header Section */}
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-3 hover-gradient-border">
              <h1 className="text-2xl font-semibold text-slate-900 sm:text-3xl">Admission</h1>
            </div>
            <div className="rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm">
              <div className="font-medium text-slate-900">Admission Session</div>
              <div className="text-xs text-slate-500">2026-27 Odd</div>
            </div>
          </div>

          {/* Summary Cards */}
          <div className="grid gap-4 xl:grid-cols-4">
            {summaryCards.map((card, index) => (
              <div
                key={index}
                role="button"
                tabIndex={0}
                onClick={() => handleCardClick(card)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleCardClick(card);
                  }
                }}
                className={`${card.bgColor} rounded-[22px] border ${card.borderColor} p-6 shadow-md relative overflow-hidden transition-all duration-300 hover:shadow-lg hover:scale-[1.02] cursor-pointer`}
              >
                <div className="relative z-10">
                  <div className="flex items-start justify-between hover-gradient-border">
                    <div>
                      <p className={`text-sm font-semibold ${card.textColor}`}>{card.title}</p>
                      <h2 className="mt-3 text-4xl font-bold text-slate-900">{card.value}</h2>
                    </div>
                    <div className={`rounded-2xl ${card.textColor.replace('text-', 'bg-').replace('700', '100')} p-3`}>
                      <card.icon className={`h-6 w-6 ${card.textColor}`} />
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Two Column Layout: Admission Data & Source Wise */}
          <div className="grid gap-4 xl:grid-cols-[1.5fr_1fr]">
            {/* Left Card: Admission Data */}
            <div className="rounded-[22px] border border-slate-200/80 bg-white p-5 shadow-[0_18px_50px_-26px_rgba(15,23,42,0.28)]">
              <div className="mb-4 flex items-center justify-between gap-4 hover-gradient-border">
                <h2 className="text-lg font-semibold text-slate-900">Admission Data</h2>
                <button
                  type="button"
                  onClick={handleRefresh}
                  className="rounded-full p-2 text-slate-600 transition hover:bg-slate-100 hover:text-slate-900 hover-gradient-border"
                  title="Refresh chart data"
                >
                  <RotateCw className="h-5 w-5" />
                </button>
              </div>
              <div key={chartKey} className="mt-4">
                <AdmissionDataChart />
              </div>
            </div>

            {/* Right Card: Source Wise Admission Enquiry */}
            <div className="rounded-[22px] border border-slate-200/80 bg-white p-5 shadow-[0_18px_50px_-26px_rgba(15,23,42,0.28)]">
              <h2 className="mb-6 text-lg font-semibold text-slate-900">Source Wise Admission Enquiry</h2>
              <div className="mt-4">
                <SourceWiseAdmissionChart />
              </div>
            </div>
          </div>

          {/* Full Width: Course Wise Admission */}
          <div className="rounded-[22px] border border-slate-200/80 bg-white p-5 shadow-[0_18px_50px_-26px_rgba(15,23,42,0.28)]">
            <div className="mb-4 flex items-center justify-between gap-4 hover-gradient-border">
              <h2 className="text-lg font-semibold text-slate-900">Admission Enquiry Course Wise</h2>
            </div>
            <div className="mt-4">
              <AdmissionCourseWiseChart />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const data = [
  { name: 'Enquiry', value: 2369 },
];

export default function AdmissionDataChart() {
  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      return (
        <div className="rounded-lg border border-slate-200 bg-white p-3 shadow-lg">
          <p className="text-sm font-semibold text-slate-900">{payload[0].payload.name}</p>
          <p className="text-sm font-bold text-pink-600">{payload[0].value}</p>
        </div>
      );
    }
    return null;
  };

  return (
    <ResponsiveContainer width="100%" height={420}>
      <BarChart data={data} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
        <XAxis dataKey="name" stroke="#94a3b8" style={{ fontSize: '12px' }} />
        <YAxis stroke="#94a3b8" style={{ fontSize: '12px' }} domain={[0, 2500]} />
        <Tooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(236, 72, 153, 0.05)' }} />
        <Bar 
          dataKey="value" 
          fill="#ec4899" 
          radius={[12, 12, 0, 0]}
          isAnimationActive={true}
          animationDuration={800}
        />
      </BarChart>
    </ResponsiveContainer>
  );
}

import { useState, useMemo } from 'react';
import { PieChart, Pie, Cell, Legend, Tooltip, ResponsiveContainer } from 'recharts';

const sourceData = [
  { name: 'COLLEGE DUNIA', value: 600, fill: '#3b82f6' },
  { name: 'COLLEGE DEKHO', value: 500, fill: '#f59e0b' },
  { name: 'ZOLLEGE', value: 420, fill: '#10b981' },
  { name: 'COLLEGEHAI', value: 280, fill: '#ec4899' },
  { name: 'SHIKSHA', value: 210, fill: '#8b5cf6' },
  { name: 'GOOGLE-AD', value: 180, fill: '#06b6d4' },
  { name: 'CAMPUS VISIT', value: 95, fill: '#f97316' },
  { name: 'KOLLEGEAPPLY', value: 42, fill: '#6366f1' },
  { name: 'REGISTRATION(HU)', value: 28, fill: '#d946ef' },
  { name: 'FACEBOOK', value: 14, fill: '#0891b2' },
  { name: 'HUWEB', value: 0, fill: '#64748b' },
];

export default function SourceWiseAdmissionChart() {
  const [visibleSources, setVisibleSources] = useState(new Set(sourceData.map(s => s.name)));

  const filteredData = useMemo(() => {
    return sourceData.filter(item => visibleSources.has(item.name));
  }, [visibleSources]);

  const total = useMemo(() => {
    return filteredData.reduce((sum, item) => sum + item.value, 0);
  }, [filteredData]);

  const handleLegendClick = (entry) => {
    setVisibleSources(prev => {
      const newSet = new Set(prev);
      if (newSet.has(entry.payload.name)) {
        newSet.delete(entry.payload.name);
      } else {
        newSet.add(entry.payload.name);
      }
      return newSet;
    });
  };

  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      const percentage = ((data.value / sourceData.reduce((sum, item) => sum + item.value, 0)) * 100).toFixed(1);
      return (
        <div className="rounded-lg border border-slate-200 bg-white p-3 shadow-lg">
          <p className="text-sm font-semibold text-slate-900">{data.name}</p>
          <p className="text-sm font-bold text-slate-900">{data.value} enquiries</p>
          <p className="text-xs text-slate-500">{percentage}%</p>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex flex-col items-center gap-6">
      <ResponsiveContainer width="100%" height={280}>
        <PieChart>
          <Pie
            data={filteredData}
            cx="50%"
            cy="50%"
            innerRadius={80}
            outerRadius={120}
            paddingAngle={2}
            dataKey="value"
            isAnimationActive={true}
            animationDuration={800}
          >
            {filteredData.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.fill} />
            ))}
          </Pie>
          <Tooltip content={<CustomTooltip />} />
        </PieChart>
      </ResponsiveContainer>
      <div className="text-center">
        <p className="text-sm text-slate-500">Total</p>
        <p className="text-4xl font-bold text-slate-900">{total}</p>
      </div>
      <Legend 
        onClick={(e) => handleLegendClick(e.entry)}
        wrapperStyle={{ cursor: 'pointer', paddingTop: '20px' }}
        layout="vertical"
        align="center"
        verticalAlign="bottom"
        height={36}
      />
    </div>
  );
}

