              <div className="rounded-[18px] border border-slate-200 bg-white shadow-sm">
                <table className="w-full table-fixed border-collapse text-left">
                  <colgroup>
                    <col className="w-[205px]" />
                    <col className="w-[100px]" />
                    <col className="w-[100px]" />
                    <col className="w-[70px]" />
                    <col className="w-[100px]" />
                    <col className="w-[100px]" />
                    <col className="w-[70px]" />
                    <col className="w-[100px]" />
                    <col className="w-[100px]" />
