import { useEffect, useMemo, useState } from 'react';
import { ChevronLeft, ChevronRight, Edit3, Eye, LoaderCircle, Trash2 } from 'lucide-react';
import { useERP } from '../services/ERPContext.jsx';
import Breadcrumb from '../components/ui/Breadcrumb.jsx';
import ConfirmDialog from '../components/ui/ConfirmDialog.jsx';
import Modal from '../components/ui/Modal.jsx';
import { deleteAllocation, getAllocationsByCollege, updateAllocation } from '../services/allocateSubjectService.js';

export default function AllocateSubjectPage() {
  const { colleges = [] } = useERP();
  const collegeOptions = useMemo(() => {
    const source = Array.isArray(colleges) ? colleges : [];
    return source.map((college) => (typeof college === 'string' ? college : college.name || college.collegeName || college.label || String(college.id)));
  }, [colleges]);
  const [selectedCollege, setSelectedCollege] = useState('');
  const [rows, setRows] = useState([]);
  const [showTable, setShowTable] = useState(false);
  const [loading, setLoading] = useState(false);
  const [viewRow, setViewRow] = useState(null);
  const [editRow, setEditRow] = useState(null);
  const [deleteRow, setDeleteRow] = useState(null);
  const [sortBy, setSortBy] = useState('subject');
  const [subjectType, setSubjectType] = useState('all');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedIds, setSelectedIds] = useState([]);
  const [formState, setFormState] = useState({
    subject: '',
    faculty: '',
    status: 'Allocated',
    section: '',
    semester: '',
    course: '',
  });
  const [formError, setFormError] = useState('');

  useEffect(() => {
    document.title = 'Allocate Subject - Academics Setup';
  }, []);

  const handleGo = async () => {
    if (!selectedCollege) {
      window.alert('Please select a college before continuing.');
      return;
    }

    setLoading(true);
    setShowTable(false);
    setSelectedIds([]);
    setCurrentPage(1);

    try {
      const data = await getAllocationsByCollege(selectedCollege);
      setRows(data);
      setShowTable(true);
    } catch (error) {
      window.alert(error.message || 'Failed to load allocations.');
      setRows([]);
      setShowTable(false);
    } finally {
      setLoading(false);
    }
  };

  const visibleRows = useMemo(() => {
    const filtered = [...rows].filter((item) => {
      if (subjectType !== 'all') {
        const normalized = String(item.subject || '').toLowerCase();
        const matchesType = normalized.includes(subjectType.toLowerCase());
        if (!matchesType) {
          return false;
        }
      }

      return true;
    });

    const sorted = [...filtered].sort((a, b) => {
      const sortMap = {
        subject: String(a.subject || '').localeCompare(String(b.subject || '')),
        faculty: String(a.faculty || '').localeCompare(String(b.faculty || '')),
        semester: String(a.semester || '').localeCompare(String(b.semester || '')),
        section: String(a.section || '').localeCompare(String(b.section || '')),
      };

      return sortMap[sortBy] ?? 0;
    });

    return sorted;
  }, [rows, sortBy, subjectType]);

  const pageSize = 10;
  const totalPages = Math.max(1, Math.ceil(visibleRows.length / pageSize));
  const paginatedRows = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return visibleRows.slice(startIndex, startIndex + pageSize);
  }, [currentPage, visibleRows]);

  const handleSelectAll = (event) => {
    if (event.target.checked) {
      const allIds = paginatedRows.map((row) => row.id);
      setSelectedIds((current) => Array.from(new Set([...current, ...allIds])));
      return;
    }

    setSelectedIds((current) => current.filter((id) => !paginatedRows.some((row) => row.id === id)));
  };

  const handleToggleRow = (id) => {
    setSelectedIds((current) => (current.includes(id) ? current.filter((item) => item !== id) : [...current, id]));
  };

  const allVisibleSelected = paginatedRows.length > 0 && paginatedRows.every((row) => selectedIds.includes(row.id));

  const handleEdit = (row) => {
    setEditRow(row);
    setFormState({
      subject: row.subject || '',
      faculty: row.faculty || '',
      status: row.status || 'Allocated',
      section: row.section || '',
      semester: row.semester || '',
      course: row.course || '',
    });
    setFormError('');
  };

  const handleSaveEdit = async (event) => {
    event.preventDefault();

    if (!formState.subject.trim() || !formState.faculty.trim() || !formState.section.trim() || !formState.semester.trim() || !formState.course.trim()) {
      setFormError('All fields are required.');
      return;
    }

    try {
      const updated = await updateAllocation(editRow.id, {
        subject: formState.subject.trim(),
        faculty: formState.faculty.trim(),
        status: formState.status,
        section: formState.section.trim(),
        semester: formState.semester.trim(),
        course: formState.course.trim(),
      });

      setRows((currentRows) => currentRows.map((currentRow) => (currentRow.id === updated.id ? updated : currentRow)));
      setEditRow(null);
      setFormError('');
    } catch (error) {
      setFormError(error.message || 'Unable to update allocation.');
    }
  };

  const handleDelete = (row) => {
    setDeleteRow(row);
  };

  const handleDeleteConfirm = async () => {
    if (!deleteRow) return;

    try {
      await deleteAllocation(deleteRow.id);
      setRows((currentRows) => currentRows.filter((currentRow) => currentRow.id !== deleteRow.id));
      setDeleteRow(null);
    } catch (error) {
      window.alert(error.message || 'Unable to delete allocation.');
    }
  };

  const handleView = (row) => {
    setViewRow(row);
  };

  const renderSubjects = (row) => {
    const subjectList = [
      row.subject || 'Operating Systems',
      row.subjectCode ? `${row.subject || 'Database Management System'} Practical` : 'Database Management System Practical',
      'Computer Networks Practical',
      'Database Management System',
      'Fundamentals of AI and ML',
      'Computer Networks',
      'Object Oriented Programming using JAVA',
      'Object Oriented Programming using JAVA Practical',
      'Quantitative Aptitude and Logical Reasoning',
    ];

    return (
      <ol className="space-y-1 text-[12px] leading-[22px] text-slate-700">
        {subjectList.map((subject, index) => (
          <li key={`${row.id}-${index}`} className="flex items-start gap-2">
            <span className="mt-[1px] inline-flex h-4 min-w-[1.1rem] items-center justify-center rounded-full bg-slate-100 px-1 text-[10px] font-semibold text-slate-700">
              {index + 1}.
            </span>
            <span className="flex items-center gap-2">
              <input type="checkbox" checked={index < 3} readOnly className="mt-[2px] h-3.5 w-3.5 rounded border-slate-300 text-sky-600" />
              <span className="break-words">{subject}</span>
            </span>
          </li>
        ))}
      </ol>
    );
  };

  const rowCountText = `${Math.min(visibleRows.length, 250)} entries`;

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [currentPage, totalPages]);

  return (
    <div className="min-h-screen w-full bg-[#F5F7FB] px-[5px] py-4 text-slate-900 sm:px-[5px] lg:px-[5px]">
      <div className="w-full space-y-4">
        <div className="space-y-2">
          <Breadcrumb
            items={[
              { to: '/', label: 'Dashboard' },
              { label: 'Academics Setup' },
              { label: 'Allocate Subject' },
            ]}
          />
          <div className="space-y-0.5">
            <h1 className="text-2xl font-semibold tracking-tight text-slate-950 sm:text-3xl">Allocate Subject</h1>
            <p className="text-xs text-slate-600">Allocate Subject</p>
          </div>
        </div>

        <section className="rounded-[12px] border border-slate-200 bg-white p-3 shadow-sm sm:p-4">
          <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
            <div className="w-full md:max-w-md">
              <label className="mb-1.5 block text-xs font-semibold uppercase tracking-[0.2em] text-slate-700">Select College</label>
              <select
                value={selectedCollege}
                onChange={(event) => setSelectedCollege(event.target.value)}
                className="h-10 w-full rounded-[8px] border border-slate-200 bg-white px-3 text-sm text-slate-900 outline-none"
              >
                <option value="">-- Select --</option>
                {collegeOptions.map((college) => (
                  <option key={college} value={college}>{college}</option>
                ))}
              </select>
            </div>

            <button
              type="button"
              onClick={handleGo}
              className="inline-flex h-10 items-center justify-center rounded-[8px] bg-[#1D3557] px-5 text-sm font-semibold text-white transition hover:bg-[#16324F]"
            >
              Go
            </button>
          </div>
        </section>

        {showTable && (
          <section className="rounded-[12px] border border-slate-200 bg-white p-3 shadow-[0_8px_24px_rgba(15,23,42,.08)] sm:p-4">
            <div className="mb-3 rounded-[12px] border border-slate-200 bg-[#F8FAFC] p-3 shadow-sm">
              <div className="grid gap-3 lg:grid-cols-[1fr_1fr]">
                <div className="space-y-1">
                  <p className="text-[10px] font-semibold uppercase tracking-[0.24em] text-slate-500">College</p>
                  <p className="text-sm font-semibold text-slate-900">{selectedCollege}</p>
                </div>
                <div className="flex flex-col gap-2 lg:items-end">
                  <div className="grid w-full gap-2 sm:grid-cols-2">
                    <label className="space-y-1 text-sm text-slate-700">
                      <span className="block text-[10px] font-semibold uppercase tracking-[0.2em] text-slate-500">Sort By</span>
                      <select value={sortBy} onChange={(event) => { setSortBy(event.target.value); setCurrentPage(1); }} className="h-9 w-full rounded-[8px] border border-slate-200 bg-white px-3 text-sm text-slate-900 outline-none">
                        <option value="subject">Subject</option>
                        <option value="faculty">Faculty</option>
                        <option value="semester">Semester</option>
                        <option value="section">Section</option>
                      </select>
                    </label>
                    <label className="space-y-1 text-sm text-slate-700">
                      <span className="block text-[10px] font-semibold uppercase tracking-[0.2em] text-slate-500">Select Subject Type</span>
                      <select value={subjectType} onChange={(event) => { setSubjectType(event.target.value); setCurrentPage(1); }} className="h-9 w-full rounded-[8px] border border-slate-200 bg-white px-3 text-sm text-slate-900 outline-none">
                        <option value="all">All</option>
                        <option value="practical">Practical</option>
                        <option value="java">Java</option>
                        <option value="network">Network</option>
                      </select>
                    </label>
                  </div>
                </div>
              </div>
            </div>

            {loading ? (
              <div className="flex min-h-[240px] items-center justify-center rounded-[12px] border border-dashed border-slate-200 bg-slate-50">
                <div className="flex flex-col items-center gap-3 text-slate-600">
                  <LoaderCircle className="h-8 w-8 animate-spin text-slate-900" />
                  <p className="text-sm font-semibold text-slate-700">Loading subject allocations...</p>
                </div>
              </div>
            ) : visibleRows.length === 0 ? (
              <div className="rounded-[12px] border border-dashed border-slate-200 bg-slate-50 px-6 py-16 text-center">
                <h3 className="text-lg font-semibold text-slate-900">No Subject Allocation Found</h3>
                <p className="mt-2 text-sm text-slate-600">No records are available for the selected college.</p>
              </div>
            ) : (
              <div className="overflow-hidden rounded-[12px] border border-slate-200 bg-white shadow-[0_8px_24px_rgba(15,23,42,.08)]">
                <div className="overflow-x-auto">
                  <table className="min-w-[1180px] w-full border-collapse table-fixed text-left text-[12px] text-slate-900">
                    <thead className="sticky top-0 z-10 bg-[#1D3557] text-white">
                      <tr className="h-[48px]">
                        <th className="w-[48px] px-2 py-1 text-center font-semibold">
                          <input type="checkbox" checked={allVisibleSelected} onChange={handleSelectAll} className="h-4 w-4 rounded border-slate-300 text-sky-600" />
                        </th>
                        <th className="w-[70px] px-2 py-1 font-semibold">S.No</th>
                        <th className="w-[130px] px-2 py-1 font-semibold">Roll Number</th>
                        <th className="w-[160px] px-2 py-1 font-semibold">Student Name</th>
                        <th className="w-[160px] px-2 py-1 font-semibold">Father Name</th>
                        <th className="w-[170px] px-2 py-1 font-semibold">University Roll No.</th>
                        <th className="w-[320px] px-2 py-1 font-semibold">Subjects</th>
                        <th className="w-[180px] px-2 py-1 text-center font-semibold">Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {paginatedRows.map((row, index) => (
                        <tr key={row.id ?? `${row.subject}-${index}`} className="border-b border-slate-200 bg-white hover:bg-slate-50/50">
                          <td className="px-2 py-1 align-middle text-center">
                            <input type="checkbox" checked={selectedIds.includes(row.id)} onChange={() => handleToggleRow(row.id)} className="h-4 w-4 rounded border-slate-300 text-sky-600" />
                          </td>
                          <td className="px-2 py-1 align-middle font-semibold text-slate-700">{(currentPage - 1) * pageSize + index + 1}</td>
                          <td className="px-2 py-1 align-middle text-slate-700">{row.semester || '—'}</td>
                          <td className="px-2 py-1 align-middle text-slate-700">{row.faculty || '—'}</td>
                          <td className="px-2 py-1 align-middle text-slate-700">{row.course || '—'}</td>
                          <td className="px-2 py-1 align-middle text-slate-700">{row.subjectCode || '—'}</td>
                          <td className="px-2 py-1 align-middle">
                            <div className="min-h-[112px] py-0.5">
                              {renderSubjects(row)}
                            </div>
                          </td>
                          <td className="px-2 py-1 align-middle text-center">
                            <div className="flex items-center justify-center gap-1.5">
                              <button type="button" onClick={() => handleView(row)} className="inline-flex h-8 w-8 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-700 transition hover:bg-slate-50">
                                <Eye className="h-4 w-4" />
                              </button>
                              <button type="button" onClick={() => handleEdit(row)} className="inline-flex h-8 w-8 items-center justify-center rounded-full border border-emerald-200 bg-emerald-50 text-emerald-700 transition hover:bg-emerald-100">
                                <Edit3 className="h-4 w-4" />
                              </button>
                              <button type="button" onClick={() => handleDelete(row)} className="inline-flex h-8 w-8 items-center justify-center rounded-full border border-rose-200 bg-rose-50 text-rose-700 transition hover:bg-rose-100">
                                <Trash2 className="h-4 w-4" />
                              </button>
                              <button type="button" className="inline-flex h-[36px] w-[125px] items-center justify-center rounded-[8px] bg-[#1D3557] px-2 text-[11px] font-semibold text-white transition hover:bg-[#16324F]">
                                Save Subjects
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                <div className="flex flex-col gap-2 border-t border-slate-200 bg-white px-3 py-2 sm:flex-row sm:items-center sm:justify-between">
                  <p className="text-xs text-slate-600">Showing 1 to {paginatedRows.length} of {visibleRows.length} entries</p>
                  <div className="flex items-center gap-1 text-xs">
                    <button type="button" disabled={currentPage === 1} onClick={() => setCurrentPage((page) => Math.max(1, page - 1))} className="inline-flex items-center gap-1 rounded-[8px] border border-slate-200 bg-white px-2 py-1 text-slate-700 disabled:cursor-not-allowed disabled:opacity-50">
                      <ChevronLeft className="h-3.5 w-3.5" />
                      Prev
                    </button>
                    {[...Array(totalPages)].slice(0, 5).map((_, index) => {
                      const pageNumber = index + 1;
                      const isActive = currentPage === pageNumber;
                      return (
                        <button
                          key={pageNumber}
                          type="button"
                          onClick={() => setCurrentPage(pageNumber)}
                          className={`h-8 min-w-[2rem] rounded-[8px] border px-2 text-xs font-semibold ${isActive ? 'border-[#1D3557] bg-[#1D3557] text-white' : 'border-slate-200 bg-white text-slate-700'}`}
                        >
                          {pageNumber}
                        </button>
                      );
                    })}
                    <button type="button" disabled={currentPage === totalPages} onClick={() => setCurrentPage((page) => Math.min(totalPages, page + 1))} className="inline-flex items-center gap-1 rounded-[8px] border border-slate-200 bg-white px-2 py-1 text-slate-700 disabled:cursor-not-allowed disabled:opacity-50">
                      Next
                      <ChevronRight className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </div>
              </div>
            )}
          </section>
        )}
      </div>

      <Modal
        title="Allocation Details"
        isOpen={Boolean(viewRow)}
        onClose={() => setViewRow(null)}
      >
        {viewRow ? (
          <div className="grid gap-4 md:grid-cols-2">
            {[
              ['College', viewRow.college],
              ['Course', viewRow.course],
              ['Semester', viewRow.semester],
              ['Section', viewRow.section],
              ['Subject', viewRow.subject],
              ['Subject Code', viewRow.subjectCode],
              ['Faculty', viewRow.faculty],
              ['Academic Year', viewRow.academicYear],
              ['Status', viewRow.status],
              ['Created Date', viewRow.createdDate],
              ['Updated Date', viewRow.updatedDate],
            ].map(([label, value]) => (
              <div key={label} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.2em] text-slate-500">{label}</p>
                <p className="mt-2 text-sm font-medium text-slate-900">{value || '—'}</p>
              </div>
            ))}
          </div>
        ) : null}
      </Modal>

      <Modal
        title="Edit Allocation"
        isOpen={Boolean(editRow)}
        onClose={() => {
          setEditRow(null);
          setFormError('');
        }}
        footer={(
          <>
            <button type="button" onClick={() => {
              setEditRow(null);
              setFormError('');
            }} className="rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700">Cancel</button>
            <button type="submit" form="allocate-subject-edit-form" className="rounded-2xl bg-slate-900 px-4 py-2 text-sm font-semibold text-white">Save</button>
          </>
        )}
      >
        {editRow ? (
          <form id="allocate-subject-edit-form" onSubmit={handleSaveEdit} className="space-y-4">
            {formError ? <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{formError}</div> : null}
            <div className="grid gap-4 md:grid-cols-2">
              <label className="space-y-2 text-sm text-slate-700">
                <span className="font-semibold">Subject</span>
                <input value={formState.subject} onChange={(event) => setFormState((current) => ({ ...current, subject: event.target.value }))} className="h-11 w-full rounded-2xl border border-slate-200 px-3 outline-none" required />
              </label>
              <label className="space-y-2 text-sm text-slate-700">
                <span className="font-semibold">Faculty</span>
                <input value={formState.faculty} onChange={(event) => setFormState((current) => ({ ...current, faculty: event.target.value }))} className="h-11 w-full rounded-2xl border border-slate-200 px-3 outline-none" required />
              </label>
              <label className="space-y-2 text-sm text-slate-700">
                <span className="font-semibold">Status</span>
                <select value={formState.status} onChange={(event) => setFormState((current) => ({ ...current, status: event.target.value }))} className="h-11 w-full rounded-2xl border border-slate-200 px-3 outline-none">
                  <option value="Allocated">Allocated</option>
                  <option value="Pending">Pending</option>
                  <option value="Updated">Updated</option>
                </select>
              </label>
              <label className="space-y-2 text-sm text-slate-700">
                <span className="font-semibold">Section</span>
                <input value={formState.section} onChange={(event) => setFormState((current) => ({ ...current, section: event.target.value }))} className="h-11 w-full rounded-2xl border border-slate-200 px-3 outline-none" required />
              </label>
              <label className="space-y-2 text-sm text-slate-700">
                <span className="font-semibold">Semester</span>
                <input value={formState.semester} onChange={(event) => setFormState((current) => ({ ...current, semester: event.target.value }))} className="h-11 w-full rounded-2xl border border-slate-200 px-3 outline-none" required />
              </label>
              <label className="space-y-2 text-sm text-slate-700">
                <span className="font-semibold">Course</span>
                <input value={formState.course} onChange={(event) => setFormState((current) => ({ ...current, course: event.target.value }))} className="h-11 w-full rounded-2xl border border-slate-200 px-3 outline-none" required />
              </label>
            </div>
          </form>
        ) : null}
      </Modal>

      <ConfirmDialog
        open={Boolean(deleteRow)}
        title="Delete allocation"
        description={`Are you sure you want to delete the allocation for ${deleteRow?.subject || 'this subject'}?`}
        confirmLabel="Delete"
        onCancel={() => setDeleteRow(null)}
        onConfirm={handleDeleteConfirm}
      />
    </div>
  );
}

import { useEffect, useState, useRef } from 'react';
import { ArrowLeft, Copy, Plus, ChevronDown, Filter, Eye, Edit2, Trash2 } from 'lucide-react';
import Breadcrumb from '../components/ui/Breadcrumb.jsx';

const STORAGE_KEY = 'assessmentMasterRows';

const assessments = [
  { id: 'SCH', name: 'Scholastic Assessment', code: 'SCH', type: 'SCHOLASTIC', description: 'Scholastic assessment activities', createdOn: '15 May 2026', status: 'Active' },
  { id: 'CO-SCH', name: 'Co-Scholastic Assessment', code: 'CO-SCH', type: 'CO-SCHOLASTIC', description: 'Co-scholastic assessment activities', createdOn: '15 May 2026', status: 'Active' },
  { id: 'DIS', name: 'Discipline Assessment', code: 'DIS', type: 'DISCIPLINE', description: 'Discipline related assessment', createdOn: '16 May 2026', status: 'Active' },
  { id: 'SKL', name: 'Skill Assessment', code: 'SKL', type: 'SKILL', description: 'Skill based assessment', createdOn: '16 May 2026', status: 'Active' },
  { id: 'MAJ', name: 'Major Assessment', code: 'MAJ', type: 'MAJOR', description: 'Major subject assessment', createdOn: '17 May 2026', status: 'Active' },
  { id: 'MIN', name: 'Minor Assessment', code: 'MIN', type: 'MINOR', description: 'Minor subject assessment', createdOn: '17 May 2026', status: 'Active' },
  { id: 'MDC', name: 'MDC Assessment', code: 'MDC', type: 'MDC', description: 'Multidisciplinary course assessment', createdOn: '18 May 2026', status: 'Active' },
  { id: 'SEC', name: 'SEC Assessment', code: 'SEC', type: 'SEC', description: 'Skill enhancement course assessment', createdOn: '18 May 2026', status: 'Active' },
  { id: 'VAC', name: 'VAC Assessment', code: 'VAC', type: 'VAC', description: 'Value added course assessment', createdOn: '19 May 2026', status: 'Active' },
  { id: 'AEC', name: 'AEC Assessment', code: 'AEC', type: 'AEC', description: 'Ability enhancement course assessment', createdOn: '19 May 2026', status: 'Active' },
  { id: 'VOC', name: 'VOC Assessment', code: 'VOC', type: 'VOC', description: 'Vocational course assessment', createdOn: '20 May 2026', status: 'Active' },
];

const TYPE_OPTIONS = [
  { emoji: '📘', value: 'SCHOLASTIC' },
  { emoji: '👥', value: 'CO-SCHOLASTIC' },
  { emoji: '🛡', value: 'DISCIPLINE' },
  { emoji: '⚙', value: 'SKILL' },
  { emoji: '⭐', value: 'MAJOR' },
  { emoji: '📗', value: 'MINOR' },
  { emoji: '🎓', value: 'MDC' },
  { emoji: '🛡', value: 'SEC' },
  { emoji: '✈', value: 'VAC' },
  { emoji: '✏', value: 'AEC' },
  { emoji: '🎤', value: 'VOC' },
];

const createId = () => `asses-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

const getInitialRows = () => {
  if (typeof window !== 'undefined') {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored) {
      try {
        return JSON.parse(stored);
      } catch (error) {
        return assessments;
      }
    }
  }
  return assessments;
};


export default function AssessmentMasterPage() {
  const [query, setQuery] = useState('');
  const [openAddMenu, setOpenAddMenu] = useState(false);
  const [openInlineForm, setOpenInlineForm] = useState(false);
  const [form, setForm] = useState({ name: '', type: '' });
  const [typeFilter, setTypeFilter] = useState('');
  const [editingId, setEditingId] = useState(null);
  const [rows, setRows] = useState(getInitialRows);
  const closeTimerRef = useRef(null);

  useEffect(() => {
    // Hide the global BackNavigationButton to keep only the in-page back button
    const selector = '.erp-content-wrapper > .pt-1 > .mb-3';
    const el = document.querySelector(selector);
    let prevDisplay;
    if (el) {
      prevDisplay = el.style.display;
      el.style.display = 'none';
    }
    return () => { if (el) el.style.display = prevDisplay || ''; };
  }, []);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(rows));
    }
  }, [rows]);

  const filteredRows = rows.filter((row) => {
    const search = query.trim().toLowerCase();
    if (!search) return true;
    return [row.name, row.code, row.type, row.description, row.status, row.createdOn]
      .some((value) => value.toLowerCase().includes(search));
  });

  return (
    <div className="min-h-screen w-full min-w-0 px-[12px] pb-8 pt-4 lg:px-6">
      <div className="flex items-start justify-between gap-4 mb-6">
        <div className="flex items-start gap-4">
          <button type="button" className="inline-flex h-10 w-10 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-700 hover:bg-slate-50">
            <ArrowLeft className="h-4 w-4" />
          </button>
          <div>
            <Breadcrumb items={[{ label: 'Dashboard', to: '/' }, { label: 'Academics Setup', to: '/settings/academics' }, { label: 'Assessment', to: '/settings/assessment' }, { label: 'Assessment Master' }]} />
            <div className="flex items-baseline gap-3">
              <h1 className="text-3xl font-semibold text-slate-900">Assessment Master</h1>
              <span className="text-sm text-slate-500">Assessment Master</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button type="button" className="inline-flex items-center gap-2 rounded-[10px] bg-slate-900 px-4 py-2 text-sm font-semibold text-white hover:bg-slate-800 transition">
            <Copy className="h-4 w-4" /> Copy
          </button>
        </div>
      </div>

      <div className="rounded-[12px] border border-slate-200 bg-white p-5 shadow-sm">
        <div className="flex items-center justify-between gap-4 mb-6">
          <div className="relative w-full">
            <button
              type="button"
              onClick={() => setOpenInlineForm((s) => !s)}
              className="inline-flex items-center gap-2 rounded-lg bg-[#08203a] px-4 py-2 text-sm font-semibold text-white shadow-md hover:opacity-95 transition"
            >
              <Plus className="h-4 w-4" /> Add New Details <ChevronDown className="h-4 w-4 text-white/80" />
            </button>

            {/* Inline expandable form */}
            <div className={`mt-4 overflow-visible transition-all duration-300 ${openInlineForm ? 'max-h-[220px] opacity-100' : 'max-h-0 opacity-0'}`}>
              <div className="rounded-md border border-slate-200 bg-white p-3 shadow-sm">
                <form
                  onSubmit={(e) => {
                    e.preventDefault();
                    if (!form.name || !form.type) return;
                    if (editingId) {
                      setRows((r) => r.map((row) => (row.id === editingId ? { ...row, name: form.name, type: form.type, description: `${form.name} - ${form.type} description` } : row)));
                      setEditingId(null);
                    } else {
                      const newCode = form.type.replace(/[^A-Z]/g, '').slice(0, 6) || 'NEW';
                      const newRow = {
                        id: createId(),
                        name: form.name,
                        code: newCode,
                        type: form.type,
                        description: `${form.name} - ${form.type} description`,
                        createdOn: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
                        status: 'Active',
                      };
                      setRows((r) => [newRow, ...r]);
                    }
                    setForm({ name: '', type: '' });
                    setTypeFilter('');
                    setOpenInlineForm(false);
                  }}
                >
                  <div className="flex flex-wrap items-center gap-3">
                    <div className="flex-1 min-w-[200px]">
                      <label className="block text-xs font-medium text-slate-600 mb-1">Assessment Name *</label>
                      <input
                        value={form.name}
                        onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
                        placeholder="Enter Assessment Name"
                        className="h-10 w-full rounded-md border border-slate-200 bg-white px-3 text-sm placeholder-slate-400 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500"
                      />
                    </div>

                    <div className="w-[260px] min-w-[160px]">
                      <label className="block text-xs font-medium text-slate-600 mb-1">Assessment Type *</label>
                      <div
                        className="relative"
                        onMouseEnter={() => {
                          if (closeTimerRef.current) { clearTimeout(closeTimerRef.current); closeTimerRef.current = null; }
                          setOpenAddMenu(true);
                        }}
                        onMouseLeave={() => {
                          if (closeTimerRef.current) clearTimeout(closeTimerRef.current);
                          closeTimerRef.current = setTimeout(() => { setOpenAddMenu(false); closeTimerRef.current = null; }, 180);
                        }}
                      >
                        <input
                          value={typeFilter || form.type}
                          onChange={(e) => { setTypeFilter(e.target.value); }}
                          onFocus={() => setOpenAddMenu(true)}
                          placeholder="Select type"
                          className="h-10 w-full rounded-md border border-slate-200 bg-white pl-3 pr-10 text-sm placeholder-slate-400 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500"
                        />
                        <div className="absolute inset-y-0 right-2 flex items-center pointer-events-none">
                          <ChevronDown className="h-4 w-4 text-slate-400" />
                        </div>

                        <div className={`absolute left-0 right-0 mt-10 z-30 rounded-md bg-white shadow-lg ring-1 ring-black ring-opacity-5 ${openAddMenu ? '' : 'hidden'}`}>
                          <div className="max-h-40 overflow-auto py-1">
                            {TYPE_OPTIONS
                              .filter((opt) => (typeFilter ? opt.value.toLowerCase().includes(typeFilter.toLowerCase()) : true))
                              .map((opt) => (
                                <button key={opt.value} type="button" onClick={() => { setForm((f) => ({ ...f, type: opt.value })); setTypeFilter(''); setOpenAddMenu(false); }} className="w-full text-left px-3 py-2 text-sm hover:bg-slate-50 flex items-center gap-3">
                                  <span className="inline-flex h-6 w-6 items-center justify-center rounded-md bg-slate-100 text-sm">{opt.emoji}</span>
                                  <span>{opt.value}</span>
                                </button>
                              ))}
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 ml-auto">
                      <button type="submit" className="inline-flex items-center gap-2 rounded-md bg-emerald-600 px-4 py-2 text-sm font-semibold text-white hover:bg-emerald-700 transition">
                        <span className="text-lg">💾</span> Save
                      </button>
                      <button type="button" onClick={() => { setEditingId(null); setForm({ name: '', type: '' }); setTypeFilter(''); }} className="inline-flex h-10 w-10 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-700 hover:bg-slate-50">
                        <Trash2 className="h-4 w-4 text-rose-500" />
                      </button>
                    </div>
                  </div>
                </form>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 ml-auto">
            <div>
              <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search assessment..." className="h-10 w-[320px] rounded-md border border-slate-200 bg-white px-3 text-sm placeholder-slate-400 focus:border-slate-400 focus:ring-1 focus:ring-slate-200" />
            </div>
            <button type="button" className="inline-flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700 hover:bg-slate-50">
              <Filter className="h-4 w-4" /> Filter
            </button>
          </div>
        </div>

        {/* Data Table */}
        <div className="overflow-x-auto">
          <table className="min-w-full table-auto border-collapse">
            <thead>
              <tr className="bg-[#08203a] text-white rounded-t-lg">
                <th className="px-4 py-3 text-left text-sm font-semibold">#</th>
                <th className="px-4 py-3 text-left text-sm font-semibold">NAME</th>
                <th className="px-4 py-3 text-left text-sm font-semibold">CODE</th>
                <th className="px-4 py-3 text-left text-sm font-semibold">TYPE</th>
                <th className="px-4 py-3 text-left text-sm font-semibold">DESCRIPTION</th>
                <th className="px-4 py-3 text-left text-sm font-semibold">STATUS</th>
                <th className="px-4 py-3 text-left text-sm font-semibold">CREATED ON</th>
                <th className="px-4 py-3 text-center text-sm font-semibold">ACTIONS</th>
              </tr>
            </thead>
            <tbody className="bg-white">
              {filteredRows.map((row, idx) => (
                <tr key={row.id} className="border-t border-slate-100 align-top">
                      <td className="px-4 py-4 text-sm text-slate-700">{idx + 1}</td>
                  <td className="px-4 py-4 text-sm font-medium text-slate-900">{row.name}</td>
                  <td className="px-4 py-4 text-sm">
                    <span className="inline-flex items-center justify-center rounded-md bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-700">{row.code}</span>
                  </td>
                  <td className="px-4 py-4 text-sm text-slate-700">{row.type}</td>
                  <td className="px-4 py-4 text-sm text-slate-600">{row.description}</td>
                  <td className="px-4 py-4">
                    <span className="inline-flex items-center gap-2 rounded-full bg-emerald-100 px-3 py-1 text-sm font-medium text-emerald-800">
                      <span className="h-2 w-2 rounded-full bg-emerald-600 inline-block" />
                      {row.status}
                    </span>
                  </td>
                  <td className="px-4 py-4 text-sm text-slate-600">{row.createdOn}</td>
                  <td className="px-4 py-4 text-sm text-center">
                    <div className="inline-flex items-center gap-2 justify-center">
                      <button type="button" onClick={() => { /* view currently no-op */ }} className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-white border border-slate-100 shadow-sm text-[#1E293B] hover:bg-blue-50">
                        <Eye className="h-4 w-4" />
                      </button>
                      <button type="button" onClick={() => { setForm({ name: row.name, type: row.type }); setOpenInlineForm(true); setEditingId(row.id); }} className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-white border border-slate-100 shadow-sm text-[#1E293B] hover:bg-emerald-50">
                        <Edit2 className="h-4 w-4" />
                      </button>
                      <button type="button" onClick={() => { if (window.confirm('Delete this assessment?')) setRows((r) => r.filter((x) => x.id !== row.id)); }} className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-white border border-slate-100 shadow-sm text-[#EF4444] hover:bg-rose-50">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Footer */}
        <div className="mt-6 flex items-center justify-between">
          <div className="text-sm text-slate-600">Showing 1 to {filteredRows.length} of {rows.length} entries</div>
          <div className="inline-flex items-center gap-2">
            <button className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-700">&lt;</button>
            <button className="inline-flex h-9 w-9 items-center justify-center rounded-md bg-[#08203a] text-white">1</button>
            <button className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-700">&gt;</button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { FaFileUpload, FaPlus } from 'react-icons/fa';
import { useForm } from 'react-hook-form';
import { useResourceList, useCreateResource } from '../hooks/useResourceHooks';
import SectionHeader from '../components/ui/SectionHeader.jsx';
import WithPermission from '../components/auth/WithPermission.jsx';
import SearchFilter from '../components/forms/SearchFilter.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import TablePagination from '../components/tables/TablePagination.jsx';
import Modal from '../components/ui/Modal.jsx';
import FormField from '../components/forms/FormField.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';
import Button from '../components/ui/Button.jsx';
const statusOptions = [
  { value: 'All', label: 'All statuses' },
  { value: 'Open', label: 'Open' },
  { value: 'Closed', label: 'Closed' },
  { value: 'Review', label: 'In Review' },
];
export default function AssignmentsPage() {
  const { data: assignmentsData } = useResourceList('assignments', { page: 1, pageSize: 200 });
  const assignments = assignmentsData?.items || [];
  const createAssignment = useCreateResource('assignments');
  const { data: coursesData } = useResourceList('courses', { page: 1, pageSize: 200 });
  const courses = coursesData?.items || [];
  const { data: semestersData } = useResourceList('semesters', { page: 1, pageSize: 200 });
  const semesters = semestersData?.items || [];
  const { data: sectionsData } = useResourceList('sections', { page: 1, pageSize: 200 });
  const sections = sectionsData?.items || [];
  const { data: teachersData } = useResourceList('teachers', { page: 1, pageSize: 200 });
  const teachers = teachersData?.items || [];
  const { data: subjectsData } = useResourceList('subjects', { page: 1, pageSize: 200 });
  const subjects = subjectsData?.items || [];
  const subjectMap = new Map((subjects || []).map((s) => [s.id, s]));
  const courseMap = new Map((courses || []).map((c) => [c.id, c]));
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [page, setPage] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const pageSize = 5;
  const initialValues = {
    title: '',
    subject: '',
    course: courses[0]?.title || '',
    semester: semesters[0]?.title || '',
    section: sections[0]?.name || 'A',
    setBy: teachers[0]?.name || '',
    dueDate: '',
    maxScore: '10',
    status: 'Open',
  };
  const { register, handleSubmit, reset, formState: { errors } } = useForm({ defaultValues: initialValues });
  const filteredAssignments = useMemo(() => {
    return assignments.filter((assignment) => {
      const searchTerm = search.toLowerCase();
      const subjectName = subjectMap.get(assignment.subjectId)?.title || '';
      const courseName = courseMap.get(assignment.courseId)?.title || '';
      const matchesSearch = [assignment.title, subjectName, courseName].some((value) => value.toLowerCase().includes(searchTerm));
      const matchesFilter = filter === 'All' || assignment.status === filter;
      return matchesSearch && matchesFilter;
    });
  }, [assignments, search, filter, subjectMap, courseMap]);
  const pageCount = Math.max(1, Math.ceil(filteredAssignments.length / pageSize));
  const displayedAssignments = filteredAssignments.slice((page - 1) * pageSize, page * pageSize);
  const resetForm = () => reset({ title: '', subject: '', course: courses[0]?.title || '', semester: semesters[0]?.title || '', section: sections[0]?.name || 'A', setBy: teachers[0]?.name || '', dueDate: '', maxScore: '10', status: 'Open' });
  const onSubmit = (data) => {
    createAssignment({ ...data, status: data.status || 'Open', maxScore: Number(data.maxScore) || 0 });
    resetForm();
    setPage(1);
    setIsModalOpen(false);
  };
  const totalAssignments = assignments.length;
  const openAssignments = assignments.filter((a) => a.status === 'Open').length;
  const closedAssignments = assignments.filter((a) => a.status === 'Closed').length;
  return (
    <div className="space-y-6">
      <SectionHeader title="Assignments" subtitle="Create and manage course assignments, track submissions and grade work." />
      <div className="grid gap-3 md:grid-cols-3">
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Total assignments</p>
          <p className="mt-3 text-2xl font-semibold text-white">{totalAssignments}</p>
        </div>
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Open</p>
          <p className="mt-3 text-2xl font-semibold text-white">{openAssignments}</p>
        </div>
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Closed</p>
          <p className="mt-3 text-2xl font-semibold text-white">{closedAssignments}</p>
        </div>
      </div>
      <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
        <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h2 className="text-lg font-semibold text-white">Assignment library</h2>
            <p className="text-sm text-slate-400">Create, manage and grade assignments across all courses.</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <WithPermission moduleKey="assignments" action="import">
              <Button variant="secondary" className="inline-flex items-center gap-2 px-3 py-2 text-sm hover-gradient-border"><FaFileUpload /> Import</Button>
            </WithPermission>
            <WithPermission moduleKey="assignments" action="create">
              <Button onClick={() => setIsModalOpen(true)} variant="primary" className="inline-flex items-center gap-2 px-3 py-2 text-sm"><FaPlus /> New assignment</Button>
            </WithPermission>
          </div>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2"><SearchFilter search={search} onSearch={setSearch} filter={filter} onFilter={setFilter} options={statusOptions} /></div>
        <div className="mt-4">
          <DataTable
            columns={['Title', 'Subject', 'Course', 'Due Date', 'Submitted', 'Max Score', 'Status']}
            rows={displayedAssignments.map((assignment) => {
              const subject = subjectMap.get(assignment.subjectId);
              const course = courseMap.get(assignment.courseId);
              return [
                <div key={assignment.id} className="font-semibold text-white">{assignment.title}</div>,
                subject?.title || 'Unknown',
                course?.title || 'Unknown',
                assignment.dueDate,
                assignment.submissionCount ?? 0,
                assignment.maxScore,
                <StatusBadge key={`${assignment.id}-status`} status={assignment.status} />,
              ];
            })}
          />
        </div>
        <div className="mt-4"><TablePagination page={page} pageCount={pageCount} onPageChange={setPage} /></div>
      </div>
      <Modal title="Create new assignment" isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} footer={<Button onClick={handleSubmit(onSubmit)} variant="primary" >Create assignment</Button>}>
        <form className="grid gap-5 lg:grid-cols-2">
          <FormField label="Title"><input type="text" {...register('title', { required: 'Title is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="Implement Stack using Arrays" />{errors.title && <p className="mt-1 text-sm text-rose-400">{errors.title.message}</p>}</FormField>
          <FormField label="Subject"><input type="text" {...register('subject', { required: 'Subject is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="Data Structures" />{errors.subject && <p className="mt-1 text-sm text-rose-400">{errors.subject.message}</p>}</FormField>
          <FormField label="Course"><input type="text" {...register('course')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="BCA" /></FormField>
          <FormField label="Semester"><input type="text" {...register('semester')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="5" /></FormField>
          <FormField label="Section"><select {...register('section')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"><option value="A">A</option><option value="B">B</option><option value="C">C</option></select></FormField>
          <FormField label="Set by"><input type="text" {...register('setBy', { required: 'Setter is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="Dr. Priya Menon" />{errors.setBy && <p className="mt-1 text-sm text-rose-400">{errors.setBy.message}</p>}</FormField>
          <FormField label="Due date"><input type="date" {...register('dueDate', { required: 'Due date is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />{errors.dueDate && <p className="mt-1 text-sm text-rose-400">{errors.dueDate.message}</p>}</FormField>
          <FormField label="Max score"><input type="number" {...register('maxScore', { required: 'Max score is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="10" />{errors.maxScore && <p className="mt-1 text-sm text-rose-400">{errors.maxScore.message}</p>}</FormField>
          <FormField label="Status"><select {...register('status')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"><option value="Open">Open</option><option value="Closed">Closed</option><option value="Review">In Review</option></select></FormField>
        </form>
      </Modal>
    </div>
  );
}

