      bullets: ['Credit values should match the prescribed scheme.', 'Higher credits usually indicate greater instructional workload.', 'Review credits before publishing the final academic calendar.'],
    },
  },
];

function getStatusClasses(status) {
  if (status === 'Active') {
    return 'bg-emerald-100 text-emerald-700';
  }
  if (status === 'Inactive') {
    return 'bg-slate-100 text-slate-700';
  }
  if (status === 'Archived') {
    return 'bg-rose-100 text-rose-700';
  }
  return 'bg-amber-100 text-amber-700';
}

const emptyForm = {
  name: '',
  code: '',
  department: 'Computer Science',
  program: '',
  duration: '',
  semesters: '',
  eligibility: '',
  credits: '',
  status: 'Active',
  description: '',
};

export default function CourseManagementPage() {
  const navigate = useNavigate();
  const [courses, setCourses] = useState(initialCourses);
  const [search, setSearch] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('All Departments');
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [isHelperOpen, setIsHelperOpen] = useState(false);
  const [helperContent, setHelperContent] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [formErrors, setFormErrors] = useState({});
  const [isEditMode, setIsEditMode] = useState(false);

  const filteredCourses = useMemo(() => {
    const query = search.toLowerCase();
    return courses.filter((course) => {
      const matchesSearch = [course.code, course.name, course.department, course.program].some((value) => value.toLowerCase().includes(query));
      const matchesDepartment = departmentFilter === 'All Departments' || course.department === departmentFilter;
      return matchesSearch && matchesDepartment;
    });
  }, [courses, search, departmentFilter]);

  const openCreateModal = () => {
    setForm(emptyForm);
    setFormErrors({});
    setIsEditMode(false);
    setSelectedCourse(null);
    setIsCreateOpen(true);
  };

  const openViewModal = (course) => {
    setSelectedCourse(course);
    setIsEditMode(false);
    setFormErrors({});
  };

  const openHelperModal = (item) => {
    setHelperContent(item);
    setIsHelperOpen(true);
  };

  const handleCreateSubmit = (event) => {
    event.preventDefault();
    const nextErrors = {};
    ['name', 'code', 'department', 'program', 'duration', 'semesters', 'eligibility', 'credits', 'status', 'description'].forEach((field) => {
      if (!form[field].trim()) {
        nextErrors[field] = 'This field is required';
      }
    });

    if (Object.keys(nextErrors).length > 0) {
      setFormErrors(nextErrors);
      return;
    }

    const newCourse = {
      ...form,
      code: form.code.toUpperCase(),
      name: form.name,
      department: form.department,
      program: form.program,
      duration: form.duration,
      semesters: form.semesters,
      eligibility: form.eligibility,
      credits: form.credits,
      status: form.status,
      description: form.description,
    };

    setCourses((current) => [newCourse, ...current]);
    setIsCreateOpen(false);
    setForm(emptyForm);
    setFormErrors({});
  };

  const handleEditSubmit = (event) => {
    event.preventDefault();
    const nextErrors = {};
    ['name', 'code', 'department', 'program', 'duration', 'semesters', 'eligibility', 'credits', 'status', 'description'].forEach((field) => {
      if (!form[field].trim()) {
        nextErrors[field] = 'This field is required';
      }
    });

    if (Object.keys(nextErrors).length > 0) {
      setFormErrors(nextErrors);
      return;
    }

    setCourses((current) => current.map((course) => (course.code === selectedCourse.code ? { ...course, ...form, code: form.code.toUpperCase() } : course)));
    setSelectedCourse(null);
    setIsEditMode(false);
    setForm(emptyForm);
    setFormErrors({});
  };

  const startEdit = () => {
    if (!selectedCourse) {
      return;
    }
    setForm({
      name: selectedCourse.name,
      code: selectedCourse.code,
      department: selectedCourse.department,
      program: selectedCourse.program,
      duration: selectedCourse.duration,
      semesters: selectedCourse.semesters,
      eligibility: selectedCourse.eligibility,
      credits: selectedCourse.credits,
      status: selectedCourse.status,
      description: selectedCourse.description,
    });
    setIsEditMode(true);
    setFormErrors({});
  };

  return (
    <div className="space-y-6">
      <div className="rounded-[28px] border border-slate-200/80 bg-white p-6 shadow-sm">
        <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <div className="mt-3">
              <Breadcrumb
                items={[
                  { label: 'Settings', to: '/settings' },
                  { label: 'Institute Setup', to: '/settings/institute' },
                  { label: 'Courses' },
                ]}
              />
            </div>
            <div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <p className="text-xs uppercase tracking-[0.28em] text-emerald-600">Institute setup</p>
                <h1 className="mt-2 text-3xl font-semibold tracking-tight text-slate-900">Course Management</h1>
                <p className="mt-2 max-w-2xl text-sm text-slate-500">
                  Manage courses, programs, departments, duration and academic structure from one centralized workspace.
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <section className="rounded-[28px] border border-slate-200/80 bg-white p-6 shadow-sm">
          <div className="flex items-center gap-3 text-slate-900">
            <BookOpen className="h-5 w-5 text-emerald-600" />
            <h3 className="text-lg font-semibold">Course helpers</h3>
          </div>
          <div className="mt-4 grid gap-4 lg:grid-cols-2 2xl:grid-cols-4">
            {helpers.map((item) => {
              const Icon = item.icon;
              return (
                <button
                  key={item.title}
                  type="button"
                  onClick={() => openHelperModal(item)}
                  className="flex h-full items-center justify-between rounded-2xl border border-slate-200 bg-slate-50/70 p-4 text-left transition hover-gradient-border"
                >
                  <div className="flex items-center gap-3">
                    <div className="flex h-9 w-9 items-center justify-center rounded-2xl bg-emerald-50 text-emerald-700">
                      <Icon className="h-4 w-4" />
                    </div>
                    <div>
                      <p className="font-semibold text-slate-900">{item.title}</p>
                      <p className="mt-1 text-sm text-slate-600">{item.description}</p>
                    </div>
                  </div>
                  <ChevronLeft className="ml-3 h-4 w-4 rotate-180 text-slate-400" />
                </button>
              );
            })}
          </div>
        </section>

        <section className="rounded-[28px] border border-slate-200/80 bg-white p-6 shadow-sm">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="text-sm font-semibold uppercase tracking-[0.22em] text-slate-500">Course overview</p>
              <h2 className="mt-2 text-2xl font-semibold text-slate-900">Available Courses</h2>
            </div>
            <button
              type="button"
              onClick={openCreateModal}
              className="inline-flex items-center gap-2 rounded-2xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-emerald-500 hover-gradient-border"
            >
              <Plus className="h-4 w-4" /> Add Course
            </button>
          </div>

          <div className="mt-5 flex flex-col gap-3 rounded-2xl border border-slate-200 bg-slate-50/70 p-3 md:flex-row md:items-center md:justify-between">
            <label className="flex items-center gap-2 rounded-2xl border border-slate-200 bg-white px-3 py-2 text-sm text-slate-600 shadow-sm hover-gradient-border">
              <Search className="h-4 w-4 text-slate-400" />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search course"
                className="w-full bg-transparent outline-none sm:w-48"
              />
            </label>
            <select
              value={departmentFilter}
              onChange={(event) => setDepartmentFilter(event.target.value)}
              className="rounded-2xl border border-slate-200 bg-white px-3 py-2 text-sm text-slate-600 shadow-sm outline-none hover-gradient-border"
            >
              <option>All Departments</option>
              <option>Computer Science</option>
              <option>Management</option>
              <option>Engineering</option>
              <option>Commerce</option>
              <option>Humanities</option>
              <option>Agriculture</option>
              <option>Pharmacy</option>
              <option>Law</option>
              <option>Education</option>
            </select>
          </div>

          <div className="mt-6 overflow-x-auto rounded-3xl border border-slate-200">
            <table className="min-w-full divide-y divide-slate-200 text-sm text-slate-700">
              <thead>
                <tr className="bg-emerald-600 text-left uppercase tracking-[0.12em] text-white">
                  <th className="px-4 py-4">Course Code</th>
                  <th className="px-4 py-4">Course Name</th>
                  <th className="px-4 py-4">Department</th>
                  <th className="px-4 py-4">Program</th>
                  <th className="px-4 py-4">Duration</th>
                  <th className="px-4 py-4">Semesters</th>
                  <th className="px-4 py-4">Status</th>
                  <th className="px-4 py-4">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 bg-white text-sm">
                {filteredCourses.map((course, index) => (
                  <tr key={`${course.code}-${index}`} className={index % 2 === 0 ? 'bg-slate-50' : 'bg-white'}>
                    <td className="whitespace-nowrap px-4 py-4 font-medium text-slate-900">{course.code}</td>
                    <td className="px-4 py-4 text-slate-700">{course.name}</td>
                    <td className="whitespace-nowrap px-4 py-4">{course.department}</td>
                    <td className="whitespace-nowrap px-4 py-4">{course.program}</td>
                    <td className="whitespace-nowrap px-4 py-4">{course.duration}</td>
                    <td className="whitespace-nowrap px-4 py-4">{course.semesters}</td>
                    <td className="whitespace-nowrap px-4 py-4 text-sm font-semibold text-slate-900">
                      <span className={`inline-flex items-center justify-center rounded-full px-2.5 py-0.5 text-[11px] font-medium ${getStatusClasses(course.status)}`}>
                        {course.status}
                      </span>
                    </td>
                    <td className="whitespace-nowrap px-4 py-4">
                      <button
                        type="button"
                        onClick={() => openViewModal(course)}
                        className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 transition hover:bg-slate-50 hover-gradient-border"
                      >
                        View
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

      </div>

      {isCreateOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-2xl rounded-[28px] border border-slate-200 bg-white p-6 shadow-2xl">
            <div className="flex items-center justify-between gap-3">
              <div>
                <p className="text-sm font-semibold uppercase tracking-[0.24em] text-emerald-600">Course setup</p>
                <h3 className="mt-1 text-xl font-semibold text-slate-900">Add course</h3>
              </div>
              <button
                type="button"
                onClick={() => {
                  setIsCreateOpen(false);
                  setForm(emptyForm);
                  setFormErrors({});
                }}
                className="rounded-full border border-slate-200 bg-slate-50 p-2 text-slate-600 transition hover:bg-slate-100 hover-gradient-border"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            <form className="mt-6 grid gap-4 md:grid-cols-2" onSubmit={handleCreateSubmit}>
              {[
                ['name', 'Course Name'],
                ['code', 'Course Code'],
                ['department', 'Department'],
                ['program', 'Program'],
                ['duration', 'Duration'],
                ['semesters', 'Semesters'],
                ['eligibility', 'Eligibility'],
                ['credits', 'Credits'],
              ].map(([field, label]) => (
                <label key={field} className="text-sm font-medium text-slate-700">
                  {label}
                  <input
                    value={form[field]}
                    onChange={(event) => setForm((current) => ({ ...current, [field]: event.target.value }))}
                    className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none hover-gradient-border"
                  />
                  {formErrors[field] ? <p className="mt-1 text-xs text-rose-500">{formErrors[field]}</p> : null}
                </label>
              ))}

              <label className="text-sm font-medium text-slate-700 md:col-span-2">
                Status
                <select
                  value={form.status}
                  onChange={(event) => setForm((current) => ({ ...current, status: event.target.value }))}
                  className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none hover-gradient-border"
                >
                  <option value="Active">Active</option>
                  <option value="Inactive">Inactive</option>
                  <option value="Draft">Draft</option>
                  <option value="Archived">Archived</option>
                </select>
                {formErrors.status ? <p className="mt-1 text-xs text-rose-500">{formErrors.status}</p> : null}
              </label>

              <label className="text-sm font-medium text-slate-700 md:col-span-2">
                Description
                <textarea
                  value={form.description}
                  onChange={(event) => setForm((current) => ({ ...current, description: event.target.value }))}
                  rows="3"
                  className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none hover-gradient-border"
                />
                {formErrors.description ? <p className="mt-1 text-xs text-rose-500">{formErrors.description}</p> : null}
              </label>

              <div className="flex flex-wrap gap-3 md:col-span-2">
                <button type="submit" className="inline-flex items-center gap-2 rounded-2xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-emerald-500 hover-gradient-border">
                  <Plus className="h-4 w-4" /> Save
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setIsCreateOpen(false);
                    setForm(emptyForm);
                    setFormErrors({});
                  }}
                  className="inline-flex items-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 hover-gradient-border"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {selectedCourse && !isEditMode && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-2xl rounded-[28px] border border-slate-200 bg-white p-6 shadow-2xl">
            <div className="flex items-center justify-between gap-3">
              <div>
                <p className="text-sm font-semibold uppercase tracking-[0.24em] text-emerald-600">Course profile</p>
                <h3 className="mt-1 text-xl font-semibold text-slate-900">{selectedCourse.name}</h3>
              </div>
              <button
                type="button"
                onClick={() => setSelectedCourse(null)}
                className="rounded-full border border-slate-200 bg-slate-50 p-2 text-slate-600 transition hover:bg-slate-100 hover-gradient-border"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="mt-6 grid gap-4 md:grid-cols-2">
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Course code</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.code}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Department</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.department}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Program</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.program}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Duration</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.duration}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Semesters</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.semesters}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Eligibility</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.eligibility}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Credits</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.credits}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Status</p>
                <p className="mt-2 text-sm font-semibold text-slate-900">{selectedCourse.status}</p>
              </div>
              <div className="md:col-span-2 rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-500">Description</p>
                <p className="mt-2 text-sm text-slate-700">{selectedCourse.description}</p>
              </div>
            </div>

            <div className="mt-6 flex flex-wrap gap-3">
              <button type="button" onClick={startEdit} className="inline-flex items-center gap-2 rounded-2xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-emerald-500 hover-gradient-border">
                Edit
              </button>
              <button type="button" onClick={() => setSelectedCourse(null)} className="inline-flex items-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 hover-gradient-border">
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {selectedCourse && isEditMode && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-2xl rounded-[28px] border border-slate-200 bg-white p-6 shadow-2xl">
            <div className="flex items-center justify-between gap-3">
              <div>
                <p className="text-sm font-semibold uppercase tracking-[0.24em] text-emerald-600">Course edit</p>
                <h3 className="mt-1 text-xl font-semibold text-slate-900">Edit course</h3>
              </div>
              <button type="button" onClick={() => setIsEditMode(false)} className="rounded-full border border-slate-200 bg-slate-50 p-2 text-slate-600 transition hover:bg-slate-100 hover-gradient-border">
                <X className="h-4 w-4" />
              </button>
            </div>

            <form className="mt-6 grid gap-4 md:grid-cols-2" onSubmit={handleEditSubmit}>
              {[
                ['name', 'Course Name'],
                ['code', 'Course Code'],
                ['department', 'Department'],
                ['program', 'Program'],
                ['duration', 'Duration'],
                ['semesters', 'Semesters'],
                ['eligibility', 'Eligibility'],
                ['credits', 'Credits'],
              ].map(([field, label]) => (
                <label key={field} className="text-sm font-medium text-slate-700">
                  {label}
                  <input
                    value={form[field]}
                    onChange={(event) => setForm((current) => ({ ...current, [field]: event.target.value }))}
                    className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none hover-gradient-border"
                  />
                  {formErrors[field] ? <p className="mt-1 text-xs text-rose-500">{formErrors[field]}</p> : null}
                </label>
              ))}

              <label className="text-sm font-medium text-slate-700 md:col-span-2">
                Status
                <select
                  value={form.status}
                  onChange={(event) => setForm((current) => ({ ...current, status: event.target.value }))}
                  className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none hover-gradient-border"
                >
                  <option value="Active">Active</option>
                  <option value="Inactive">Inactive</option>
                  <option value="Draft">Draft</option>
                  <option value="Archived">Archived</option>
                </select>
                {formErrors.status ? <p className="mt-1 text-xs text-rose-500">{formErrors.status}</p> : null}
              </label>

              <label className="text-sm font-medium text-slate-700 md:col-span-2">
                Description
                <textarea
                  value={form.description}
                  onChange={(event) => setForm((current) => ({ ...current, description: event.target.value }))}
                  rows="3"
                  className="mt-1.5 w-full rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none hover-gradient-border"
                />
                {formErrors.description ? <p className="mt-1 text-xs text-rose-500">{formErrors.description}</p> : null}
              </label>

              <div className="flex flex-wrap gap-3 md:col-span-2">
                <button type="submit" className="inline-flex items-center gap-2 rounded-2xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-emerald-500 hover-gradient-border">
                  Save changes
                </button>
                <button type="button" onClick={() => setIsEditMode(false)} className="inline-flex items-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 hover-gradient-border">
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {helperContent && isHelperOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-xl rounded-[28px] border border-slate-200 bg-white p-6 shadow-2xl">
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-emerald-50 text-emerald-700">
                  {(() => {
                    const HelperIcon = helperContent.icon;
                    return <HelperIcon className="h-5 w-5" />;
                  })()}
                </div>
                <div>
                  <p className="text-sm font-semibold uppercase tracking-[0.24em] text-emerald-600">Course help</p>
                  <h3 className="mt-1 text-xl font-semibold text-slate-900">{helperContent.content.heading}</h3>
                </div>
              </div>
              <button type="button" onClick={() => setIsHelperOpen(false)} className="rounded-full border border-slate-200 bg-slate-50 p-2 text-slate-600 transition hover:bg-slate-100 hover-gradient-border">
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="mt-6 rounded-2xl border border-slate-200 bg-slate-50/70 p-4">
              <p className="text-sm text-slate-700">{helperContent.content.summary}</p>
              <ul className="mt-4 space-y-2 text-sm text-slate-600">
                {helperContent.content.bullets.map((bullet) => (
                  <li key={bullet} className="flex gap-2">
                    <span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-emerald-500" />
                    <span>{bullet}</span>
                  </li>
                ))}
              </ul>
            </div>

            <div className="mt-6 flex justify-end">
              <button type="button" onClick={() => setIsHelperOpen(false)} className="inline-flex items-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 hover-gradient-border">
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useMemo, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  GraduationCap,
  BookOpen,
  Briefcase,
  UserPlus,
  CalendarCheck,
  Star,
  IndianRupee,
  Users,
  FileWarning,
  Building2,
} from 'lucide-react';
import { useResourceList } from '../hooks/useResourceHooks';
import StudentOverviewDashboard from '../components/student/StudentOverviewDashboard.jsx';
import FeeDashboard from '../components/finance/FeeDashboard.jsx';
import AdmissionDashboard from '../components/admission/AdmissionDashboard.jsx';
import AttendanceDashboard from '../components/dashboard/AttendanceDashboard.jsx';
import ExaminationDashboard from '../components/dashboard/ExaminationDashboard.jsx';
import HumanResourceDashboard from '../components/dashboard/HumanResourceDashboard.jsx';
import HODDashboard from '../components/dashboard/HODDashboard.jsx';
import LibraryDashboard from '../components/dashboard/LibraryDashboard.jsx';
import MessManagementDashboard from '../components/dashboard/MessManagementDashboard.jsx';
import ProfilePage from '../pages/employees/ProfilePage.jsx';

export default function DashboardPage () {
  const navigate = useNavigate();
  const [activeDashboardTab, setActiveDashboardTab] = useState('Quick Links');

  // Live clock
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  // Data hooks
  const { data: studentsData } = useResourceList('students', { page: 1, pageSize: 1 });
  const studentsCount = studentsData?.meta?.total || studentsData?.items?.length || 0;
  const { data: teachersData } = useResourceList('teachers', { page: 1, pageSize: 1 });
  const teachersCount = teachersData?.meta?.total || teachersData?.items?.length || 0;
  const { data: employeesData } = useResourceList('employees', { page: 1, pageSize: 1 });
  const employeesCount = employeesData?.meta?.total || employeesData?.items?.length || 0;
  const { data: leadsData } = useResourceList('leads', { page: 1, pageSize: 1 });
  const leadsCount = leadsData?.meta?.total || leadsData?.items?.length || 0;
  const { data: paymentsData } = useResourceList('feePayments', { page: 1, pageSize: 100 });
  const payments = paymentsData?.items || [];
  const feeCollected = useMemo(() => payments.reduce((s, p) => s + (p.amount || 0), 0), [payments]);
  const { data: attendanceData } = useResourceList('studentAttendance', { page: 1, pageSize: 100 });
  const attendance = attendanceData?.items || [];
  const avgAttendance = attendance.length ? `${(attendance.reduce((s, a) => s + (a.percentage || 0), 0) / attendance.length).toFixed(1)}%` : '0.0%';

  // KPI cards
  const kpis = [
    { id: 'k-students', label: 'Total Students', value: studentsCount, icon: GraduationCap, bg: 'linear-gradient(135deg,#1e40af,#3b82f6)' },
    { id: 'k-teachers', label: 'Total Teachers', value: teachersCount, icon: BookOpen, bg: 'linear-gradient(135deg,#065f46,#10b981)' },
    { id: 'k-employees', label: 'Total Employees', value: employeesCount, icon: Briefcase, bg: 'linear-gradient(135deg,#7c3aed,#a78bfa)' },
    { id: 'k-admissions', label: 'Admissions', value: leadsCount, icon: UserPlus, bg: 'linear-gradient(135deg,#b45309,#f59e0b)' },
    { id: 'k-fee', label: 'Fee Collected', value: `₹${feeCollected.toLocaleString()}`, icon: IndianRupee, bg: 'linear-gradient(135deg,#0e7490,#06b6d4)' },
    { id: 'k-attendance', label: 'Avg Attendance', value: avgAttendance, icon: CalendarCheck, bg: 'linear-gradient(135deg,#be123c,#f43f5e)' },
  ];

  const quickActions = [
    { id: 'qa-students', label: 'Student List', to: '/students', color: '#3b82f6' },
    { id: 'qa-collect', label: 'Collect Fee', to: '/fees/collection', color: '#10b981' },
    { id: 'qa-summary', label: 'Fee Summary', to: '/finance', color: '#ec4899' },
    { id: 'qa-notice', label: 'Notice', to: '/notifications', color: '#f59e0b' },
    { id: 'qa-attendance', label: 'Student Attendance', to: '/attendance/students', color: '#10b981' },
    { id: 'qa-college', label: 'College Summary', to: '/reports', color: '#3b82f6' },
    { id: 'qa-employee', label: 'Employee', to: '/employees', color: '#10b981' },
    { id: 'qa-books', label: 'Books', to: '/library', color: '#ec4899' },
  ];

  const reportCards = [
    { id: 'report-strength', label: 'Strength Report', icon: Users },
    { id: 'report-collection', label: 'Daily Collection', icon: IndianRupee },
    { id: 'report-due-fee', label: 'Due Fee Report', icon: FileWarning },
    { id: 'report-due-fee-college', label: 'Due Fee College Wise', icon: Building2 },
    { id: 'report-employee', label: 'Employee Report', icon: Briefcase },
    { id: 'report-subject', label: 'Subject Report', icon: BookOpen },
  ];

  return (
    <div className="min-h-screen w-full overflow-x-hidden bg-[linear-gradient(135deg,#f0fdf4_0%,#f8fafc_40%,#f0f9ff_100%)] p-0">
      <div className="w-full p-3 sm:p-4 lg:p-6">
        <div className="flex flex-col gap-3 rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between sm:p-5">
          <div>
            <div className="text-xl font-bold text-slate-900 sm:text-2xl">Hello, Admin 👋</div>
            <div className="mt-1 text-sm text-slate-600">Nice to have you back, what an exciting day!</div>
          </div>
          <div className="text-sm text-slate-600">
            {now.toLocaleString('en-US', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })} | {now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true })}
          </div>
        </div>

        <div className="sticky top-16 z-20 mt-3 rounded-2xl border border-slate-200/70 bg-white shadow-sm">
          <div className="flex gap-2 overflow-x-auto px-2 py-2 sm:px-3">
            {[
              'Quick Links',
              'Student Overview',
              'Fee',
              'Admission',
              'Attendance',
              'Examination',
              'Human Resource',
              'Library',
              'My Profile',
              'HOD Dashboard',
              'Mess Management',
            ].map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setActiveDashboardTab(t)}
                className={`whitespace-nowrap rounded-full px-3 py-2 text-[13px] font-medium transition-colors ${
                  activeDashboardTab === t
                    ? 'border border-emerald-500 bg-emerald-50 text-emerald-700'
                    : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
                }`}
              >
                {t.replace("'", '’')}
              </button>
            ))}
          </div>
        </div>

        <div className="mt-4">
          {activeDashboardTab === 'Quick Links' && (
            <>
              <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6">
                {kpis.map((k) => (
                  <div key={k.id} className="flex items-center gap-3 rounded-2xl p-4 text-white shadow-lg" style={{ background: k.bg }}>
                    <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-white/20">
                      <k.icon className="h-6 w-6" />
                    </div>
                    <div className="min-w-0">
                      <div className="text-xl font-bold">{k.value}</div>
                      <div className="text-[11px] uppercase tracking-[0.2em] text-white/90">{k.label}</div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="mt-4 grid gap-4 xl:grid-cols-2">
                <div className="no-hover-border flex min-h-0 flex-col rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm sm:p-5">
                  <div>
                    <div className="text-lg font-semibold text-slate-900">Favorites</div>
                    <div className="mt-1 text-sm text-slate-500">Quick access to common tasks</div>
                  </div>
                  <div className="mt-4 grid flex-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">
                    {quickActions.map((a) => (
                      <button key={a.id} type="button" onClick={() => navigate(a.to)} className="hover-gradient-border flex min-h-[92px] flex-col items-center justify-center rounded-2xl border border-slate-200 bg-white px-3 py-3 text-center transition hover:-translate-y-0.5 hover:shadow-lg cursor-pointer">
                        <Star className="h-5 w-5" style={{ color: a.color }} />
                        <div className="mt-2 text-[11px] font-semibold" style={{ color: a.color }}>{a.label}</div>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="no-hover-border flex min-h-0 flex-col rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm sm:p-5">
                  <div>
                    <div className="text-lg font-semibold text-slate-900">Reports</div>
                    <div className="mt-1 text-sm text-slate-500">Team and finance dashboards</div>
                  </div>
                  <div className="mt-4 grid flex-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
                    {reportCards.map((card) => (
                      <button key={card.id} type="button" onClick={() => navigate('/reports')} className="hover-gradient-border flex min-h-[92px] flex-col items-center justify-center rounded-2xl bg-slate-900 px-3 py-3 text-center text-white transition hover:-translate-y-0.5 hover:shadow-lg hover:bg-slate-800 cursor-pointer">
                        <card.icon className="h-5 w-5" />
                        <div className="mt-2 text-[12px] font-semibold">{card.label}</div>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </>
          )}
          
          {activeDashboardTab === 'Student Overview' && <StudentOverviewDashboard />}
          
          {activeDashboardTab === 'Fee' && <FeeDashboard />}
          
          {activeDashboardTab === 'Admission' && <AdmissionDashboard />}
          
          {activeDashboardTab === 'Attendance' && <AttendanceDashboard />}
          
          {activeDashboardTab === 'Examination' && <ExaminationDashboard />}
          {activeDashboardTab === 'Human Resource' && <HumanResourceDashboard />}
          {activeDashboardTab === 'Library' && <LibraryDashboard />}
          {activeDashboardTab === 'My Profile' && <ProfilePage />}
          {activeDashboardTab === 'HOD Dashboard' && <HODDashboard />}
          {activeDashboardTab === 'Mess Management' && <MessManagementDashboard />}
        </div>
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { useForm } from 'react-hook-form';
import { useResourceList, useCreateResource } from '../hooks/useResourceHooks';
import { FaBuilding, FaDownload, FaPlus } from 'react-icons/fa';
import SectionHeader from '../components/ui/SectionHeader.jsx';
import SearchFilter from '../components/forms/SearchFilter.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';
import TablePagination from '../components/tables/TablePagination.jsx';
import Modal from '../components/ui/Modal.jsx';
import Button from '../components/ui/Button.jsx';
import FormField from '../components/forms/FormField.jsx';
const statusOptions = [
  { value: 'All', label: 'All statuses' },
  { value: 'Active', label: 'Active' },
  { value: 'Inactive', label: 'Inactive' },
];
export default function DepartmentManagementPage() {
  const { data: departmentsData } = useResourceList('departments', { page: 1, pageSize: 200 });
  const departments = departmentsData?.items || [];
  const createDepartment = useCreateResource('departments');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [page, setPage] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const pageSize = 5;
  const { register, handleSubmit, reset, formState: { errors, _isSubmitting } } = useForm({ defaultValues: { code: '', name: '', head: '', facultyCount: '0', activePrograms: '0', status: 'Active' } });
  const filteredDepartments = useMemo(() => {
    const searchTerm = search.toLowerCase();
    return departments.filter((department) => {
      const matchesSearch = [department.code, department.name, department.head].some((field) => String(field ?? '').toLowerCase().includes(searchTerm));
      const matchesFilter = filter === 'All' || String(department.status ?? '') === filter;
      return matchesSearch && matchesFilter;
    });
  }, [departments, search, filter]);
  const pageCount = Math.max(1, Math.ceil(filteredDepartments.length / pageSize));
  const displayedDepartments = filteredDepartments.slice((page - 1) * pageSize, page * pageSize);
  const onSubmit = (data) => {
    createDepartment({
      ...data,
      facultyCount: Number(data.facultyCount),
      activePrograms: Number(data.activePrograms),
    });
    reset({ code: '', name: '', head: '', facultyCount: '0', activePrograms: '0', status: 'Active' });
    setPage(1);
    setIsModalOpen(false);
  };
  return (
    <div className="space-y-6">
      <SectionHeader title="Department management" subtitle="Academic department operations, heads, active programs, and faculty coverage." />
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(280px,0.3fr)]">
        <div className="grid gap-4">
          <div className="grid gap-3 md:grid-cols-3">
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Active departments</p>
              <p className="mt-3 text-2xl font-semibold text-white">{departments.length}</p>
            </div>
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Faculty coverage</p>
              <p className="mt-3 text-2xl font-semibold text-white">{departments.reduce((sum, dept) => sum + Number(dept.facultyCount || 0), 0)}</p>
            </div>
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Program count</p>
              <p className="mt-3 text-2xl font-semibold text-white">{departments.reduce((sum, dept) => sum + Number(dept.activePrograms || 0), 0)}</p>
            </div>
          </div>
          <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
              <div>
                <h2 className="text-xl font-semibold text-white">Department directory</h2>
                <p className="text-sm text-slate-400">Manage departments, leadership, and academic program support.</p>
              </div>
              <div className="flex flex-wrap items-center gap-2">
                <button className="inline-flex items-center gap-2 rounded-2xl bg-slate-800/80 px-3 py-2 text-sm text-slate-200 transition hover:bg-slate-700 hover-gradient-border">
                  <FaDownload /> Export
                </button>
                <button onClick={() => setIsModalOpen(true)} className="inline-flex items-center gap-2 rounded-2xl bg-sky-400 px-3 py-2 text-sm font-semibold text-slate-950 transition hover:bg-sky-300">
                  <FaPlus /> Add department
                </button>
              </div>
            </div>
            <div className="mt-4 grid gap-3 md:grid-cols-2">
              <SearchFilter search={search} onSearch={setSearch} filter={filter} onFilter={setFilter} options={statusOptions} />
            </div>
            <div className="mt-6">
              <DataTable
                columns={['Code', 'Department', 'Head', 'Faculty', 'Programs', 'Status']}
                rows={displayedDepartments.map((department) => [department.code, department.name, department.head, department.facultyCount, department.activePrograms, <StatusBadge key={department.code} status={department.status} />])}
              />
            </div>
            <div className="mt-4">
              <TablePagination page={page} pageCount={pageCount} onPageChange={setPage} />
            </div>
          </div>
        </div>
        <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <div className="mb-4 flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-sky-400/10 text-sky-300">
              <FaBuilding className="h-4 w-4" />
            </div>
            <div>
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Operational insights</p>
              <h3 className="text-lg font-semibold text-white">Department performance</h3>
            </div>
          </div>
          <div className="grid gap-3">
            <div className="rounded-[22px] border border-white/10 bg-slate-950/70 p-4">
              <p className="text-sm text-slate-400">Largest department</p>
              <p className="mt-2 text-2xl font-semibold text-white">Computer Science</p>
            </div>
            <div className="rounded-[22px] border border-white/10 bg-slate-950/70 p-4">
              <p className="text-sm text-slate-400">Most active programs</p>
              <p className="mt-2 text-2xl font-semibold text-white">Computer Science</p>
            </div>
          </div>
        </div>
      </div>
      <Modal title="Add department" isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} footer={<Button onClick={handleSubmit(onSubmit)} variant="primary" >Save department</Button>}>
        <form className="grid gap-5 lg:grid-cols-2">
          <FormField label="Department code">
            <input type="text" {...register('code', { required: 'Code is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="CS" />
            {errors.code && <p className="mt-1 text-sm text-rose-400">{errors.code.message}</p>}
          </FormField>
          <FormField label="Department name">
            <input type="text" {...register('name', { required: 'Name is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="Computer Science" />
            {errors.name && <p className="mt-1 text-sm text-rose-400">{errors.name.message}</p>}
          </FormField>
          <FormField label="Department head">
            <input type="text" {...register('head', { required: 'Head is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="Dr. Priya Menon" />
            {errors.head && <p className="mt-1 text-sm text-rose-400">{errors.head.message}</p>}
          </FormField>
          <FormField label="Faculty count">
            <input type="number" {...register('facultyCount', { required: 'Faculty count is required', min: { value: 1, message: 'Must be at least 1' } })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="18" />
            {errors.facultyCount && <p className="mt-1 text-sm text-rose-400">{errors.facultyCount.message}</p>}
          </FormField>
          <FormField label="Active programs">
            <input type="number" {...register('activePrograms', { required: 'Program count is required', min: { value: 1, message: 'Must be at least 1' } })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="4" />
            {errors.activePrograms && <p className="mt-1 text-sm text-rose-400">{errors.activePrograms.message}</p>}
          </FormField>
          <FormField label="Status">
            <select {...register('status', { required: 'Status is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border">
              <option value="Active">Active</option>
              <option value="Inactive">Inactive</option>
            </select>
            {errors.status && <p className="mt-1 text-sm text-rose-400">{errors.status.message}</p>}
          </FormField>
        </form>
      </Modal>
    </div>
  );
}

import { useMemo, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';
import {
  useResourceList,
  useCreateResource,
  useUpdateResource,
  useDeleteResource,
  useBulkImport,
  useBulkExport,
} from '../hooks/useResourceHooks';
import { FaChartLine, FaDownload, FaEdit, FaFileImport, FaPlus, FaTrash } from 'react-icons/fa';
import SectionHeader from '../components/ui/SectionHeader.jsx';
import SearchFilter from '../components/forms/SearchFilter.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';
import TablePagination from '../components/tables/TablePagination.jsx';
import Modal from '../components/ui/Modal.jsx';
import FormField from '../components/forms/FormField.jsx';

const statusOptions = [
  { value: 'All', label: 'All statuses' },
  { value: 'Active', label: 'Active' },
  { value: 'Inactive', label: 'Inactive' },
];

const defaultValues = {
  code: '',
  title: '',
  level: '1',
  status: 'Active',
};

function downloadBlob(blob, filename) {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
}

export default function DesignationManagementPage() {
  const importInputRef = useRef(null);
  const { data: designationsData } = useResourceList('designations', { page: 1, pageSize: 200 });
  const designations = designationsData?.items || [];
  const createDesignation = useCreateResource('designations');
  const updateDesignation = useUpdateResource('designations');
  const deleteDesignation = useDeleteResource('designations');
  const importDesignation = useBulkImport('designations');
  const exportDesignation = useBulkExport('designations');

  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [page, setPage] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedDesignation, setSelectedDesignation] = useState(null);
  const [importStatus, setImportStatus] = useState('');
  const [_isExporting, setIsExporting] = useState(false);
  const pageSize = 6;

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm({ defaultValues });

  const filteredDesignations = useMemo(() => {
    return designations.filter((designation) => {
      const searchTerm = search.toLowerCase();
      const matchesSearch = [designation.code, designation.title, designation.level]
        .filter(Boolean)
        .some((field) => field.toString().toLowerCase().includes(searchTerm));
      const matchesFilter = filter === 'All' || designation.status === filter;
      return matchesSearch && matchesFilter;
    });
  }, [designations, search, filter]);

  const pageCount = Math.max(1, Math.ceil(filteredDesignations.length / pageSize));
  const displayedDesignations = filteredDesignations.slice((page - 1) * pageSize, page * pageSize);
  const activeDesignations = designations.filter((designation) => designation.status === 'Active').length;
  const averageLevel = designations.length
    ? (designations.reduce((sum, designation) => sum + Number(designation.level || 0), 0) / designations.length).toFixed(1)
    : '0.0';

  const resetForm = () => {
    reset(defaultValues);
    setSelectedDesignation(null);
    setIsEditMode(false);
  };

  const openNewDesignationModal = () => {
    resetForm();
    setIsModalOpen(true);
  };

  const openEditDesignationModal = (designation) => {
    setSelectedDesignation(designation);
    setIsEditMode(true);
    reset({
      code: designation.code || '',
      title: designation.title || '',
      level: String(designation.level || '1'),
      status: designation.status || 'Active',
    });
    setIsModalOpen(true);
  };

  const onSubmit = (data) => {
    const payload = {
      ...data,
      level: Number(data.level),
    };
    if (isEditMode && selectedDesignation) {
      updateDesignation.mutate({ id: selectedDesignation.id, payload }, { onSuccess: () => { resetForm(); setPage(1); setIsModalOpen(false); } });
    } else {
      createDesignation.mutate(payload, { onSuccess: () => { resetForm(); setPage(1); setIsModalOpen(false); } });
    }
  };

  const handleDelete = (designation) => {
    if (!window.confirm(`Delete designation ${designation.title}?`)) return;
    deleteDesignation.mutate(designation.id);
  };

  const handleImport = (file) => {
    if (!file) return;
    setImportStatus('Importing designations…');
    const formData = new FormData();
    formData.append('file', file);
    importDesignation.mutate(formData, {
      onSuccess: () => setImportStatus('Designations imported successfully.'),
      onError: () => setImportStatus('Import failed. Please try a valid CSV file.'),
    });
  };

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];
    handleImport(file);
    event.target.value = '';
  };

  const handleExport = async () => {
    setIsExporting(true);
    try {
      const blob = await exportDesignation.mutateAsync();
      downloadBlob(blob, 'designations-export.xlsx');
    } catch (error) {
      console.error(error);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="space-y-6">
      <SectionHeader
        title="Designation management"
        subtitle="Manage role levels, job titles, and HR staffing hierarchies."
        action={
          <div className="flex flex-wrap items-center gap-3">
            <button
              type="button"
              onClick={handleExport}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700 hover-gradient-border"
            >
              <FaDownload /> Export
            </button>
            <button
              type="button"
              onClick={() => importInputRef.current?.click()}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700"
            >
              <FaFileImport /> Import
            </button>
            <button
              type="button"
              onClick={openNewDesignationModal}
              className="inline-flex items-center gap-2 rounded-3xl bg-emerald-500 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 hover-gradient-border"
            >
              <FaPlus /> Add designation
            </button>
          </div>
        }
      />
      <input ref={importInputRef} type="file" accept=".csv" className="hidden hover-gradient-border" onChange={handleFileChange} />
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(280px,0.3fr)]">
        <div className="grid gap-4">
          <div className="grid gap-3 md:grid-cols-3">
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Total designations</p>
              <p className="mt-3 text-2xl font-semibold text-white">{designations.length}</p>
            </div>
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Active titles</p>
              <p className="mt-3 text-2xl font-semibold text-white">{activeDesignations}</p>
            </div>
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Average level</p>
              <p className="mt-3 text-2xl font-semibold text-white">{averageLevel}</p>
            </div>
          </div>
          <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
              <div>
                <h2 className="text-xl font-semibold text-white">Designation catalog</h2>
                <p className="text-sm text-slate-400">Create job titles and map position levels across HR operations.</p>
              </div>
            </div>
            <div className="mt-4 grid gap-3 md:grid-cols-2">
              <SearchFilter search={search} onSearch={setSearch} filter={filter} onFilter={setFilter} options={statusOptions} />
            </div>
            <div className="mt-4">
              <DataTable
                columns={['Code', 'Title', 'Level', 'Status', 'Actions']}
                rows={displayedDesignations.map((designation) => [
                  designation.code,
                  designation.title,
                  designation.level,
                  <StatusBadge key={`${designation.id}-status`} status={designation.status} />,
                  <div key={`${designation.id}-actions`} className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => openEditDesignationModal(designation)}
                      className="rounded-full border border-white/10 bg-slate-800/80 px-3 py-2 text-xs text-slate-200 transition hover:bg-slate-700"
                    >
                      <FaEdit className="inline-block" /> Edit
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDelete(designation)}
                      className="rounded-full border border-white/10 bg-rose-500/10 px-3 py-2 text-xs text-rose-300 transition hover:bg-rose-500/20"
                    >
                      <FaTrash className="inline-block" /> Remove
                    </button>
                  </div>,
                ])}
              />
            </div>
            <div className="mt-4">
              <TablePagination page={page} pageCount={pageCount} onPageChange={setPage} />
            </div>
          </div>
        </div>
        <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <div className="mb-4 flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-emerald-500/10 text-emerald-300">
              <FaChartLine className="h-4 w-4" />
            </div>
            <div>
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">HR hierarchy</p>
              <h3 className="text-lg font-semibold text-white">Position planning</h3>
            </div>
          </div>
          <div className="grid gap-3">
            <div className="rounded-[22px] border border-white/10 bg-slate-950/70 p-4">
              <p className="text-sm text-slate-400">Most common title</p>
              <p className="mt-2 text-2xl font-semibold text-white">{designations[0]?.title || 'N/A'}</p>
            </div>
            <div className="rounded-[22px] border border-white/10 bg-slate-950/70 p-4">
              <p className="text-sm text-slate-400">Levels covered</p>
              <p className="mt-2 text-2xl font-semibold text-white">{designations.length ? Math.max(...designations.map((item) => Number(item.level || 0))) : 0}</p>
            </div>
          </div>
        </div>
      </div>
      {importStatus && (
        <div className="rounded-[28px] border border-emerald-500/20 bg-emerald-500/5 p-4 text-sm text-emerald-200">{importStatus}</div>
      )}
      <Modal
        title={isEditMode ? 'Update designation' : 'Add designation'}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        footer={
          <button
            type="button"
            onClick={handleSubmit(onSubmit)}
            disabled={isSubmitting}
            className="rounded-3xl bg-emerald-500 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 disabled:cursor-not-allowed disabled:opacity-60 hover-gradient-border"
          >
            {isEditMode ? 'Update designation' : 'Save designation'}
          </button>
        }
      >
        <form className="grid gap-5 lg:grid-cols-2">
          <FormField label="Designation code">
            <input
              type="text"
              {...register('code', { required: 'Code is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="HR-01"
            />
            {errors.code && <p className="mt-1 text-sm text-rose-400">{errors.code.message}</p>}
          </FormField>
          <FormField label="Designation title">
            <input
              type="text"
              {...register('title', { required: 'Title is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="HR Coordinator"
            />
            {errors.title && <p className="mt-1 text-sm text-rose-400">{errors.title.message}</p>}
          </FormField>
          <FormField label="Level">
            <input
              type="number"
              {...register('level', { required: 'Level is required', min: { value: 1, message: 'Minimum level 1' } })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="1"
            />
            {errors.level && <p className="mt-1 text-sm text-rose-400">{errors.level.message}</p>}
          </FormField>
          <FormField label="Status">
            <select
              {...register('status', { required: 'Status is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
            >
              <option value="Active">Active</option>
              <option value="Inactive">Inactive</option>
            </select>
            {errors.status && <p className="mt-1 text-sm text-rose-400">{errors.status.message}</p>}
          </FormField>
        </form>
      </Modal>
    </div>
  );
}

