import { useEffect, useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import { Trash2 } from 'lucide-react';
import Breadcrumb from '../components/ui/Breadcrumb.jsx';
import Button from '../components/ui/Button.jsx';
import Modal from '../components/ui/Modal.jsx';
import TablePagination from '../components/tables/TablePagination.jsx';

const initialEmployees = [
  { id: 'emp-1', name: 'Tushant Kumar', employeeId: 'HU175', dateCount: 9 },
  { id: 'emp-2', name: 'Ravindra Kr Arya', employeeId: 'HU111', dateCount: 17 },
  { id: 'emp-3', name: 'Mukul Saini', employeeId: 'HU278', dateCount: 5 },
  { id: 'emp-4', name: 'Bhuvnesh Kumar', employeeId: 'HU134', dateCount: 51 },
  { id: 'emp-5', name: 'Narayan Jee', employeeId: 'HU143', dateCount: 49 },
  { id: 'emp-6', name: 'Vimal Panday', employeeId: 'HU149', dateCount: 51 },
  { id: 'emp-7', name: 'Sulochna', employeeId: 'HU113', dateCount: 34 },
  { id: 'emp-8', name: 'Neha Sharma', employeeId: 'HU182', dateCount: 12 },
  { id: 'emp-9', name: 'Rajeev Kumar', employeeId: 'HU164', dateCount: 28 },
  { id: 'emp-10', name: 'Deepak Singh', employeeId: 'HU190', dateCount: 22 },
];

const teacherOptions = [
  'Ravindra Kr Arya',
  'Narayan Jee',
  'Bhuvnesh Kumar',
  'Neha Sharma',
  'Vimal Panday',
  'Rajeev Kumar',
  'Deepak Singh',
];

const pageSizeOptions = [5, 10, 15];

export default function EmployeeCalendarListPage() {
  const [rows, setRows] = useState(initialEmployees);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [replacementTeacher, setReplacementTeacher] = useState(teacherOptions[0]);
  const [effectiveFrom, setEffectiveFrom] = useState('2026-07-01');
  const [effectiveTo, setEffectiveTo] = useState('2026-07-31');
  const [reason, setReason] = useState('');
  const [actionMessage, setActionMessage] = useState('');

  useEffect(() => {
    if (!actionMessage) return undefined;
    const timer = window.setTimeout(() => setActionMessage(''), 2800);
    return () => window.clearTimeout(timer);
  }, [actionMessage]);

  const filteredRows = useMemo(() => {
    const normalizedSearch = search.trim().toLowerCase();
    if (!normalizedSearch) return rows;
    return rows.filter((row) =>
      [row.name, row.employeeId].some((value) => value.toLowerCase().includes(normalizedSearch))
    );
  }, [rows, search]);

  const pageCount = Math.max(1, Math.ceil(filteredRows.length / pageSize));
  const displayedRows = filteredRows.slice((page - 1) * pageSize, (page - 1) * pageSize + pageSize);

  useEffect(() => {
    if (page > pageCount) {
      setPage(pageCount);
    }
  }, [page, pageCount]);

  const selectedRows = rows.filter((row) => selectedIds.has(row.id));
  const isAllSelected = displayedRows.length > 0 && displayedRows.every((row) => selectedIds.has(row.id));
  const hasSelection = selectedIds.size > 0;

  const handleSearchChange = (event) => {
    setSearch(event.target.value);
    setPage(1);
  };

  const handleSelectAll = () => {
    const nextSelectedIds = new Set(selectedIds);
    if (isAllSelected) {
      displayedRows.forEach((row) => nextSelectedIds.delete(row.id));
    } else {
      displayedRows.forEach((row) => nextSelectedIds.add(row.id));
    }
    setSelectedIds(nextSelectedIds);
  };

  const handleSelectRow = (rowId) => {
    const nextSelectedIds = new Set(selectedIds);
    if (nextSelectedIds.has(rowId)) nextSelectedIds.delete(rowId);
    else nextSelectedIds.add(rowId);
    setSelectedIds(nextSelectedIds);
  };

  const handleDeleteRow = (rowId) => {
    const row = rows.find((item) => item.id === rowId);
    if (!row) return;
    if (!window.confirm(`Delete ${row.name} from the employee calendar list?`)) return;
    setRows((current) => current.filter((item) => item.id !== rowId));
    setSelectedIds((current) => {
      const next = new Set(current);
      next.delete(rowId);
      return next;
    });
  };

  const handleOpenReplaceModal = () => setIsModalOpen(true);
  const handleCloseReplaceModal = () => setIsModalOpen(false);

  const clearSelection = () => setSelectedIds(new Set());

  const showActionMessage = (message) => {
    setActionMessage(message);
  };

  const handleReplaceTeacher = () => {
    if (!hasSelection) return;
    setRows((current) =>
      current.map((row) =>
        selectedIds.has(row.id)
          ? {
              ...row,
              replacementTeacher,
              replacementFrom: effectiveFrom,
              replacementTo: effectiveTo,
              replacementReason: reason,
              status: row.status || 'Active',
            }
          : row
      )
    );
    setIsModalOpen(false);
    setReason('');
    showActionMessage('Replacement teacher updated for selected employees.');
  };

  const handleCancelLectures = () => {
    if (!hasSelection) return;
    setRows((current) =>
      current.map((row) =>
        selectedIds.has(row.id)
          ? { ...row, status: 'Cancelled' }
          : row
      )
    );
    clearSelection();
    showActionMessage('Selected lectures were cancelled.');
  };

  const handleDeleteEmployeeLecturesByCollege = () => {
    if (!hasSelection) return;
    if (!window.confirm(`Delete lectures by college for ${selectedRows.length} selected employee(s)?`)) return;
    setRows((current) => current.filter((row) => !selectedIds.has(row.id)));
    setSelectedIds(new Set());
    showActionMessage('Selected employee lectures were deleted by college.');
  };

  const handleDeleteEmployeeLectures = () => {
    if (!hasSelection) return;
    if (!window.confirm(`Delete lectures for ${selectedRows.length} selected employee(s)?`)) return;
    setRows((current) => current.filter((row) => !selectedIds.has(row.id)));
    setSelectedIds(new Set());
    showActionMessage('Selected employee lectures were deleted.');
  };

  const handlePageChange = (nextPage) => {
    setPage(nextPage);
  };

  const handlePageSizeChange = (event) => {
    setPageSize(Number(event.target.value));
    setPage(1);
  };

  return (
    <div className="min-h-screen overflow-x-hidden bg-[linear-gradient(135deg,#f8fafc_0%,#eef2ff_45%,#f0fdf4_100%)] p-0">
      <div className="m-2.5 rounded-[22px] border border-slate-200/80 bg-white/90 p-5 shadow-[0_22px_70px_-24px_rgba(2,8,23,0.35)] sm:p-6">
        <Breadcrumb
          items={[
            { label: 'Dashboard', to: '/' },
            { label: 'Academics Setup', to: '/academics' },
            { label: 'Employee Calendar List' },
          ]}
        />

        <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
          <div>
            <h1 className="text-3xl font-semibold tracking-tight text-slate-950">Employee Calendar List</h1>
            <p className="mt-2 text-sm text-slate-500">Employee Calendar</p>
          </div>
          <Button
            type="button"
            onClick={handleOpenReplaceModal}
            disabled={!hasSelection}
            variant="primary"
            className="inline-flex items-center justify-center gap-2 px-4 text-sm font-semibold"
          >
            Replace Teacher
          </Button>
        </div>

        <div className="mt-6 grid gap-4 sm:grid-cols-[1fr_auto] sm:items-center">
          <div className="relative max-w-md">
            <input
              type="search"
              value={search}
              onChange={handleSearchChange}
              placeholder="Search Employee..."
              className="w-full rounded-2xl border border-slate-200 bg-slate-50 py-3 px-4 text-sm font-semibold text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-100"
            />
          </div>
          {actionMessage && (
            <div className="rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700 shadow-sm">
              {actionMessage}
            </div>
          )}

          <div className="flex flex-wrap items-center gap-2 text-sm text-slate-600">
            <span>Items per page:</span>
            <select
              value={pageSize}
              onChange={handlePageSizeChange}
              className="h-10 rounded-2xl border border-slate-200 bg-white px-3 text-sm font-semibold text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-100"
            >
              {pageSizeOptions.map((option) => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="mt-6 overflow-hidden rounded-[20px] border border-slate-200 bg-white shadow-sm">
          <div className="overflow-x-auto">
            <table className="min-w-full border-collapse text-left text-sm">
              <thead className="bg-slate-950 text-slate-100">
                <tr>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3">
                    <input
                      type="checkbox"
                      checked={isAllSelected}
                      onChange={handleSelectAll}
                      className="h-4 w-4 rounded border-slate-300 bg-slate-900 text-white"
                      aria-label="Select all employees"
                    />
                  </th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">S.No</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Employee Name</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Employee Id</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Date Count</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Status</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Replacement Teacher</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Effective From</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Effective To</th>
                  <th className="sticky top-0 border-b border-slate-700 px-4 py-3 font-semibold uppercase tracking-[0.14em]">Action</th>
                </tr>
              </thead>
              <tbody>
                {displayedRows.map((row, index) => (
                  <tr key={row.id} className="border-b border-slate-200 transition hover:bg-slate-50">
                    <td className="px-4 py-4 align-top">
                      <input
                        type="checkbox"
                        checked={selectedIds.has(row.id)}
                        onChange={() => handleSelectRow(row.id)}
                        className="h-4 w-4 rounded border-slate-300 text-slate-900"
                        aria-label={`Select ${row.name}`}
                      />
                    </td>
                    <td className="px-4 py-4 align-top font-semibold text-slate-900">{(page - 1) * pageSize + index + 1}</td>
                    <td className="px-4 py-4 align-top text-slate-900">{row.name}</td>
                    <td className="px-4 py-4 align-top text-slate-900">{row.employeeId}</td>
                    <td className="px-4 py-4 align-top text-slate-900">{row.dateCount}</td>
                    <td className="px-4 py-4 align-top text-slate-900">{row.status || 'Active'}</td>
                    <td className="px-4 py-4 align-top text-slate-900">{row.replacementTeacher || '-'}</td>
                    <td className="px-4 py-4 align-top text-slate-900">{row.replacementFrom || '-'}</td>
                    <td className="px-4 py-4 align-top text-slate-900">{row.replacementTo || '-'}</td>
                    <td className="px-4 py-4 align-top">
                      <button
                        type="button"
                        onClick={() => handleDeleteRow(row.id)}
                        className="inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-700 transition hover:border-rose-300 hover:bg-rose-50 hover:text-rose-700"
                        aria-label={`Delete ${row.name}`}
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                ))}
                {displayedRows.length === 0 && (
                  <tr>
                    <td colSpan={10} className="px-4 py-10 text-center text-sm text-slate-500">
                      No employees match your search.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          <div className="flex flex-col gap-3 border-t border-slate-200 bg-slate-50 px-4 py-4 sm:flex-row sm:items-center sm:justify-between">
            <p className="text-sm text-slate-600">
              Showing {displayedRows.length} of {filteredRows.length} employees
            </p>
            <TablePagination page={page} pageCount={pageCount} onPageChange={handlePageChange} />
          </div>

          {hasSelection && (
            <motion.div
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 12 }}
              transition={{ duration: 0.22 }}
              className="mt-4 rounded-[20px] border border-slate-200 bg-white px-4 py-4 shadow-sm"
            >
              <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-end">
                <Button
              type="button"
              variant="danger"
              onClick={handleCancelLectures}
              className="min-w-[180px] rounded-2xl px-4 py-2 text-sm font-semibold"
            >
              Cancel Lectures
            </Button>
            <Button
              type="button"
              variant="danger"
              onClick={handleDeleteEmployeeLecturesByCollege}
              className="min-w-[220px] rounded-2xl px-4 py-2 text-sm font-semibold"
            >
              Delete Employee Lectures By College
            </Button>
            <Button
              type="button"
              variant="danger"
              onClick={handleDeleteEmployeeLectures}
              className="min-w-[180px] rounded-2xl px-4 py-2 text-sm font-semibold"
            >
              Delete Employee Lectures
            </Button>
              </div>
            </motion.div>
          )}
        </div>
      </div>

      <Modal
        title="Replace Teacher"
        isOpen={isModalOpen}
        onClose={handleCloseReplaceModal}
        footer={
          <>
            <button
              type="button"
              onClick={handleCloseReplaceModal}
              className="inline-flex h-11 items-center justify-center rounded-2xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleReplaceTeacher}
              className="inline-flex h-11 items-center justify-center rounded-2xl bg-slate-950 px-4 text-sm font-semibold text-white transition hover:bg-slate-800"
              disabled={!hasSelection}
            >
              Replace
            </button>
          </>
        }
      >
        <div className="grid gap-5 sm:grid-cols-[1.2fr_0.8fr]">
          <div className="space-y-4">
            <div>
              <p className="text-sm font-semibold text-slate-700">Selected Employee(s)</p>
              <div className="mt-3 rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm text-slate-700">
                {selectedRows.length > 0 ? (
                  <ul className="space-y-2">
                    {selectedRows.map((row) => (
                      <li key={row.id} className="flex items-center gap-2 text-slate-900">
                        <span className="inline-flex h-8 min-w-[24px] items-center justify-center rounded-full bg-slate-200 text-xs font-semibold text-slate-700">{row.employeeId}</span>
                        {row.name}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-slate-500">No employee selected.</p>
                )}
              </div>
            </div>

            <label className="flex flex-col gap-2 text-sm font-semibold text-slate-700">
              Replacement Teacher
              <select
                value={replacementTeacher}
                onChange={(event) => setReplacementTeacher(event.target.value)}
                className="h-11 rounded-2xl border border-slate-200 bg-white px-4 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-100"
              >
                {teacherOptions.map((teacher) => (
                  <option key={teacher} value={teacher}>{teacher}</option>
                ))}
              </select>
            </label>

            <div className="grid gap-4 sm:grid-cols-2">
              <label className="flex flex-col gap-2 text-sm font-semibold text-slate-700">
                Effective From
                <input
                  type="date"
                  value={effectiveFrom}
                  onChange={(event) => setEffectiveFrom(event.target.value)}
                  className="h-11 rounded-2xl border border-slate-200 bg-white px-4 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-100"
                />
              </label>
              <label className="flex flex-col gap-2 text-sm font-semibold text-slate-700">
                Effective To
                <input
                  type="date"
                  value={effectiveTo}
                  onChange={(event) => setEffectiveTo(event.target.value)}
                  className="h-11 rounded-2xl border border-slate-200 bg-white px-4 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-100"
                />
              </label>
            </div>

            <label className="flex flex-col gap-2 text-sm font-semibold text-slate-700">
              Reason
              <textarea
                value={reason}
                onChange={(event) => setReason(event.target.value)}
                rows={4}
                className="min-h-[120px] rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-100"
                placeholder="Enter replacement reason"
              />
            </label>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import {
  useResourceList,
  useCreateResource,
  useUpdateResource,
  useDeleteResource,
  useBulkImport,
  useBulkExport,
} from '../hooks/useResourceHooks';
import {
  FaChartLine,
  FaDownload,
  FaEdit,
  FaFileImport,
  FaPlus,
  FaTrash,
} from 'react-icons/fa';
import SectionHeader from '../components/ui/SectionHeader.jsx';
import WithPermission from '../components/auth/WithPermission.jsx';
import SearchFilter from '../components/forms/SearchFilter.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';
import TablePagination from '../components/tables/TablePagination.jsx';
import Modal from '../components/ui/Modal.jsx';
import FormField from '../components/forms/FormField.jsx';
const statusOptions = [
  { value: 'All', label: 'All statuses' },
  { value: 'Active', label: 'Active' },
  { value: 'On Leave', label: 'On Leave' },
  { value: 'Resigned', label: 'Resigned' },
];
const defaultEmployeeValues = {
  name: '',
  email: '',
  department: 'Admissions',
  designation: 'Assistant',
  shift: 'Day',
  status: 'Active',
  salary: '3200',
  joinDate: '',
};
const defaultAttendanceValues = {
  date: new Date().toISOString().slice(0, 10),
  employeeId: '',
  shift: 'Day',
  status: 'Present',
};
function downloadBlob(blob, filename) {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
}
export default function EmployeeManagementPage() {
  const importInputRef = useRef(null);
  const navigate = useNavigate();
  const { data: employeesData } = useResourceList('employees', { page: 1, pageSize: 200 });
  const { data: departmentsData } = useResourceList('departments', { page: 1, pageSize: 200 });
  const { data: employeeAttendanceData } = useResourceList('employeeAttendance', { page: 1, pageSize: 200 });
  const employees = employeesData?.items || [];
  const departments = departmentsData?.items || [];
  const employeeAttendance = employeeAttendanceData?.items || [];
  const createEmployee = useCreateResource('employees');
  const updateEmployee = useUpdateResource('employees');
  const deleteEmployee = useDeleteResource('employees');
  const importEmployee = useBulkImport('employees');
  const exportEmployee = useBulkExport('employees');
  const createAttendance = useCreateResource('employeeAttendance');
  const [searchRoster, setSearchRoster] = useState('');
  const [filterRoster, setFilterRoster] = useState('All');
  const [page, setPage] = useState(1);
  const [attendancePage, setAttendancePage] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [importStatus, setImportStatus] = useState('');
  const [_isExporting, setIsExporting] = useState(false);
  const [isSubmittingAttendance, setIsSubmittingAttendance] = useState(false);
  const pageSize = 6;
  const attendancePageSize = 5;
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm({ defaultValues: defaultEmployeeValues });
  const {
    register: registerAttendance,
    handleSubmit: handleSubmitAttendance,
    reset: resetAttendance,
    formState: { errors: attendanceErrors },
  } = useForm({ defaultValues: defaultAttendanceValues });
  const employeeMap = useMemo(() => new Map(employees.map((employee) => [employee.id, employee])), [employees]);
  const filteredEmployees = useMemo(() => {
    return employees.filter((employee) => {
      const searchTerm = searchRoster.toLowerCase();
      const matchesSearch = [employee.name, employee.email, employee.department, employee.designation]
        .filter(Boolean)
        .some((field) => field.toLowerCase().includes(searchTerm));
      const matchesFilter = filterRoster === 'All' || employee.status === filterRoster;
      return matchesSearch && matchesFilter;
    });
  }, [employees, searchRoster, filterRoster]);
  const filteredAttendance = useMemo(() => {
    return employeeAttendance.filter((entry) => {
      const searchTerm = searchRoster.toLowerCase();
      const employeeName = employeeMap.get(entry.employeeId)?.name || '';
      const matchesSearch = [employeeName, entry.date, entry.shift, entry.status]
        .filter(Boolean)
        .some((field) => field.toLowerCase().includes(searchTerm));
      return matchesSearch;
    });
  }, [employeeAttendance, employeeMap, searchRoster]);
  const pageCount = Math.max(1, Math.ceil(filteredEmployees.length / pageSize));
  const displayedEmployees = filteredEmployees.slice((page - 1) * pageSize, page * pageSize);
  const attendancePageCount = Math.max(1, Math.ceil(filteredAttendance.length / attendancePageSize));
  const displayedAttendance = filteredAttendance.slice((attendancePage - 1) * attendancePageSize, attendancePage * attendancePageSize);
  const activeEmployees = employees.filter((employee) => employee.status === 'Active').length;
  const onLeaveEmployees = employees.filter((employee) => employee.status === 'On Leave').length;
  const dayShiftCount = employees.filter((employee) => employee.shift === 'Day').length;
  const totalPayroll = employees.reduce((sum, employee) => sum + (Number(String(employee.salary).replace(/[^0-9.]/g, '')) || 0), 0);
  const topDepartment = useMemo(() => {
    const counts = employees.reduce((acc, employee) => {
      const dept = employee.department || 'General';
      acc[dept] = (acc[dept] || 0) + 1;
      return acc;
    }, {});
    return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';
  }, [employees]);
  const attendanceSummary = useMemo(() => {
    const present = employeeAttendance.filter((entry) => entry.status === 'Present').length;
    const absent = employeeAttendance.filter((entry) => entry.status === 'Absent').length;
    const late = employeeAttendance.filter((entry) => entry.status === 'Late').length;
    return { present, absent, late };
  }, [employeeAttendance]);
  const resetForm = () => {
    reset(defaultEmployeeValues);
    setSelectedEmployee(null);
    setIsEditMode(false);
  };
  const openNewEmployeeModal = () => {
    resetForm();
    setIsModalOpen(true);
  };
  const openEditEmployeeModal = (employee) => {
    setSelectedEmployee(employee);
    setIsEditMode(true);
    reset({
      name: employee.name || '',
      email: employee.email || '',
      department: employee.department || 'Admissions',
      designation: employee.designation || 'Assistant',
      shift: employee.shift || 'Day',
      status: employee.status || 'Active',
      salary: String(employee.salary).replace(/[^0-9.]/g, '') || '3200',
      joinDate: employee.joinDate || '',
    });
    setIsModalOpen(true);
  };
  const formatEmployeePayload = (data, existingEmployee) => {
    const fullName = String(data.name || '').trim();
    const [first_name, ...rest] = fullName.split(' ');
    const last_name = rest.join(' ') || null;
    const inferredEmployeeCode = data.email ? data.email.split('@')[0].toLowerCase().replace(/[^a-z0-9]+/g, '-') : fullName.toLowerCase().replace(/[^a-z0-9]+/g, '-');

    return {
      employee_code: existingEmployee?.employee_code || inferredEmployeeCode || `emp-${Date.now()}`,
      first_name: first_name || fullName,
      last_name: last_name,
      email: data.email || null,
      designation: data.designation,
      department: data.department,
      status: data.status,
    };
  };
  const onSubmit = (data) => {
    const payload = formatEmployeePayload(data, selectedEmployee);
    if (isEditMode && selectedEmployee) {
      updateEmployee.mutate(
        { id: selectedEmployee.id, payload },
        {
          onSuccess: () => {
            resetForm();
            setPage(1);
            setIsModalOpen(false);
          },
        },
      );
    } else {
      createEmployee.mutate(payload, {
        onSuccess: () => {
          resetForm();
          setPage(1);
          setIsModalOpen(false);
        },
      });
    }
  };
  const handleDelete = (employee) => {
    if (!window.confirm(`Remove ${employee.name} from the workforce roster?`)) {
      return;
    }
    deleteEmployee.mutate(employee.id);
  };
  const handleImport = (file) => {
    if (!file) return;
    setImportStatus('Importing employee roster…');
    const formData = new FormData();
    formData.append('file', file);
    importEmployee.mutate(formData, {
      onSuccess: () => setImportStatus('Employee roster imported successfully.'),
      onError: () => setImportStatus('Import failed. Please try a valid CSV file.'),
    });
  };
  const handleFileChange = (event) => {
    const file = event.target.files?.[0];
    handleImport(file);
    event.target.value = '';
  };
  const handleExport = async () => {
    setIsExporting(true);
    try {
      const blob = await exportEmployee.mutateAsync();
      downloadBlob(blob, 'employees-export.xlsx');
    } catch (error) {
      console.error(error);
    } finally {
      setIsExporting(false);
    }
  };
  const handleAttendanceSubmit = (data) => {
    setIsSubmittingAttendance(true);
    createAttendance.mutate(data, {
      onSuccess: () => {
        resetAttendance(defaultAttendanceValues);
        setAttendancePage(1);
      },
      onSettled: () => setIsSubmittingAttendance(false),
    });
  };
  return (
    <div className="space-y-6">
      <SectionHeader
        title="Employee management"
        subtitle="HR operations, workforce analytics, payroll and attendance monitoring."
        action={
          <div className="flex flex-wrap items-center gap-3">
            <button
              type="button"
              onClick={handleExport}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700 hover-gradient-border"
            >
              <FaDownload /> Export payroll
            </button>
            <button
              type="button"
              onClick={() => importInputRef.current?.click()}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700"
            >
              <FaFileImport /> Import CSV
            </button>
            <button
              type="button"
              onClick={openNewEmployeeModal}
              className="inline-flex items-center gap-2 rounded-3xl bg-emerald-500 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 hover-gradient-border"
            >
              <FaPlus /> Add employee
            </button>
          </div>
        }
      />
      <input ref={importInputRef} type="file" accept=".csv" className="hidden hover-gradient-border" onChange={handleFileChange} />
      <div className="grid gap-4">
        <div className="grid gap-3 md:grid-cols-4">
          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Total employees</p>
            <p className="mt-3 text-2xl font-semibold text-white">{employees.length}</p>
          </div>
          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Day shift</p>
            <p className="mt-3 text-2xl font-semibold text-white">{dayShiftCount}</p>
          </div>
          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-400">On leave</p>
            <p className="mt-3 text-2xl font-semibold text-white">{onLeaveEmployees}</p>
          </div>
          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Payroll burn</p>
            <p className="mt-3 text-2xl font-semibold text-white">${totalPayroll.toLocaleString()}</p>
          </div>
        </div>
        <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
            <div>
              <h2 className="text-xl font-semibold text-white">Workforce roster</h2>
              <p className="text-sm text-slate-400">Search personnel records, filter by status, and manage role assignments.</p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <div className="rounded-2xl bg-slate-950/70 px-3 py-2 text-sm text-slate-200">Top department: {topDepartment}</div>
              <div className="rounded-2xl bg-slate-950/70 px-3 py-2 text-sm text-slate-200">On leave: {onLeaveEmployees}</div>
            </div>
          </div>
          <div className="mt-4 grid gap-3 md:grid-cols-2">
            <SearchFilter
              search={searchRoster}
              onSearch={setSearchRoster}
              filter={filterRoster}
              onFilter={setFilterRoster}
              options={statusOptions}
            />
          </div>
          <div className="mt-4">
            <DataTable
              columns={[
                { label: 'Employee', key: 'employee', minWidth: '180px' },
                { label: 'Email', key: 'email', minWidth: '200px' },
                { label: 'Department', key: 'department', minWidth: '130px' },
                { label: 'Designation', key: 'designation', minWidth: '140px' },
                { label: 'Status', key: 'status', minWidth: '90px' },
                { label: 'Actions', key: 'actions', minWidth: '120px' },
              ]}
              rows={displayedEmployees.map((employee) => [
                <div className="space-y-1" key={employee.id}>
                  <p className="font-semibold text-white">{employee.name}</p>
                  <p className="text-sm text-slate-400">{employee.email}</p>
                </div>,
                employee.department,
                employee.designation,
                <StatusBadge key={`${employee.id}-status`} status={employee.status} />,
                <div key={`${employee.id}-actions`} className="flex items-center justify-center gap-1.5">
                  <WithPermission moduleKey="employees" action="view">
                    <ViewButton
                      title="View employee"
                      ariaLabel="View employee"
                      className="h-8 w-8 rounded-full border border-sky-200 bg-sky-50 text-sky-700 hover:bg-sky-100"
                      onClick={() => navigate(`/employees/${employee.id}`)}
                    />
                  </WithPermission>
                  <WithPermission moduleKey="employees" action="edit">
                    <button
                      type="button"
                      title="Edit"
                      aria-label="Edit"
                      onClick={() => openEditEmployeeModal(employee)}
                      className="h-8 w-8 flex items-center justify-center rounded-full border border-emerald-200 bg-emerald-50 text-emerald-700 transition hover:bg-emerald-100 hover-gradient-border"
                    >
                      <FaEdit />
                    </button>
                  </WithPermission>
                  <WithPermission moduleKey="employees" action="delete">
                    <button
                      type="button"
                      title="Delete"
                      aria-label="Delete"
                      onClick={() => handleDelete(employee)}
                      className="h-8 w-8 flex items-center justify-center rounded-full border border-rose-200 bg-rose-50 text-rose-700 transition hover:bg-rose-100 hover-gradient-border"
                    >
                      <FaTrash />
                    </button>
                  </WithPermission>
                </div>,
              ])}
            />
          </div>
          <div className="mt-4">
            <TablePagination page={page} pageCount={pageCount} onPageChange={setPage} />
          </div>
        </div>
      </div>
      {importStatus && (
        <div className="rounded-[28px] border border-emerald-500/20 bg-emerald-500/5 p-4 text-sm text-emerald-200">{importStatus}</div>
      )}
      <div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]">
        <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
            <div>
              <h2 className="text-xl font-semibold text-white">Attendance overview</h2>
              <p className="text-sm text-slate-400">Latest employee attendance across shifts and departments.</p>
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <div className="rounded-3xl bg-slate-950/70 px-4 py-3 text-sm text-slate-200">Present: {attendanceSummary.present}</div>
              <div className="rounded-3xl bg-slate-950/70 px-4 py-3 text-sm text-slate-200">Absent: {attendanceSummary.absent}</div>
            </div>
          </div>
          <div className="mt-6">
            <DataTable
              columns={['Employee', 'Department', 'Shift', 'Date', 'Status']}
              rows={displayedAttendance.map((entry) => [
                <div key={entry.id} className="font-semibold text-white">{employeeMap.get(entry.employeeId)?.name || entry.employeeId}</div>,
                employeeMap.get(entry.employeeId)?.department || 'Unknown',
                entry.shift,
                entry.date,
                <StatusBadge key={`${entry.id}-status`} status={entry.status} />,
              ])}
            />
          </div>
          <div className="mt-6">
            <TablePagination page={attendancePage} pageCount={attendancePageCount} onPageChange={setAttendancePage} />
          </div>
        </div>
        <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <div className="mb-5 flex items-center gap-3">
            <div className="flex h-12 w-12 items-center justify-center rounded-3xl bg-slate-700/80 text-slate-200">
              <FaChartLine className="h-5 w-5" />
            </div>
            <div>
              <p className="text-sm uppercase tracking-[0.24em] text-slate-400">Payroll and operations</p>
              <h3 className="text-xl font-semibold text-white">Workforce planning</h3>
            </div>
          </div>
          <div className="grid gap-4">
            <div className="rounded-[28px] border border-white/10 bg-slate-950/70 p-5">
              <p className="text-sm text-slate-400">Active workforce</p>
              <p className="mt-3 text-3xl font-semibold text-white">{activeEmployees}</p>
            </div>
            <div className="rounded-[28px] border border-white/10 bg-slate-950/70 p-5">
              <p className="text-sm text-slate-400">Average salary</p>
              <p className="mt-3 text-3xl font-semibold text-white">{employees.length ? `$${Math.round(totalPayroll / employees.length).toLocaleString()}` : '$0'}</p>
            </div>
          </div>
          <div className="mt-6 rounded-[28px] border border-white/10 bg-slate-950/70 p-5">
            <p className="text-sm text-slate-400">Streamline attendance logging without leaving the roster.</p>
            <form className="mt-4 space-y-4" onSubmit={handleSubmitAttendance(handleAttendanceSubmit)}>
              <FormField label="Employee">
                <select
                  {...registerAttendance('employeeId', { required: 'Employee selection is required' })}
                  className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
                >
                  <option value="">Select employee</option>
                  {employees.map((employee) => (
                    <option key={employee.id} value={employee.id}>{employee.name}</option>
                  ))}
                </select>
                {attendanceErrors.employeeId && <p className="mt-1 text-sm text-rose-400">{attendanceErrors.employeeId.message}</p>}
              </FormField>
              <FormField label="Date">
                <input
                  type="date"
                  {...registerAttendance('date', { required: 'Date is required' })}
                  className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
                />
                {attendanceErrors.date && <p className="mt-1 text-sm text-rose-400">{attendanceErrors.date.message}</p>}
              </FormField>
              <FormField label="Shift">
                <select
                  {...registerAttendance('shift', { required: 'Shift selection is required' })}
                  className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
                >
                  <option value="Day">Day</option>
                  <option value="Afternoon">Afternoon</option>
                  <option value="Night">Night</option>
                </select>
              </FormField>
              <FormField label="Status">
                <select
                  {...registerAttendance('status', { required: 'Status is required' })}
                  className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
                >
                  <option value="Present">Present</option>
                  <option value="Absent">Absent</option>
                  <option value="Late">Late</option>
                </select>
              </FormField>
              <button
                type="submit"
                className="inline-flex w-full items-center justify-center rounded-3xl bg-emerald-500 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 hover-gradient-border"
                disabled={isSubmittingAttendance}
              >
                Record attendance
              </button>
            </form>
          </div>
        </div>
      </div>
      <Modal
        title={isEditMode ? 'Update employee profile' : 'Add new employee'}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        footer={
          <button
            type="button"
            onClick={handleSubmit(onSubmit)}
            disabled={isSubmitting}
            className="rounded-3xl bg-emerald-500 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 disabled:cursor-not-allowed disabled:opacity-60 hover-gradient-border"
          >
            {isEditMode ? 'Update employee' : 'Save employee'}
          </button>
        }
      >
        <form className="grid gap-5 lg:grid-cols-2">
          <FormField label="Full name">
            <input
              type="text"
              {...register('name', { required: 'Name is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="Enter full name"
            />
            {errors.name && <p className="mt-1 text-sm text-rose-400">{errors.name.message}</p>}
          </FormField>
          <FormField label="Email address">
            <input
              type="email"
              {...register('email', {
                required: 'Email is required',
                pattern: { value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, message: 'Enter a valid email' },
              })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="employee@example.edu"
            />
            {errors.email && <p className="mt-1 text-sm text-rose-400">{errors.email.message}</p>}
          </FormField>
          <FormField label="Department">
            <select
              {...register('department', { required: 'Department is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
            >
              {departments.length > 0 ? (
                departments.map((department) => (
                  <option key={department.id} value={department.name}>{department.name}</option>
                ))
              ) : (
                <>
                  <option value="Admissions">Admissions</option>
                  <option value="Finance">Finance</option>
                  <option value="HR">HR</option>
                  <option value="Library">Library</option>
                  <option value="Security">Security</option>
                </>
              )}
            </select>
            {errors.department && <p className="mt-1 text-sm text-rose-400">{errors.department.message}</p>}
          </FormField>
          <FormField label="Designation">
            <input
              type="text"
              {...register('designation', { required: 'Designation is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="e.g., HR Coordinator"
            />
            {errors.designation && <p className="mt-1 text-sm text-rose-400">{errors.designation.message}</p>}
          </FormField>
          <FormField label="Shift">
            <select
              {...register('shift', { required: 'Shift selection is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
            >
              <option value="Day">Day</option>
              <option value="Afternoon">Afternoon</option>
              <option value="Night">Night</option>
            </select>
            {errors.shift && <p className="mt-1 text-sm text-rose-400">{errors.shift.message}</p>}
          </FormField>
          <FormField label="Status">
            <select
              {...register('status', { required: 'Status is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
            >
              <option value="Active">Active</option>
              <option value="On Leave">On Leave</option>
              <option value="Resigned">Resigned</option>
            </select>
            {errors.status && <p className="mt-1 text-sm text-rose-400">{errors.status.message}</p>}
          </FormField>
          <FormField label="Monthly salary">
            <input
              type="number"
              {...register('salary', {
                required: 'Salary is required',
                min: { value: 1000, message: 'Minimum salary 1000' },
              })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="Salary in USD"
            />
            {errors.salary && <p className="mt-1 text-sm text-rose-400">{errors.salary.message}</p>}
          </FormField>
          <FormField label="Joining date">
            <input
              type="date"
              {...register('joinDate', { required: 'Joining date is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
            />
            {errors.joinDate && <p className="mt-1 text-sm text-rose-400">{errors.joinDate.message}</p>}
          </FormField>
        </form>
      </Modal>
    </div>
  );
}

