import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { GripVertical, Pencil, Plus, Search, Trash2 } from 'lucide-react';
import { useForm } from 'react-hook-form';
import { toast } from 'react-toastify';
import api from '../api/axios.js';
import Breadcrumb from '../components/ui/Breadcrumb.jsx';
import Button from '../components/ui/Button.jsx';
import ConfirmDialog from '../components/ui/ConfirmDialog.jsx';
import Modal from '../components/ui/Modal.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';

const FILTER_OPTIONS = [
  'Previous Dues',
  'Transport',
  'Miscellaneous',
  'Cheque Bounce',
  'Fine',
  'Library Fine',
  'Subject Fee',
  'Library Book Security',
  'Library Book Lost Fine',
];

const DEFAULT_FORM_VALUES = {
  feeHeadName: '',
  feeType: 'Fixed',
  displayOrder: 0,
  status: 'Active',
  description: '',
  feeHeadCode: '',
  receiptHead: '',
  feeCategory: '',
  isRefundable: false,
  taxApplicable: false,
};

const getAutoCode = (label) => {
  if (!label) return '';
  return label
    .trim()
    .toUpperCase()
    .replace(/\s+/g, '_')
    .replace(/[^A-Z0-9_]/g, '');
};

export default function FeeHeadManagementPage() {
  const navigate = useNavigate();
  const [items, setItems] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [editorItem, setEditorItem] = useState(null);
  const [removeItem, setRemoveItem] = useState(null);
  const [query, setQuery] = useState('');
  const [selectedFilters, setSelectedFilters] = useState([]);
  const [dragSourceId, setDragSourceId] = useState(null);
  const originalOrder = useRef([]);
  const { register, handleSubmit, reset, watch, formState: { errors } } = useForm({ defaultValues: DEFAULT_FORM_VALUES });

  const loadFeeHeads = async () => {
    setIsLoading(true);
    try {
      const response = await api.get('/coe/fee-heads');
      const fetched = (response.data?.data || []).map((item) => ({
        ...item,
        displayOrder: Number(item.displayOrder ?? item.display_order ?? 0),
      })).sort((a, b) => a.displayOrder - b.displayOrder || a.id - b.id);
      setItems(fetched);
      originalOrder.current = fetched.map((item) => item.id);
    } catch (error) {
      toast.error(error?.response?.data?.detail || 'Unable to load fee heads.');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadFeeHeads();
  }, []);

  const visibleItems = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    const hasFilters = selectedFilters.length > 0;

    return items.filter((item) => {
      const content = `${item.feeHeadName} ${item.feeCategory} ${item.receiptHead}`.toLowerCase();
      if (hasFilters) {
        const matchesFilter = selectedFilters.some((filter) => content.includes(filter.toLowerCase()));
        if (!matchesFilter) return false;
      }
      if (!normalizedQuery) return true;
      return content.includes(normalizedQuery);
    });
  }, [items, query, selectedFilters]);

  const hasOrderChanges = useMemo(() => {
    return items.some((item, index) => item.id !== originalOrder.current[index]);
  }, [items]);

  const handleToggleFilter = (filter) => {
    setSelectedFilters((current) =>
      current.includes(filter)
        ? current.filter((value) => value !== filter)
        : [...current, filter],
    );
  };

  const openCreate = () => {
    reset(DEFAULT_FORM_VALUES);
    setEditorItem(null);
    setShowModal(true);
  };

  const openEdit = (item) => {
    reset({
      feeHeadName: item.feeHeadName || '',
      feeType: item.amountType || 'Fixed',
      displayOrder: Number(item.displayOrder ?? 0),
      status: item.status || 'Active',
      description: item.description || '',
      feeHeadCode: item.feeHeadCode || getAutoCode(item.feeHeadName),
      receiptHead: item.receiptHead || item.feeHeadName || '',
      feeCategory: item.feeCategory || '',
      isRefundable: item.isRefundable ?? false,
      taxApplicable: item.taxApplicable ?? false,
    });
    setEditorItem(item);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setEditorItem(null);
    reset(DEFAULT_FORM_VALUES);
  };

  const handleDragStart = (itemId) => {
    setDragSourceId(itemId);
  };

  const handleDragEnter = (targetId) => {
    if (!dragSourceId || dragSourceId === targetId) return;
    setItems((current) => {
      const sourceIndex = current.findIndex((item) => item.id === dragSourceId);
      const targetIndex = current.findIndex((item) => item.id === targetId);
      if (sourceIndex === -1 || targetIndex === -1) return current;
      const next = [...current];
      const [moved] = next.splice(sourceIndex, 1);
      next.splice(targetIndex, 0, moved);
      return next.map((item, index) => ({ ...item, displayOrder: index + 1 }));
    });
  };

  const handleDragEnd = () => {
    setDragSourceId(null);
  };

  const saveOrder = async () => {
    if (!hasOrderChanges) {
      toast.info('No changes to save.');
      return;
    }

    setIsSaving(true);
    try {
      await Promise.all(
        items.map((item) => api.put(`/coe/fee-heads/${item.id}`, { displayOrder: item.displayOrder })),
      );
      toast.success('Fee head order saved successfully.');
      await loadFeeHeads();
    } catch (error) {
      toast.error(error?.response?.data?.detail || 'Unable to save fee head order.');
    } finally {
      setIsSaving(false);
    }
  };

  const submitFeeHead = async (values) => {
    const payload = {
      feeHeadName: values.feeHeadName.trim(),
      feeHeadCode: values.feeHeadCode.trim() || getAutoCode(values.feeHeadName),
      receiptHead: values.receiptHead.trim() || values.feeHeadName.trim(),
      feeCategory: values.feeCategory.trim() || 'General',
      displayOrder: Number(values.displayOrder ?? items.length + 1),
      amountType: values.feeType,
      isRefundable: values.isRefundable,
      taxApplicable: values.taxApplicable,
      status: values.status,
      description: values.description?.trim() || null,
    };

    try {
      const response = editorItem
        ? await api.put(`/coe/fee-heads/${editorItem.id}`, payload)
        : await api.post('/coe/fee-heads', payload);

      const saved = response.data?.data;
      if (saved) {
        setItems((current) => {
          const next = editorItem
            ? current.map((item) => (item.id === saved.id ? { ...item, ...saved, displayOrder: Number(saved.displayOrder ?? item.displayOrder) } : item))
            : [...current, { ...saved, displayOrder: Number(saved.displayOrder ?? current.length + 1) }];
          return next.sort((a, b) => a.displayOrder - b.displayOrder);
        });
      }

      toast.success(editorItem ? 'Fee head updated successfully.' : 'Fee head created successfully.');
      closeModal();
    } catch (error) {
      toast.error(error?.response?.data?.detail || 'Unable to save fee head.');
    }
  };

  const confirmDelete = async () => {
    if (!removeItem) return;
    try {
      await api.delete(`/coe/fee-heads/${removeItem.id}`);
      setItems((current) => current.map((item) => (item.id === removeItem.id ? { ...item, status: 'Inactive' } : item)));
      toast.success('Fee head deleted successfully.');
      setRemoveItem(null);
    } catch (error) {
      toast.error(error?.response?.data?.detail || 'Unable to delete fee head.');
    }
  };

  return (
    <div className="min-h-[calc(100vh-7rem)] rounded-[24px] border border-slate-200/80 bg-[linear-gradient(135deg,#f8fafc_0%,#ffffff_55%,#f8fafc_100%)] p-3 shadow-[0_18px_45px_rgba(15,23,42,0.06)] lg:p-5">
      <div className="rounded-[22px] border border-slate-200/70 bg-white/95 p-4 shadow-inner sm:p-6">
        <Breadcrumb items={[{ label: 'Dashboard', to: '/' }, { label: 'Fee Structure', to: '/settings/fee-structure' }, { label: 'Fee Head' }]} />

        <div className="mb-8 flex flex-col gap-4 rounded-[24px] border border-slate-200/70 bg-slate-50 px-6 py-5 shadow-sm sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.24em] text-emerald-600">Fee Structure</p>
            <h1 className="mt-2 text-3xl font-semibold tracking-tight text-slate-950">Fee Head</h1>
          </div>
          <Button type="button" onClick={openCreate} className="inline-flex items-center gap-2 px-5 py-3 text-sm font-semibold">
            <Plus className="h-4 w-4" /> New Fee Head
          </Button>
        </div>

        <div className="mb-5 rounded-[24px] border border-slate-200/70 bg-white p-5 shadow-[0_10px_36px_rgba(15,23,42,0.05)]">
          <div className="mb-4 grid gap-3 lg:grid-cols-[1fr_auto]">
            <div className="flex flex-wrap gap-3">
              {FILTER_OPTIONS.map((filter) => (
                <label key={filter} className="inline-flex cursor-pointer items-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700 transition hover:border-emerald-300 hover:bg-emerald-50/70">
                  <input
                    type="checkbox"
                    checked={selectedFilters.includes(filter)}
                    onChange={() => handleToggleFilter(filter)}
                    className="h-4 w-4 rounded border-slate-300 text-emerald-600 focus:ring-emerald-500"
                  />
                  <span>{filter}</span>
                </label>
              ))}
            </div>
            <div className="relative max-w-sm">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <input
                type="search"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="Search fee heads..."
                className="w-full rounded-2xl border border-slate-200 bg-slate-50 py-3 pl-10 pr-4 text-sm text-slate-900 outline-none transition focus:border-emerald-500"
              />
            </div>
          </div>

          <div className="overflow-hidden rounded-[30px] border border-slate-200 bg-white px-1 py-1 shadow-sm">
            {isLoading ? (
              <div className="py-20 text-center text-sm text-slate-500">Loading fee heads...</div>
            ) : visibleItems.length === 0 ? (
              <div className="py-20 text-center text-sm text-slate-500">No fee heads found. Adjust filters, search, or add a new fee head.</div>
            ) : (
              <div className="space-y-3">
                {visibleItems.map((item, index) => (
                  <article
                    key={item.id}
                    draggable
                    onDragStart={() => handleDragStart(item.id)}
                    onDragOver={(event) => event.preventDefault()}
                    onDragEnter={() => handleDragEnter(item.id)}
                    onDragEnd={handleDragEnd}
                    className="group flex items-center justify-between gap-4 rounded-[20px] border border-slate-200 bg-white px-4 py-4 shadow-sm transition duration-200 hover:-translate-y-0.5 hover:shadow-md"
                  >
                    <div className="flex min-w-0 items-center gap-4">
                      <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-slate-100 text-sm font-semibold text-slate-700">
                        {index + 1}
                      </div>
                      <div className="min-w-0">
                        <p className="truncate text-sm font-semibold text-slate-950">{item.feeHeadName || 'Untitled Fee Head'}</p>
                        <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-slate-500">
                          <span>{item.feeCategory || 'General'}</span>
                          <span>•</span>
                          <span>{item.status || 'Active'}</span>
                        </div>
                      </div>
                    </div>

                    <div className="hidden min-w-[180px] items-center gap-2 sm:flex">
                      <StatusBadge status={item.status} />
                      <span className="rounded-full bg-slate-100 px-2 py-1 text-[11px] font-semibold uppercase tracking-[0.16em] text-slate-500">Order {item.displayOrder}</span>
                    </div>

                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => openEdit(item)}
                        className="inline-flex h-10 w-10 items-center justify-center rounded-full border border-slate-200 bg-slate-50 text-slate-600 transition hover:border-emerald-300 hover:bg-emerald-50 hover:text-emerald-700"
                        aria-label="Edit fee head"
                      >
                        <Pencil className="h-4 w-4" />
                      </button>
                      <button
                        type="button"
                        onClick={() => setRemoveItem(item)}
                        className="inline-flex h-10 w-10 items-center justify-center rounded-full border border-slate-200 bg-white text-rose-600 transition hover:border-rose-300 hover:bg-rose-50"
                        aria-label="Delete fee head"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                      <span className="inline-flex h-10 w-10 cursor-grab items-center justify-center rounded-full border border-slate-200 bg-slate-50 text-slate-500 transition hover:bg-slate-100" title="Drag to reorder">
                        <GripVertical className="h-4 w-4" />
                      </span>
                    </div>
                  </article>
                ))}
              </div>
            )}
          </div>

          <p className="mt-6 text-center text-sm text-slate-500">
            To change the order of Fee Heads you can use drag and drop and then click Save.
          </p>

          <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:justify-center">
            <Button type="button" onClick={saveOrder} disabled={!hasOrderChanges || isSaving} isLoading={isSaving} className="min-w-[150px]">
              Save
            </Button>
            <Button type="button" variant="secondary" onClick={() => navigate('/settings/fee-structure/fee-head-group')} className="min-w-[150px]">
              Next
            </Button>
          </div>
        </div>
      </div>

      <Modal
        title={editorItem ? 'Edit Fee Head' : 'New Fee Head'}
        isOpen={showModal}
        onClose={closeModal}
        footer={
          <>
            <Button type="button" variant="secondary" onClick={closeModal}>
              Cancel
            </Button>
            <Button type="submit" form="fee-head-form" isLoading={false}>
              Save
            </Button>
          </>
        }
      >
        <form id="fee-head-form" onSubmit={handleSubmit(submitFeeHead)} className="grid gap-4 sm:grid-cols-2">
          <label className="space-y-2">
            <span className="block text-sm font-semibold text-slate-700">Fee Head Name *</span>
            <input
              type="text"
              {...register('feeHeadName', { required: 'Fee Head Name is required' })}
              className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500"
            />
            {errors.feeHeadName && <p className="text-xs text-rose-600">{errors.feeHeadName.message}</p>}
          </label>

          <label className="space-y-2">
            <span className="block text-sm font-semibold text-slate-700">Fee Type *</span>
            <select
              {...register('feeType', { required: 'Fee Type is required' })}
              className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500"
            >
              <option value="Fixed">Fixed</option>
              <option value="Variable">Variable</option>
            </select>
            {errors.feeType && <p className="text-xs text-rose-600">{errors.feeType.message}</p>}
          </label>

          <label className="space-y-2 sm:col-span-2">
            <span className="block text-sm font-semibold text-slate-700">Description</span>
            <textarea
              rows="4"
              {...register('description')}
              className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500"
            />
          </label>

          <label className="space-y-2">
            <span className="block text-sm font-semibold text-slate-700">Display Order</span>
            <input
              type="number"
              {...register('displayOrder', {
                valueAsNumber: true,
                min: { value: 0, message: 'Order must be zero or greater' },
              })}
              className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500"
            />
            {errors.displayOrder && <p className="text-xs text-rose-600">{errors.displayOrder.message}</p>}
          </label>

          <label className="space-y-2">
            <span className="block text-sm font-semibold text-slate-700">Status</span>
            <select
              {...register('status', { required: 'Status is required' })}
              className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500"
            >
              <option value="Active">Active</option>
              <option value="Inactive">Inactive</option>
            </select>
            {errors.status && <p className="text-xs text-rose-600">{errors.status.message}</p>}
          </label>

          <input type="hidden" {...register('feeHeadCode')} />
          <input type="hidden" {...register('receiptHead')} />
          <input type="hidden" {...register('feeCategory')} />
          <input type="hidden" {...register('isRefundable')} />
          <input type="hidden" {...register('taxApplicable')} />
        </form>
      </Modal>

      <ConfirmDialog
        open={Boolean(removeItem)}
        title="Delete fee head?"
        description="This will move the fee head to inactive status and preserve its record."
        confirmLabel="Delete"
        onCancel={() => setRemoveItem(null)}
        onConfirm={confirmDelete}
      />
    </div>
  );
}

import { useMemo, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import {
  useResourceList,
  useBulkImport,
  useBulkExport,
} from '../hooks/useResourceHooks';
import {
  FaDownload,
  FaFileImport,
  FaPlus,
} from 'react-icons/fa';
import SectionHeader from '../components/ui/SectionHeader.jsx';
import SearchFilter from '../components/forms/SearchFilter.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import TablePagination from '../components/tables/TablePagination.jsx';
import Modal from '../components/ui/Modal.jsx';
import FormField from '../components/forms/FormField.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';
import { createPayment, cancelPayment } from '../services/paymentService.js';
import { downloadReceiptPdf } from '../services/receiptService.js';
import { calculateStudentLedger } from '../services/feeService.js';

const statusOptions = [
  { value: 'All', label: 'All statuses' },
  { value: 'Paid', label: 'Paid' },
  { value: 'Pending', label: 'Pending' },
  { value: 'Cancelled', label: 'Cancelled' },
];

const defaultPaymentValues = {
  studentId: '',
  amount: '',
  date: new Date().toISOString().slice(0, 10),
  method: 'Cash',
  status: 'Paid',
  installmentNumber: '',
  scholarshipAmount: 0,
  discountAmount: 0,
  waiverAmount: 0,
  fine: 0,
  notes: '',
};

function downloadBlob(blob, filename) {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
}

function formatCurrency(value) {
  const amount = Number(value || 0);
  return `$${amount.toLocaleString()}`;
}

function normalizeSearchValue(value) {
  return String(value || '').toLowerCase();
}

export default function FeeManagementPage() {
  const importInputRef = useRef(null);
  const queryClient = useQueryClient();

  const { data: paymentsData } = useResourceList('payments', { page: 1, pageSize: 200 });
  const { data: studentsData } = useResourceList('students', { page: 1, pageSize: 200 });
  const { data: receiptsData } = useResourceList('receipts', { page: 1, pageSize: 200 });
  const { data: scholarshipsData } = useResourceList('scholarships', { page: 1, pageSize: 200 });

  const payments = paymentsData?.items || [];
  const students = studentsData?.items || [];
  const receipts = receiptsData?.items || [];
  const scholarships = scholarshipsData?.items || [];

  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [courseFilter, setCourseFilter] = useState('All');
  const [departmentFilter, setDepartmentFilter] = useState('All');
  const [page, setPage] = useState(1);
  const [selectedStudentId, setSelectedStudentId] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [importStatus, setImportStatus] = useState('');
  const pageSize = 6;

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm({ defaultValues: defaultPaymentValues });

  const selectedStudent = students.find((student) => student.id === selectedStudentId) || null;

  const studentMap = useMemo(() => new Map(students.map((student) => [student.id, student])), [students]);

  const filteredPayments = useMemo(() => {
    const normalizedQuery = normalizeSearchValue(search);

    return payments.filter((payment) => {
      const student = studentMap.get(payment.studentId) || {};
      const studentName = normalizeSearchValue(student.name);
      const admissionNo = normalizeSearchValue(student.enrollmentNo);
      const receiptNumber = normalizeSearchValue(payment.receiptNumber);
      const status = normalizeSearchValue(payment.status);
      const method = normalizeSearchValue(payment.method);
      const courseId = student.courseId || '';
      const departmentId = student.departmentId || '';

      const matchesSearch = [studentName, admissionNo, receiptNumber, method, status, payment.paymentId, payment.id]
        .filter(Boolean)
        .some((field) => normalizeSearchValue(field).includes(normalizedQuery));

      const matchesStatus = statusFilter === 'All' || normalizeSearchValue(statusFilter) === status;
      const matchesCourse = courseFilter === 'All' || courseFilter === courseId;
      const matchesDepartment = departmentFilter === 'All' || departmentFilter === departmentId;

      return matchesSearch && matchesStatus && matchesCourse && matchesDepartment;
    });
  }, [payments, search, statusFilter, courseFilter, departmentFilter, studentMap]);

  const pageCount = Math.max(1, Math.ceil(filteredPayments.length / pageSize));
  const displayedPayments = filteredPayments.slice((page - 1) * pageSize, page * pageSize);

  const paymentSummary = useMemo(() => {
    const today = new Date().toISOString().slice(0, 10);
    const monthly = new Date().getMonth();
    const year = new Date().getFullYear();

    return payments.reduce(
      (summary, payment) => {
        const paidValue = Number(payment.amount || 0);
        const scholarshipValue = Number(payment.scholarshipAmount || 0);
        const fineValue = Number(payment.fine || 0);
        const dateValue = payment.paidAt || payment.date || payment.createdAt || '';
        const paidAt = new Date(dateValue);
        const paidDateKey = paidAt.toISOString().slice(0, 10);

        if (payment.status === 'Paid') {
          summary.totalCollection += paidValue;
          summary.paidTransactions += 1;
          summary.scholarshipTotal += scholarshipValue;
          summary.fineCollected += fineValue;
          if (paidDateKey === today) summary.todaysCollection += paidValue;
          if (paidAt.getMonth() === monthly && paidAt.getFullYear() === year) summary.monthlyCollection += paidValue;
        }

        if (payment.status === 'Pending') {
          summary.pendingAmount += paidValue;
        }

        if (payment.status === 'Pending' && payment.dueDate) {
          const dueDate = new Date(payment.dueDate);
          if (dueDate < new Date()) {
            summary.overdueStudents.add(payment.studentId);
          }
        }

        return summary;
      },
      {
        totalCollection: 0,
        paidTransactions: 0,
        monthlyCollection: 0,
        todaysCollection: 0,
        pendingAmount: 0,
        scholarshipTotal: 0,
        fineCollected: 0,
        overdueStudents: new Set(),
      },
    );
  }, [payments]);

  const studentPayments = useMemo(
    () => (selectedStudent ? payments.filter((payment) => payment.studentId === selectedStudent.id) : []),
    [payments, selectedStudent],
  );
  const studentScholarships = useMemo(
    () => (selectedStudent ? scholarships.filter((scholarship) => scholarship.studentId === selectedStudent.id) : []),
    [scholarships, selectedStudent],
  );

  const studentLedger = useMemo(() => {
    if (!selectedStudent) return null;
    return calculateStudentLedger(selectedStudent, studentPayments, studentScholarships);
  }, [selectedStudent, studentPayments, studentScholarships]);

  const createPaymentMutation = useMutation({
    mutationFn: createPayment,
    onSuccess: () => {
      queryClient.invalidateQueries(['payments']);
      queryClient.invalidateQueries(['receipts']);
      queryClient.invalidateQueries(['students']);
      setImportStatus('Payment recorded successfully.');
    },
  });

  const cancelPaymentMutation = useMutation({
    mutationFn: cancelPayment,
    onSuccess: () => {
      queryClient.invalidateQueries(['payments']);
      setImportStatus('Payment cancelled and audit logged.');
    },
  });


  const importPayments = useBulkImport('payments');
  const exportPayments = useBulkExport('payments');

  const handleImport = (file) => {
    if (!file) return;
    setImportStatus('Importing payments…');
    const formData = new FormData();
    formData.append('file', file);
    importPayments.mutate(formData, {
      onSuccess: () => setImportStatus('Payments imported successfully.'),
      onError: () => setImportStatus('Import failed. Please check the CSV format and try again.'),
    });
  };

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];
    handleImport(file);
    event.target.value = '';
  };

  const handleExport = async () => {
    try {
      const blob = await exportPayments.mutateAsync();
      downloadBlob(blob, 'payments-export.xlsx');
    } catch (error) {
      console.error(error);
    }
  };

  const handleSubmitPayment = async (data) => {
    const student = students.find((item) => item.id === data.studentId);
    const paymentPayload = {
      ...data,
      studentName: student?.name || '',
      departmentId: student?.departmentId || '',
      courseId: student?.courseId || '',
      receiptNumber: data.receiptNumber || undefined,
      paymentId: data.paymentId || undefined,
    };
    await createPaymentMutation.mutateAsync(paymentPayload, {
      onSuccess: () => {
        reset(defaultPaymentValues);
        setPage(1);
        setIsModalOpen(false);
      },
    });
  };

  const handleCancelPayment = (id) => {
    cancelPaymentMutation.mutate(id);
  };

  const handleDownloadReceipt = async (receipt) => {
    try {
      const blob = await downloadReceiptPdf(receipt);
      downloadBlob(blob, `${receipt.receiptNumber}.pdf`);
    } catch (error) {
      console.error(error);
    }
  };

  const courseOptions = useMemo(
    () => ['All', ...Array.from(new Set(students.map((student) => student.courseId).filter(Boolean)))],
    [students],
  );
  const departmentOptions = useMemo(
    () => ['All', ...Array.from(new Set(students.map((student) => student.departmentId).filter(Boolean)))],
    [students],
  );

  return (
    <div className="space-y-6">
      <SectionHeader
        title="Fee management"
        subtitle="Manage fee collections, overdue balances, receipts and payment reconciliation."
        action={
          <div className="flex flex-wrap items-center gap-3">
            <button
              type="button"
              onClick={handleExport}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700 hover-gradient-border"
            >
              <FaDownload /> Export fees
            </button>
            <button
              type="button"
              onClick={() => importInputRef.current?.click()}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700"
            >
              <FaFileImport /> Import CSV
            </button>
            <button
              type="button"
              onClick={() => setIsModalOpen(true)}
              className="inline-flex items-center gap-2 rounded-3xl bg-sky-400 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-sky-300"
            >
              <FaPlus /> Record payment
            </button>
          </div>
        }
      />

      <input ref={importInputRef} type="file" accept=".csv" className="hidden hover-gradient-border" onChange={handleFileChange} />

      <div className="grid gap-3 md:grid-cols-3">
        <div className="hover-gradient-border rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Today&apos;s collection</p>
          <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(paymentSummary.todaysCollection)}</p>
        </div>
        <div className="hover-gradient-border rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Monthly collection</p>
          <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(paymentSummary.monthlyCollection)}</p>
        </div>
        <div className="hover-gradient-border rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Pending amount</p>
          <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(paymentSummary.pendingAmount)}</p>
        </div>
      </div>

      <div className="grid gap-3 md:grid-cols-3">
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Overdue students</p>
          <p className="mt-3 text-2xl font-semibold text-white">{paymentSummary.overdueStudents.size}</p>
        </div>
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Scholarship total</p>
          <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(paymentSummary.scholarshipTotal)}</p>
        </div>
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Fine collected</p>
          <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(paymentSummary.fineCollected)}</p>
        </div>
      </div>

      {importStatus && (
        <div className="rounded-[28px] border border-emerald-500/20 bg-emerald-500/5 p-4 text-sm text-emerald-200">{importStatus}</div>
      )}

      <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
        <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h2 className="text-xl font-semibold text-white">Fee ledger</h2>
            <p className="text-sm text-slate-400">Review receipts, reconcile pending dues, and keep fee records audit-ready.</p>
          </div>
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <SearchFilter search={search} onSearch={setSearch} filter={statusFilter} onFilter={setStatusFilter} options={statusOptions} />
            <div className="rounded-[16px] border border-slate-200/70 bg-white/95 p-3 shadow-sm">
              <label className="mb-1.5 block text-[11px] uppercase tracking-[0.24em] text-slate-500">Course</label>
              <select
                value={courseFilter}
                onChange={(e) => setCourseFilter(e.target.value)}
                className="h-10 w-full rounded-2xl border border-slate-200/70 bg-slate-50 px-3 text-sm text-slate-900 outline-none"
              >
                {courseOptions.map((course) => (
                  <option key={course} value={course}>{course}</option>
                ))}
              </select>
            </div>
            <div className="rounded-[16px] border border-slate-200/70 bg-white/95 p-3 shadow-sm">
              <label className="mb-1.5 block text-[11px] uppercase tracking-[0.24em] text-slate-500">Department</label>
              <select
                value={departmentFilter}
                onChange={(e) => setDepartmentFilter(e.target.value)}
                className="h-10 w-full rounded-2xl border border-slate-200/70 bg-slate-50 px-3 text-sm text-slate-900 outline-none"
              >
                {departmentOptions.map((department) => (
                  <option key={department} value={department}>{department}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        <div className="mt-4 grid gap-3 md:grid-cols-3">
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Total collection</p>
            <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(paymentSummary.totalCollection)}</p>
            <p className="text-sm text-slate-400">{paymentSummary.paidTransactions} paid receipts</p>
          </div>
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Total pending</p>
            <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(paymentSummary.pendingAmount)}</p>
            <p className="text-sm text-slate-400">Pending payments awaiting collection</p>
          </div>
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Overdue</p>
            <p className="mt-3 text-2xl font-semibold text-white">{paymentSummary.overdueStudents.size}</p>
            <p className="text-sm text-slate-400">Students with overdue fee installments</p>
          </div>
        </div>

        <div className="mt-4 overflow-x-auto rounded-[20px] border border-slate-700/60 bg-slate-900/80">
          <DataTable
            compact
            columns={['Student', 'Admission No', 'Receipt', 'Amount', 'Date', 'Status', 'Actions']}
            rows={displayedPayments.map((payment) => {
              const student = studentMap.get(payment.studentId) || {};
              return [
                <div key={payment.id} className="space-y-1">
                  <p className="font-semibold text-white">{student.name || 'Unknown'}</p>
                  <p className="text-sm text-slate-400">{student.courseId || student.departmentId || 'N/A'}</p>
                </div>,
                student.enrollmentNo || 'N/A',
                payment.receiptNumber || payment.paymentId || 'N/A',
                formatCurrency(payment.amount),
                payment.paidAt?.slice(0, 10) || payment.date || 'N/A',
                <StatusBadge key={`${payment.id}-status`} status={payment.status || 'Pending'} />,
                <div key={`${payment.id}-actions`} className="flex flex-wrap gap-2">
                  <button
                    key={`${payment.id}-receipt`}
                    type="button"
                    onClick={() => payment.receiptNumber && handleDownloadReceipt(receipts.find((receipt) => receipt.receiptNumber === payment.receiptNumber) || { receiptNumber: payment.receiptNumber, studentName: student.name, amount: payment.amount, paymentMethod: payment.method, date: payment.paidAt?.slice(0, 10) || payment.date })}
                    className="rounded-full bg-slate-700 px-3 py-2 text-xs font-medium text-slate-100 hover:bg-slate-600"
                  >
                    Receipt
                  </button>
                  {payment.status !== 'Cancelled' && (
                    <button
                      key={`${payment.id}-cancel`}
                      type="button"
                      onClick={() => handleCancelPayment(payment.id)}
                      className="rounded-full bg-rose-600 px-3 py-2 text-xs font-medium text-white hover:bg-rose-500"
                    >
                      Cancel
                    </button>
                  )}
                </div>,
              ];
            })}
          />
        </div>
        <div className="mt-4 flex items-center justify-between">
          <TablePagination page={page} pageCount={pageCount} onPageChange={setPage} />
        </div>
      </div>

      <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-xl font-semibold text-white">Student fee ledger</h2>
            <p className="text-sm text-slate-400">Select a student to review their fee balance, scholarship, and installment history.</p>
          </div>
          <div className="rounded-[16px] border border-slate-200/70 bg-white/95 p-3 shadow-sm">
            <label className="mb-1.5 block text-[11px] uppercase tracking-[0.24em] text-slate-500">Student</label>
            <select
              value={selectedStudentId}
              onChange={(e) => setSelectedStudentId(e.target.value)}
              className="h-12 w-full rounded-2xl border border-slate-200/70 bg-slate-50 px-3 text-sm text-slate-900 outline-none"
            >
              <option value="">Choose a student</option>
              {students.map((student) => (
                <option key={student.id} value={student.id}>{student.name} · {student.enrollmentNo}</option>
              ))}
            </select>
          </div>
        </div>

        {selectedStudent ? (
          <div className="mt-5 grid gap-3 md:grid-cols-3">
            <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Total fee</p>
              <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(studentLedger?.totalFee)}</p>
            </div>
            <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Paid</p>
              <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(studentLedger?.paidAmount)}</p>
            </div>
            <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Outstanding balance</p>
              <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(studentLedger?.balance)}</p>
            </div>
          </div>
        ) : (
          <div className="mt-5 rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4 text-sm text-slate-300">
            Select a student to see their ledger details and installment history.
          </div>
        )}

        {selectedStudent && (
          <div className="mt-4 grid gap-3 md:grid-cols-3">
            <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Scholarship</p>
              <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(studentLedger?.scholarshipAmount)}</p>
            </div>
            <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Discount / waiver</p>
              <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(studentLedger?.waiver)}</p>
            </div>
            <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Fine</p>
              <p className="mt-3 text-2xl font-semibold text-white">{formatCurrency(studentLedger?.fine)}</p>
            </div>
          </div>
        )}

        {selectedStudent && (
          <div className="mt-4 overflow-x-auto rounded-[20px] border border-slate-700/60 bg-slate-900/80">
            <DataTable
              compact
              columns={['Receipt', 'Amount', 'Installment', 'Status', 'Date']}
              rows={studentPayments.map((payment) => [
                payment.receiptNumber || payment.paymentId,
                formatCurrency(payment.amount),
                payment.installmentNumber || 'N/A',
                <StatusBadge key={`${payment.id}-status`} status={payment.status || 'Pending'} />,
                payment.paidAt?.slice(0, 10) || payment.date || 'N/A',
              ])}
            />
          </div>
        )}
      </div>

      <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-xl font-semibold text-white">Reports</h2>
            <p className="text-sm text-slate-400">Generate daily, monthly, outstanding, scholarship and fine reports for fee operations.</p>
          </div>
          <div className="flex flex-wrap gap-3">
            <button type="button" className="rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border">Daily report</button>
            <button type="button" className="rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border">Monthly report</button>
            <button type="button" className="rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border">Outstanding report</button>
          </div>
        </div>

        <div className="mt-4 grid gap-3 md:grid-cols-3">
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Payment history</p>
            <p className="mt-3 text-2xl font-semibold text-white">{payments.length}</p>
            <p className="text-sm text-slate-400">Total recorded payment actions</p>
          </div>
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Receipts</p>
            <p className="mt-3 text-2xl font-semibold text-white">{receipts.length}</p>
            <p className="text-sm text-slate-400">Generated payment receipts</p>
          </div>
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Scholarships</p>
            <p className="mt-3 text-2xl font-semibold text-white">{scholarships.length}</p>
            <p className="text-sm text-slate-400">Scholarship adjustments available</p>
          </div>
        </div>
      </div>

      <Modal
        title="Record fee payment"
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        footer={
          <button
            type="button"
            onClick={handleSubmit(handleSubmitPayment)}
            disabled={isSubmitting || createPaymentMutation.isLoading}
            className="rounded-3xl bg-sky-400 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-sky-300 disabled:cursor-not-allowed disabled:opacity-60 hover-gradient-border"
          >
            Save payment
          </button>
        }
      >
        <form className="grid gap-5 lg:grid-cols-2">
          <FormField label="Student">
            <select
              {...register('studentId', { required: 'Student is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
            >
              <option value="">Select student</option>
              {students.map((student) => (
                <option key={student.id} value={student.id}>{student.name} · {student.enrollmentNo}</option>
              ))}
            </select>
            {errors.studentId && <p className="mt-1 text-sm text-rose-400">{errors.studentId.message}</p>}
          </FormField>
          <FormField label="Amount">
            <input
              type="number"
              {...register('amount', { required: 'Amount is required', min: { value: 1, message: 'Enter a valid amount' } })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
              placeholder="0"
            />
            {errors.amount && <p className="mt-1 text-sm text-rose-400">{errors.amount.message}</p>}
          </FormField>
          <FormField label="Scholarship adjustment">
            <input
              type="number"
              {...register('scholarshipAmount')}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
              placeholder="0"
            />
          </FormField>
          <FormField label="Discount / waiver">
            <input
              type="number"
              {...register('waiverAmount')}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
              placeholder="0"
            />
          </FormField>
          <FormField label="Fine / late fee">
            <input
              type="number"
              {...register('fine')}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
              placeholder="0"
            />
          </FormField>
          <FormField label="Discount amount">
            <input
              type="number"
              {...register('discountAmount')}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
              placeholder="0"
            />
          </FormField>
          <FormField label="Installment number">
            <input
              type="text"
              {...register('installmentNumber')}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
              placeholder="1/3"
            />
          </FormField>
          <FormField label="Payment date">
            <input
              type="date"
              {...register('date', { required: 'Date is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
            />
            {errors.date && <p className="mt-1 text-sm text-rose-400">{errors.date.message}</p>}
          </FormField>
          <FormField label="Payment method">
            <select
              {...register('method', { required: 'Method is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
            >
              <option value="Cash">Cash</option>
              <option value="UPI">UPI</option>
              <option value="Card">Card</option>
              <option value="Net Banking">Net Banking</option>
              <option value="Cheque">Cheque</option>
              <option value="Bank Transfer">Bank Transfer</option>
            </select>
          </FormField>
          <FormField label="Status">
            <select
              {...register('status', { required: 'Status is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
            >
              <option value="Paid">Paid</option>
              <option value="Pending">Pending</option>
              <option value="Cancelled">Cancelled</option>
            </select>
          </FormField>
          <FormField label="Notes">
            <textarea
              {...register('notes')}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border"
              rows={4}
              placeholder="Payment notes or reference"
            />
          </FormField>
        </form>
      </Modal>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { CheckCircle2 } from 'lucide-react';
import { useQueryClient } from '@tanstack/react-query';
import { useResourceList } from '../hooks/useResourceHooks';
import SectionHeader from '../components/ui/SectionHeader.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import Modal from '../components/ui/Modal.jsx';
import FormField from '../components/forms/FormField.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';
import IconActionButton from '../components/ui/IconActionButton.jsx';
import { calculateTrialBalance, createChartOfAccount } from '../services/financeService.js';
import { summarizeLedger, createLedgerEntry, approveLedgerEntry } from '../services/ledgerService.js';
import { createVoucher, postVoucher, buildVoucherSummary } from '../services/voucherService.js';
import { createBudget, calculateBudgetVariance } from '../services/budgetService.js';
import { createBankAccount, getBankBalance } from '../services/bankService.js';

const defaults = {
  name: '',
  type: 'Assets',
  group: 'Current Assets',
  openingBalance: 0,
  accountCode: '',
  debit: 0,
  credit: 0,
  amount: 0,
  voucherType: 'Journal Voucher',
  status: 'Draft',
  period: '',
};

export default function FinanceAccountingPage() {
  const queryClient = useQueryClient();
  const [activeSection, setActiveSection] = useState('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isEntryModalOpen, setIsEntryModalOpen] = useState(false);
  const [isVoucherModalOpen, setIsVoucherModalOpen] = useState(false);
  const [isBudgetModalOpen, setIsBudgetModalOpen] = useState(false);
  const [isBankModalOpen, setIsBankModalOpen] = useState(false);
  const [form, setForm] = useState(defaults);
  const [busyMessage, setBusyMessage] = useState('');

  const { data: accountsData } = useResourceList('chartOfAccounts', { page: 1, pageSize: 200 });
  const { data: ledgerData } = useResourceList('journalEntries', { page: 1, pageSize: 200 });
  const { data: vouchersData } = useResourceList('vouchers', { page: 1, pageSize: 200 });
  const { data: budgetsData } = useResourceList('budgets', { page: 1, pageSize: 200 });
  const { data: banksData } = useResourceList('bankAccounts', { page: 1, pageSize: 200 });

  const accounts = accountsData?.items || [];
  const entries = ledgerData?.items || [];
  const vouchers = vouchersData?.items || [];
  const budgets = budgetsData?.items || [];
  const bankAccounts = banksData?.items || [];

  const trialBalance = useMemo(() => calculateTrialBalance(accounts, entries), [accounts, entries]);
  const ledgerSummary = useMemo(() => summarizeLedger(entries), [entries]);
  const voucherSummary = useMemo(() => buildVoucherSummary(vouchers), [vouchers]);
  const bankBalance = useMemo(() => getBankBalance(bankAccounts), [bankAccounts]);

  const filteredAccounts = useMemo(() => {
    const search = searchTerm.toLowerCase();
    return accounts.filter((account) => [account.name, account.type, account.group, account.accountCode].filter(Boolean).some((value) => String(value).toLowerCase().includes(search)));
  }, [accounts, searchTerm]);

  const handleAccountSubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Saving account…');
    await createChartOfAccount({
      name: form.name,
      type: form.type,
      group: form.group,
      accountCode: form.accountCode || `ACC-${Date.now()}`,
      openingBalance: Number(form.openingBalance || 0),
    });
    queryClient.invalidateQueries(['chartOfAccounts']);
    setBusyMessage('');
    setIsAccountModalOpen(false);
    setForm(defaults);
  };

  const handleEntrySubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Posting journal entry…');
    await createLedgerEntry({
      description: form.name,
      debit: Number(form.debit || 0),
      credit: Number(form.credit || 0),
      accountId: form.accountCode,
      status: 'Posted',
      period: form.period,
    });
    queryClient.invalidateQueries(['journalEntries']);
    setBusyMessage('');
    setIsEntryModalOpen(false);
    setForm(defaults);
  };

  const handleVoucherSubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Preparing voucher…');
    await createVoucher({
      voucherType: form.voucherType,
      amount: Number(form.amount || 0),
      status: 'Draft',
      date: form.period,
      prefix: form.voucherType === 'Receipt Voucher' ? 'RV' : form.voucherType === 'Payment Voucher' ? 'PV' : 'JV',
      sequence: vouchers.length + 1,
    });
    queryClient.invalidateQueries(['vouchers']);
    setBusyMessage('');
    setIsVoucherModalOpen(false);
    setForm(defaults);
  };

  const handleBudgetSubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Saving budget…');
    await createBudget({
      name: form.name,
      amount: Number(form.amount || 0),
      period: form.period,
      department: form.group,
    });
    queryClient.invalidateQueries(['budgets']);
    setBusyMessage('');
    setIsBudgetModalOpen(false);
    setForm(defaults);
  };

  const handleBankSubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Saving bank account…');
    await createBankAccount({ name: form.name, balance: Number(form.openingBalance || 0), accountCode: form.accountCode || `BNK-${Date.now()}` });
    queryClient.invalidateQueries(['bankAccounts']);
    setBusyMessage('');
    setIsBankModalOpen(false);
    setForm(defaults);
  };

  const approveEntry = async (entry) => {
    await approveLedgerEntry(entry.id, { remarks: 'Approved from finance module' });
    queryClient.invalidateQueries(['journalEntries']);
  };

  const postVoucherEntry = async (voucher) => {
    await postVoucher(voucher.id);
    queryClient.invalidateQueries(['vouchers']);
  };

  return (
    <div className="space-y-6">
      <SectionHeader
        title="Finance & accounting"
        subtitle="Chart of accounts, ledger posting, vouchers, banks, budget controls, and management reports."
        action={
          <div className="flex flex-wrap items-center gap-3">
            <button type="button" onClick={() => setIsAccountModalOpen(true)} className="rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200">Add account</button>
            <button type="button" onClick={() => setIsEntryModalOpen(true)} className="rounded-3xl bg-emerald-500 px-4 py-3 text-sm font-semibold text-slate-950">Post entry</button>
            <button type="button" onClick={() => setIsVoucherModalOpen(true)} className="rounded-3xl border border-slate-300 bg-white px-4 py-3 text-sm font-semibold text-slate-700">Create voucher</button>
          </div>
        }
      />

      {busyMessage ? <div className="rounded-3xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{busyMessage}</div> : null}

      <div className="rounded-[24px] border border-slate-200 bg-slate-50 p-4 shadow-sm">
        <div className="flex flex-wrap gap-2">
          {['overview', 'accounts', 'ledger', 'vouchers', 'budget', 'bank', 'reports'].map((tab) => (
            <button key={tab} type="button" onClick={() => setActiveSection(tab)} className={`rounded-2xl border px-4 py-2 text-sm font-medium transition ${activeSection === tab ? 'border-slate-900 bg-slate-900 text-white' : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-100'}`}>
              {tab === 'overview' ? 'Overview' : tab === 'accounts' ? 'Chart of Accounts' : tab === 'ledger' ? 'Ledger' : tab === 'vouchers' ? 'Vouchers' : tab === 'budget' ? 'Budget' : tab === 'bank' ? 'Bank' : 'Reports'}
            </button>
          ))}
        </div>
      </div>

      {activeSection === 'overview' && (
        <div className="grid gap-4 xl:grid-cols-[1.2fr_0.8fr]">
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Today’s collection</p><p className="mt-3 text-2xl font-semibold text-slate-950">₹{entries.reduce((sum, entry) => sum + Number(entry.debit || 0), 0).toLocaleString()}</p></div>
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Today’s payments</p><p className="mt-3 text-2xl font-semibold text-slate-950">₹{entries.reduce((sum, entry) => sum + Number(entry.credit || 0), 0).toLocaleString()}</p></div>
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Cash balance</p><p className="mt-3 text-2xl font-semibold text-slate-950">₹{bankBalance.toLocaleString()}</p></div>
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Monthly revenue</p><p className="mt-3 text-2xl font-semibold text-slate-950">₹{voucherSummary.amount.toLocaleString()}</p></div>
          </div>
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Finance integrations</h3>
            <div className="mt-4 space-y-2 text-sm text-slate-600">
              <div className="rounded-2xl bg-slate-50 p-3">Student fees</div>
              <div className="rounded-2xl bg-slate-50 p-3">Payroll</div>
              <div className="rounded-2xl bg-slate-50 p-3">Hostel fees</div>
              <div className="rounded-2xl bg-slate-50 p-3">Transport fees</div>
              <div className="rounded-2xl bg-slate-50 p-3">Library fines</div>
            </div>
          </div>
        </div>
      )}

      {activeSection === 'accounts' && (
        <div className="space-y-4">
          <div className="flex flex-wrap items-center gap-3 rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <input type="search" value={searchTerm} onChange={(event) => setSearchTerm(event.target.value)} placeholder="Search accounts" className="w-full max-w-md rounded-3xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none" />
            <button type="button" onClick={() => setIsAccountModalOpen(true)} className="rounded-3xl border border-slate-300 bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-700">New account</button>
          </div>
          <DataTable columns={[
            { label: 'Account', key: 'name', sortable: true },
            { label: 'Code', key: 'accountCode', sortable: true },
            { label: 'Type', key: 'type', sortable: true },
            { label: 'Group', key: 'group', sortable: true },
            { label: 'Opening balance', key: 'openingBalance', sortable: true, render: (value) => `₹${Number(value || 0).toLocaleString()}` },
          ]} rows={filteredAccounts} initialPageSize={8} placeholder="Search chart of accounts" />
        </div>
      )}

      {activeSection === 'ledger' && (
        <div className="space-y-4">
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Ledger summary</h3>
            <div className="mt-4 grid gap-3 sm:grid-cols-3">
              <div className="rounded-3xl border border-slate-200 bg-slate-50 p-4"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Entries</p><p className="mt-3 text-2xl font-semibold text-slate-950">{ledgerSummary.entries}</p></div>
              <div className="rounded-3xl border border-slate-200 bg-slate-50 p-4"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Debit</p><p className="mt-3 text-2xl font-semibold text-slate-950">₹{ledgerSummary.totalDebit.toLocaleString()}</p></div>
              <div className="rounded-3xl border border-slate-200 bg-slate-50 p-4"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Credit</p><p className="mt-3 text-2xl font-semibold text-slate-950">₹{ledgerSummary.totalCredit.toLocaleString()}</p></div>
            </div>
          </div>
          <DataTable columns={[
            { label: 'Description', key: 'description', sortable: true },
            { label: 'Debit', key: 'debit', sortable: true, render: (value) => `₹${Number(value || 0).toLocaleString()}` },
            { label: 'Credit', key: 'credit', sortable: true, render: (value) => `₹${Number(value || 0).toLocaleString()}` },
            { label: 'Status', key: 'status', sortable: true, render: (value) => <StatusBadge status={value} /> },
            { label: 'Action', key: 'action', sortable: false, render: (_value, row) => <IconActionButton icon={CheckCircle2} title="Approve entry" ariaLabel="Approve entry" variant="success" className="h-8 w-8" onClick={() => approveEntry(row)} /> },
          ]} rows={entries} initialPageSize={8} placeholder="Search ledger" />
        </div>
      )}

      {activeSection === 'vouchers' && (
        <div className="space-y-4">
          <DataTable columns={[
            { label: 'Voucher', key: 'voucherType', sortable: true },
            { label: 'Amount', key: 'amount', sortable: true, render: (value) => `₹${Number(value || 0).toLocaleString()}` },
            { label: 'Status', key: 'status', sortable: true, render: (value) => <StatusBadge status={value} /> },
            { label: 'Action', key: 'action', sortable: false, render: (_value, row) => <button type="button" onClick={() => postVoucherEntry(row)} className="rounded-full border border-slate-300 bg-slate-100 px-3 py-1 text-xs">Post</button> },
          ]} rows={vouchers} initialPageSize={8} placeholder="Search vouchers" />
        </div>
      )}

      {activeSection === 'budget' && (
        <div className="grid gap-4 xl:grid-cols-[1fr_0.8fr]">
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Budgets</h3>
            <div className="mt-4 space-y-3">
              {budgets.map((budget) => {
                const variance = calculateBudgetVariance(budget, Number(budget.amount || 0));
                return <div key={budget.id} className="rounded-3xl border border-slate-200 bg-slate-50 p-4"><div className="flex items-center justify-between"><p className="font-semibold text-slate-900">{budget.name}</p><span className="rounded-full bg-white px-3 py-1 text-sm">{variance.status}</span></div><p className="mt-2 text-sm text-slate-600">Planned ₹{Number(budget.amount || 0).toLocaleString()} · Variance ₹{variance.variance.toLocaleString()}</p></div>;
              })}
            </div>
          </div>
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Budget controls</h3>
            <div className="mt-4 space-y-3 text-sm text-slate-600">
              <div className="rounded-2xl bg-slate-50 p-3">Department budgets</div>
              <div className="rounded-2xl bg-slate-50 p-3">Annual budgets</div>
              <div className="rounded-2xl bg-slate-50 p-3">Variance analysis</div>
              <div className="rounded-2xl bg-slate-50 p-3">Forecasting</div>
            </div>
          </div>
        </div>
      )}

      {activeSection === 'bank' && (
        <div className="grid gap-4 xl:grid-cols-[1fr_0.8fr]">
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Bank accounts</h3>
            <div className="mt-4 space-y-3">
              {bankAccounts.map((account) => <div key={account.id} className="rounded-3xl border border-slate-200 bg-slate-50 p-4"><p className="font-semibold text-slate-900">{account.name}</p><p className="mt-2 text-sm text-slate-600">Balance ₹{Number(account.balance || 0).toLocaleString()} · {account.accountCode}</p></div>)}
            </div>
          </div>
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Bank operations</h3>
            <div className="mt-4 space-y-3 text-sm text-slate-600">
              <div className="rounded-2xl bg-slate-50 p-3">Reconciliation</div>
              <div className="rounded-2xl bg-slate-50 p-3">Deposits</div>
              <div className="rounded-2xl bg-slate-50 p-3">Withdrawals</div>
              <div className="rounded-2xl bg-slate-50 p-3">Transfers</div>
            </div>
          </div>
        </div>
      )}

      {activeSection === 'reports' && (
        <div className="grid gap-4 xl:grid-cols-[1fr_0.8fr]">
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Financial reports</h3>
            <div className="mt-4 space-y-3 text-sm text-slate-600">
              <div className="rounded-2xl bg-slate-50 p-3">Trial balance</div>
              <div className="rounded-2xl bg-slate-50 p-3">Balance sheet</div>
              <div className="rounded-2xl bg-slate-50 p-3">Profit & loss</div>
              <div className="rounded-2xl bg-slate-50 p-3">Cash book</div>
              <div className="rounded-2xl bg-slate-50 p-3">Bank book</div>
            </div>
          </div>
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Trial balance</h3>
            <div className="mt-4 space-y-3">
              {trialBalance.map((account) => <div key={account.id} className="rounded-3xl border border-slate-200 bg-slate-50 p-4"><div className="flex items-center justify-between"><p className="font-semibold text-slate-900">{account.name}</p><span className="rounded-full bg-white px-3 py-1 text-sm">₹{Number(account.balance || 0).toLocaleString()}</span></div></div>)}
            </div>
          </div>
        </div>
      )}

      <Modal title="Add account" isOpen={isAccountModalOpen} onClose={() => { setIsAccountModalOpen(false); setForm(defaults); }} footer={<button type="button" onClick={handleAccountSubmit} className="rounded-3xl bg-emerald-500 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 hover-gradient-border">Save account</button>}>
        <form className="space-y-4" onSubmit={handleAccountSubmit}>
          <FormField label="Account name"><input value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField>
          <FormField label="Account code"><input value={form.accountCode} onChange={(event) => setForm((current) => ({ ...current, accountCode: event.target.value }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField>
          <div className="grid gap-4 sm:grid-cols-2">
            <FormField label="Type"><select value={form.type} onChange={(event) => setForm((current) => ({ ...current, type: event.target.value }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none"><option>Assets</option><option>Liabilities</option><option>Income</option><option>Expense</option><option>Equity</option></select></FormField>
            <FormField label="Group"><input value={form.group} onChange={(event) => setForm((current) => ({ ...current, group: event.target.value }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField>
          </div>
          <FormField label="Opening balance"><input type="number" value={form.openingBalance} onChange={(event) => setForm((current) => ({ ...current, openingBalance: Number(event.target.value) }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField>
        </form>
      </Modal>

      <Modal title="Post journal entry" isOpen={isEntryModalOpen} onClose={() => { setIsEntryModalOpen(false); setForm(defaults); }} footer={<button type="button" onClick={handleEntrySubmit} className="rounded-3xl bg-emerald-500 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 hover-gradient-border">Post entry</button>}>
        <form className="space-y-4" onSubmit={handleEntrySubmit}>
          <FormField label="Description"><input value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField>
          <FormField label="Account code"><input value={form.accountCode} onChange={(event) => setForm((current) => ({ ...current, accountCode: event.target.value }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField>
          <div className="grid gap-4 sm:grid-cols-2"><FormField label="Debit"><input type="number" value={form.debit} onChange={(event) => setForm((current) => ({ ...current, debit: Number(event.target.value) }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField><FormField label="Credit"><input type="number" value={form.credit} onChange={(event) => setForm((current) => ({ ...current, credit: Number(event.target.value) }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField></div>
          <FormField label="Period"><input type="month" value={form.period} onChange={(event) => setForm((current) => ({ ...current, period: event.target.value }))} className="w-full rounded-3xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none" /></FormField>
        </form>
      </Modal>

      <Modal title="Create voucher" isOpen={isVoucherModalOpen} onClose={() => { setIsVoucherModalOpen(false); setForm(defaults); }} footer={<button type="button" onClick={handleVoucherSubmit} className="rounded-3xl bg-emerald-500 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 hover-gradient-border">Create voucher</button>}>
        <form className="space-y-4" onSubmit={handleVoucherSubmit}>
