function downloadBlob(blob, filename) {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
}

export default function OrganizationManagementPage() {
  const importInputRef = useRef(null);
  const { data: organizationsData } = useResourceList('organizations', { page: 1, pageSize: 200 });
  const organizations = organizationsData?.items || [];
  const createOrganization = useCreateResource('organizations');
  const updateOrganization = useUpdateResource('organizations');
  const deleteOrganization = useDeleteResource('organizations');
  const importOrganization = useBulkImport('organizations');
  const exportOrganization = useBulkExport('organizations');

  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [page, setPage] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedOrganization, setSelectedOrganization] = useState(null);
  const [importStatus, setImportStatus] = useState('');
  const [_isExporting, setIsExporting] = useState(false);
  const pageSize = 6;

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm({ defaultValues });

  const filteredOrganizations = useMemo(() => {
    return organizations.filter((organization) => {
      const searchTerm = search.toLowerCase();
      const matchesSearch = [organization.code, organization.name, organization.head, organization.officeLocation]
        .filter(Boolean)
        .some((field) => field.toString().toLowerCase().includes(searchTerm));
      const matchesFilter = filter === 'All' || organization.status === filter;
      return matchesSearch && matchesFilter;
    });
  }, [organizations, search, filter]);

  const pageCount = Math.max(1, Math.ceil(filteredOrganizations.length / pageSize));
  const displayedOrganizations = filteredOrganizations.slice((page - 1) * pageSize, page * pageSize);
  const activeOrganizations = organizations.filter((organization) => organization.status === 'Active').length;

  const resetForm = () => {
    reset(defaultValues);
    setSelectedOrganization(null);
    setIsEditMode(false);
  };

  const openNewOrganizationModal = () => {
    resetForm();
    setIsModalOpen(true);
  };

  const openEditOrganizationModal = (organization) => {
    setSelectedOrganization(organization);
    setIsEditMode(true);
    reset({
      code: organization.code || '',
      name: organization.name || '',
      head: organization.head || '',
      officeLocation: organization.officeLocation || '',
      status: organization.status || 'Active',
    });
    setIsModalOpen(true);
  };

  const onSubmit = (data) => {
    const payload = { ...data };
    if (isEditMode && selectedOrganization) {
      updateOrganization.mutate({ id: selectedOrganization.id, payload }, { onSuccess: () => { resetForm(); setPage(1); setIsModalOpen(false); } });
    } else {
      createOrganization.mutate(payload, { onSuccess: () => { resetForm(); setPage(1); setIsModalOpen(false); } });
    }
  };

  const handleDelete = (organization) => {
    if (!window.confirm(`Delete organization unit ${organization.name}?`)) return;
    deleteOrganization.mutate(organization.id);
  };

  const handleImport = (file) => {
    if (!file) return;
    setImportStatus('Importing organization units…');
    const formData = new FormData();
    formData.append('file', file);
    importOrganization.mutate(formData, {
      onSuccess: () => setImportStatus('Organization units imported successfully.'),
      onError: () => setImportStatus('Import failed. Please try a valid CSV file.'),
    });
  };

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];
    handleImport(file);
    event.target.value = '';
  };

  const handleExport = async () => {
    setIsExporting(true);
    try {
      const blob = await exportOrganization.mutateAsync();
      downloadBlob(blob, 'organizations-export.xlsx');
    } catch (error) {
      console.error(error);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="space-y-6">
      <SectionHeader
        title="Organization management"
        subtitle="Configure company units, HR centers, and departmental locations."
        action={
          <div className="flex flex-wrap items-center gap-3">
            <button
              type="button"
              onClick={handleExport}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700 hover-gradient-border"
            >
              <FaDownload /> Export
            </button>
            <button
              type="button"
              onClick={() => importInputRef.current?.click()}
              className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700"
            >
              <FaFileImport /> Import
            </button>
            <button
              type="button"
              onClick={openNewOrganizationModal}
              className="inline-flex items-center gap-2 rounded-3xl bg-emerald-500 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 hover-gradient-border"
            >
              <FaPlus /> Add organization
            </button>
          </div>
        }
      />
      <input ref={importInputRef} type="file" accept=".csv" className="hidden hover-gradient-border" onChange={handleFileChange} />
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(280px,0.3fr)]">
        <div className="grid gap-4">
          <div className="grid gap-3 md:grid-cols-3">
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Organization units</p>
              <p className="mt-3 text-2xl font-semibold text-white">{organizations.length}</p>
            </div>
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Active units</p>
              <p className="mt-3 text-2xl font-semibold text-white">{activeOrganizations}</p>
            </div>
            <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Locations tracked</p>
              <p className="mt-3 text-2xl font-semibold text-white">{new Set(organizations.map((org) => org.officeLocation)).size}</p>
            </div>
          </div>
          <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
              <div>
                <h2 className="text-xl font-semibold text-white">Organization directory</h2>
                <p className="text-sm text-slate-400">Manage HR centers, branches, and shared services groups.</p>
              </div>
            </div>
            <div className="mt-4 grid gap-3 md:grid-cols-2">
              <SearchFilter search={search} onSearch={setSearch} filter={filter} onFilter={setFilter} options={statusOptions} />
            </div>
            <div className="mt-4">
              <DataTable
                columns={['Code', 'Unit', 'Head', 'Location', 'Status', 'Actions']}
                rows={displayedOrganizations.map((organization) => [
                  organization.code,
                  organization.name,
                  organization.head,
                  organization.officeLocation,
                  <StatusBadge key={`${organization.id}-status`} status={organization.status} />,
                  <div key={`${organization.id}-actions`} className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => openEditOrganizationModal(organization)}
                      className="rounded-full border border-white/10 bg-slate-800/80 px-3 py-2 text-xs text-slate-200 transition hover:bg-slate-700"
                    >
                      <FaEdit className="inline-block" /> Edit
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDelete(organization)}
                      className="rounded-full border border-white/10 bg-rose-500/10 px-3 py-2 text-xs text-rose-300 transition hover:bg-rose-500/20"
                    >
                      <FaTrash className="inline-block" /> Remove
                    </button>
                  </div>,
                ])}
              />
            </div>
            <div className="mt-4">
              <TablePagination page={page} pageCount={pageCount} onPageChange={setPage} />
            </div>
          </div>
        </div>
        <div className="rounded-[18px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <div className="mb-4 flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-slate-950/70 text-emerald-300">
              <FaBuilding className="h-4 w-4" />
            </div>
            <div>
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">HR footprint</p>
              <h3 className="text-lg font-semibold text-white">Unit coverage</h3>
            </div>
          </div>
          <div className="grid gap-3">
            <div className="rounded-[22px] border border-white/10 bg-slate-950/70 p-4">
              <p className="text-sm text-slate-400">Most common location</p>
              <p className="mt-2 text-2xl font-semibold text-white">{organizations[0]?.officeLocation || 'N/A'}</p>
            </div>
            <div className="rounded-[22px] border border-white/10 bg-slate-950/70 p-4">
              <p className="text-sm text-slate-400">Total branches</p>
              <p className="mt-2 text-2xl font-semibold text-white">{new Set(organizations.map((org) => org.officeLocation)).size}</p>
            </div>
          </div>
        </div>
      </div>
      {importStatus && (
        <div className="rounded-[28px] border border-emerald-500/20 bg-emerald-500/5 p-4 text-sm text-emerald-200">{importStatus}</div>
      )}
      <Modal
        title={isEditMode ? 'Update organization unit' : 'Add organization unit'}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        footer={
          <button
            type="button"
            onClick={handleSubmit(onSubmit)}
            disabled={isSubmitting}
            className="rounded-3xl bg-emerald-500 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400 disabled:cursor-not-allowed disabled:opacity-60 hover-gradient-border"
          >
            {isEditMode ? 'Update unit' : 'Save unit'}
          </button>
        }
      >
        <form className="grid gap-5 lg:grid-cols-2">
          <FormField label="Unit code">
            <input
              type="text"
              {...register('code', { required: 'Code is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="ORG-01"
            />
            {errors.code && <p className="mt-1 text-sm text-rose-400">{errors.code.message}</p>}
          </FormField>
          <FormField label="Unit name">
            <input
              type="text"
              {...register('name', { required: 'Name is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="Human Resources"
            />
            {errors.name && <p className="mt-1 text-sm text-rose-400">{errors.name.message}</p>}
          </FormField>
          <FormField label="Unit head">
            <input
              type="text"
              {...register('head', { required: 'Head is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="Ayesha Patel"
            />
            {errors.head && <p className="mt-1 text-sm text-rose-400">{errors.head.message}</p>}
          </FormField>
          <FormField label="Office location">
            <input
              type="text"
              {...register('officeLocation', { required: 'Location is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
              placeholder="Main campus"
            />
            {errors.officeLocation && <p className="mt-1 text-sm text-rose-400">{errors.officeLocation.message}</p>}
          </FormField>
          <FormField label="Status">
            <select
              {...register('status', { required: 'Status is required' })}
              className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-emerald-400 hover-gradient-border"
            >
              <option value="Active">Active</option>
              <option value="Inactive">Inactive</option>
            </select>
            {errors.status && <p className="mt-1 text-sm text-rose-400">{errors.status.message}</p>}
          </FormField>
        </form>
      </Modal>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { CheckCircle2, Edit3, Lock, FileText, Send } from 'lucide-react';
import { useQueryClient } from '@tanstack/react-query';
import { useResourceList } from '../hooks/useResourceHooks';
import SectionHeader from '../components/ui/SectionHeader.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import Modal from '../components/ui/Modal.jsx';
import FormField from '../components/forms/FormField.jsx';
import StatusBadge from '../components/ui/StatusBadge.jsx';
import IconActionButton from '../components/ui/IconActionButton.jsx';
import { useAuth } from '../services/AuthContext.jsx';
import { createSalaryStructure, updateSalaryStructure } from '../services/salaryStructureService.js';
import { createSalaryRevision, updateSalaryRevision } from '../services/salaryRevisionService.js';
import { createPayrollRun, updatePayrollRun, submitPayrollRun, approvePayrollRun, lockPayrollRun, calculatePayrollBreakdown } from '../services/payrollService.js';
import { createPayslip, buildPayslipPreview } from '../services/payslipService.js';

const formDefaults = {
  name: '',
  employeeName: '',
  employeeId: '',
  frequency: 'Monthly',
  basicSalary: 50000,
  hraPercent: 20,
  daPercent: 5,
  specialAllowancePercent: 10,
  overtimeRate: 1000,
  providentFundPercent: 12,
  esiPercent: 0.75,
  professionalTaxAmount: 200,
  incomeTaxPercent: 5,
  approvedLeaveDays: 0,
  overtimeHours: 0,
  bonusAmount: 0,
  incentiveAmount: 0,
  status: 'Draft',
  period: '',
};

function downloadBlob(blob, filename) {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
}

export default function PayrollManagementPage() {
  const queryClient = useQueryClient();
  const { auth } = useAuth();
  const [activeSection, setActiveSection] = useState('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [isStructureModalOpen, setIsStructureModalOpen] = useState(false);
  const [isRevisionModalOpen, setIsRevisionModalOpen] = useState(false);
  const [isPayrollModalOpen, setIsPayrollModalOpen] = useState(false);
  const [isTaxModalOpen, setIsTaxModalOpen] = useState(false);
  const [editingStructure, setEditingStructure] = useState(null);
  const [editingRevision, setEditingRevision] = useState(null);
  const [editingPayroll, setEditingPayroll] = useState(null);
  const [form, setForm] = useState(formDefaults);
  const [busyMessage, setBusyMessage] = useState('');

  const { data: structuresData } = useResourceList('salaryStructures', { page: 1, pageSize: 200 });
  const { data: revisionsData } = useResourceList('salaryRevisions', { page: 1, pageSize: 200 });
  const { data: payrollData } = useResourceList('payrollRuns', { page: 1, pageSize: 200 });
  const { data: payslipsData } = useResourceList('payslips', { page: 1, pageSize: 200 });
  const { data: taxData } = useResourceList('taxComponents', { page: 1, pageSize: 200 });

  const salaryStructures = structuresData?.items || [];
  const salaryRevisions = revisionsData?.items || [];
  const payrollRuns = payrollData?.items || [];
  const payslips = payslipsData?.items || [];
  const taxComponents = taxData?.items || [];

  const filteredPayrollRuns = useMemo(() => payrollRuns.filter((payroll) => {
    const term = searchTerm.toLowerCase();
    return [payroll.employeeName, payroll.period, payroll.status].filter(Boolean).some((value) => String(value).toLowerCase().includes(term));
  }), [payrollRuns, searchTerm]);

  const resetForm = () => setForm({ ...formDefaults, employeeId: auth?.user?.id || '', employeeName: auth?.user?.name || '' });

  const handleStructureSubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Saving salary structure…');
    const payload = { ...form, basicSalary: Number(form.basicSalary || 0), hraPercent: Number(form.hraPercent || 0), daPercent: Number(form.daPercent || 0), specialAllowancePercent: Number(form.specialAllowancePercent || 0), overtimeRate: Number(form.overtimeRate || 0), providentFundPercent: Number(form.providentFundPercent || 0), esiPercent: Number(form.esiPercent || 0), professionalTaxAmount: Number(form.professionalTaxAmount || 0), incomeTaxPercent: Number(form.incomeTaxPercent || 0) };
    if (editingStructure) {
      await updateSalaryStructure(editingStructure.id, payload);
    } else {
      await createSalaryStructure(payload);
    }
    queryClient.invalidateQueries(['salaryStructures']);
    setBusyMessage('');
    setIsStructureModalOpen(false);
    setEditingStructure(null);
    resetForm();
  };

  const handleRevisionSubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Saving salary revision…');
    const payload = { ...form, effectiveDate: form.period, newBasicSalary: Number(form.basicSalary || 0) };
    if (editingRevision) {
      await updateSalaryRevision(editingRevision.id, payload);
    } else {
      await createSalaryRevision(payload);
    }
    queryClient.invalidateQueries(['salaryRevisions']);
    setBusyMessage('');
    setIsRevisionModalOpen(false);
    setEditingRevision(null);
    resetForm();
  };

  const handlePayrollSubmit = async (event) => {
    event.preventDefault();
    setBusyMessage('Generating payroll…');
    const breakdown = calculatePayrollBreakdown({
      salaryStructure: form,
      attendanceDays: Number(form.attendanceDays || 30),
      approvedLeaveDays: Number(form.approvedLeaveDays || 0),
      overtimeHours: Number(form.overtimeHours || 0),
      bonusAmount: Number(form.bonusAmount || 0),
      incentiveAmount: Number(form.incentiveAmount || 0),
      frequency: form.frequency,
    });
    const payload = {
      ...form,
      employeeName: form.employeeName || auth?.user?.name || 'Employee',
      employeeId: form.employeeId || auth?.user?.id || 'EMP-001',
      grossSalary: breakdown.grossEarnings,
      totalDeductions: breakdown.totalDeductions,
      netSalary: breakdown.netSalary,
      breakdown,
      status: editingPayroll ? form.status : 'Draft',
    };
    if (editingPayroll) {
      await updatePayrollRun(editingPayroll.id, payload);
    } else {
      await createPayrollRun(payload);
    }
    queryClient.invalidateQueries(['payrollRuns']);
    setBusyMessage('');
    setIsPayrollModalOpen(false);
    setEditingPayroll(null);
    resetForm();
  };

  const handlePayslipCreate = async (payroll) => {
    setBusyMessage('Creating payslip…');
    await createPayslip(buildPayslipPreview(payroll));
    queryClient.invalidateQueries(['payslips']);
    setBusyMessage('');
  };

  const processPayrollAction = async (payroll, action) => {
    if (action === 'submit') {
      await submitPayrollRun(payroll.id);
    } else if (action === 'approve') {
      await approvePayrollRun(payroll.id, { remarks: 'Approved from payroll module' });
    } else if (action === 'lock') {
      await lockPayrollRun(payroll.id);
    } else if (action === 'edit') {
      setEditingPayroll(payroll);
      setForm({ ...formDefaults, ...payroll, employeeName: payroll.employeeName, employeeId: payroll.employeeId, period: payroll.period || '' });
      setIsPayrollModalOpen(true);
      return;
    }
    queryClient.invalidateQueries(['payrollRuns']);
  };

  const exportPayroll = (format = 'csv') => {
    const headers = ['Employee', 'Period', 'Gross', 'Deductions', 'Net', 'Status'];
    const rows = filteredPayrollRuns.map((payroll) => ({ Employee: payroll.employeeName, Period: payroll.period, Gross: payroll.grossSalary || 0, Deductions: payroll.totalDeductions || 0, Net: payroll.netSalary || 0, Status: payroll.status }));
    const content = [headers, ...rows.map((row) => headers.map((header) => `"${String(row[header] ?? '').replace(/"/g, '""')}"`).join(','))].join('\n');
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    downloadBlob(blob, `payroll-${format}.csv`);
  };

  const payrollSummary = useMemo(() => ({
    due: filteredPayrollRuns.filter((item) => item.status === 'Draft').length,
    processed: filteredPayrollRuns.filter((item) => item.status === 'Processed').length,
    approvals: filteredPayrollRuns.filter((item) => ['Review', 'HR Approval', 'Finance Approval'].includes(item.status)).length,
    salaryExpense: filteredPayrollRuns.reduce((sum, item) => sum + Number(item.netSalary || 0), 0),
    employeesProcessed: filteredPayrollRuns.filter((item) => item.status !== 'Draft').length,
  }), [filteredPayrollRuns]);

  return (
    <div className="space-y-6">
      <SectionHeader
        title="Payroll management"
        subtitle="Salary structures, revisions, payroll runs, payslips, tax configuration, and reporting."
        action={
          <div className="flex flex-wrap items-center gap-3">
            <button type="button" onClick={() => setIsStructureModalOpen(true)} className="rounded-3xl bg-slate-800/80 px-4 py-3 text-sm text-slate-200 transition hover:bg-slate-700">Salary structures</button>
            <button type="button" onClick={() => setIsRevisionModalOpen(true)} className="rounded-3xl bg-emerald-500 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-emerald-400">Salary revision</button>
            <button type="button" onClick={() => setIsPayrollModalOpen(true)} className="rounded-3xl border border-slate-300 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-100">Generate payroll</button>
          </div>
        }
      />

      {busyMessage ? <div className="rounded-3xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{busyMessage}</div> : null}

      <div className="rounded-[24px] border border-slate-200 bg-slate-50 p-4 shadow-sm">
        <div className="flex flex-wrap gap-2">
          {['overview', 'runs', 'structures', 'tax', 'payslips'].map((tab) => (
            <button key={tab} type="button" onClick={() => setActiveSection(tab)} className={`rounded-2xl border px-4 py-2 text-sm font-medium transition ${activeSection === tab ? 'border-slate-900 bg-slate-900 text-white' : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-100'}`}>
              {tab === 'overview' ? 'Overview' : tab === 'runs' ? 'Payroll Runs' : tab === 'structures' ? 'Structures' : tab === 'tax' ? 'Tax' : 'Payslips'}
            </button>
          ))}
        </div>
      </div>

      {activeSection === 'overview' && (
        <div className="grid gap-4 xl:grid-cols-[1.1fr_0.9fr]">
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Payroll due</p><p className="mt-3 text-2xl font-semibold text-slate-950">{payrollSummary.due}</p></div>
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Processed</p><p className="mt-3 text-2xl font-semibold text-slate-950">{payrollSummary.processed}</p></div>
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Pending approvals</p><p className="mt-3 text-2xl font-semibold text-slate-950">{payrollSummary.approvals}</p></div>
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Salary expense</p><p className="mt-3 text-2xl font-semibold text-slate-950">₹{payrollSummary.salaryExpense.toLocaleString()}</p></div>
            <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs uppercase tracking-[0.24em] text-slate-500">Employees processed</p><p className="mt-3 text-2xl font-semibold text-slate-950">{payrollSummary.employeesProcessed}</p></div>
          </div>
          <div className="rounded-[20px] border border-slate-200 bg-white p-4 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-950">Salary structures</h3>
            <div className="mt-4 space-y-2">
              {salaryStructures.slice(0, 4).map((structure) => <div key={structure.id} className="rounded-2xl border border-slate-200 bg-slate-50 px-3 py-3 text-sm text-slate-700">{structure.name} · ₹{Number(structure.basicSalary || 0).toLocaleString()}</div>)}
