            >
              <Filter className="h-4 w-4" />
              Filter
            </Button>
            <Button
              type="button"
              variant="secondary"
              className="rounded-2xl px-4 py-2 hover-gradient-border"
              onClick={handlePrint}
            >
              <Printer className="h-4 w-4" />
              Print
            </Button>
