const parseCsvRows = (csvText) => {
  const rows = csvText.split(/\r?\n/).filter((row) => row.trim() !== '');
  const header = rows.shift()?.split(',').map((col) => col.trim().toLowerCase()) || [];
  return rows.map((row) => {
    const values = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < row.length; i += 1) {
      const char = row[i];
      if (char === '"') {
        if (inQuotes && row[i + 1] === '"') {
          current += '"';
          i += 1;
        } else {
          inQuotes = !inQuotes;
        }
        continue;
      }
      if (char === ',' && !inQuotes) {
        values.push(current);
        current = '';
        continue;
      }
      current += char;
    }
    values.push(current);
    const record = {};
    header.forEach((key, index) => {
      record[key] = values[index]?.trim() || '';
    });
    return record;
  });
};

