﻿import { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowRight, ChevronDown, HelpCircle, Upload } from 'lucide-react';
import Breadcrumb from '../components/ui/Breadcrumb.jsx';
import { useERP } from '../services/ERPContext.jsx';

const subjectOptions = [
  'Mathematics-I',
  'Physics',
  'Programming in C',
  'Python Programming',
  'Java Programming',
  'Data Structures',
  'Algorithms',
  'Operating System',
  'Database Management System',
  'Computer Networks',
  'Artificial Intelligence',
  'Machine Learning',
  'Software Engineering',
  'Web Development',
  'Discrete Mathematics',
  'Object Oriented Programming',
  'Cloud Computing',
  'Cyber Security',
  'Computer Graphics',
  'Compiler Design',
];

const employeeOptions = [
  'Dr. Amit Sharma',
  'Prof. Rahul Verma',
  'Dr. Neha Gupta',
  'Prof. Ankit Singh',
  'Dr. Priya Joshi',
  'Prof. Mohit Kumar',
  'Dr. Shalini Agarwal',
  'Prof. Vivek Chauhan',
  'Dr. Pooja Sharma',
  'Prof. Deepak Kumar',
];

function Dropdown({ label, selected, options, onSelect, renderOption }) {
  const [open, setOpen] = useState(false);
  const wrapperRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
        setOpen(false);
      }
    };

    window.addEventListener('mousedown', handleClickOutside);
    return () => window.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div ref={wrapperRef} className="relative w-full">
      <label className="mb-2 block text-[11px] font-semibold uppercase tracking-[0.22em] text-slate-500">
        {label}
      </label>
      <button
        type="button"
        onClick={() => setOpen((prev) => !prev)}
        className="inline-flex h-10 w-full items-center justify-between rounded-2xl border border-slate-300 bg-white px-4 text-left text-sm text-slate-900 shadow-sm transition hover:border-slate-400 focus:outline-none"
      >
        <span className="min-w-0 truncate">
          {selected ? (renderOption ? renderOption(selected, true) : selected.label) : 'Select...'}
        </span>
        <ChevronDown className="h-4 w-4 text-slate-500" />
      </button>

      {open && (
        <div className="absolute left-0 right-0 z-20 mt-2 max-h-72 overflow-auto rounded-2xl border border-slate-200 bg-white shadow-lg">
          <ul className="divide-y divide-slate-200">
            {options.map((option) => (
              <li key={option.value ?? option.id ?? option}>
                <button
                  type="button"
                  onClick={() => {
                    onSelect(option);
                    setOpen(false);
                  }}
                  className="w-full px-4 py-3 text-left hover:bg-slate-50"
                >
                  {renderOption ? renderOption(option, false) : option}
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

export default function SubjectAssignmentPage() {
  const { colleges = [] } = useERP();
  const collegeOptions = useMemo(() => {
    const source = Array.isArray(colleges) ? colleges : [];

    return source.map((college, index) => {
      const title = typeof college === 'string'
        ? college
        : college.name || college.collegeName || college.label || `College ${college.id ?? index + 1}`;
      return {
        id: String(college.id ?? `college-${index + 1}`),
        title,
        subtitle: typeof college === 'string' ? 'College' : college.subtitle || 'College',
        extra: typeof college === 'string' ? '' : college.extra || '',
      };
    });
  }, [colleges]);

  const [selectedCollege, setSelectedCollege] = useState(collegeOptions[0]);
  const [selectedSubject, setSelectedSubject] = useState(subjectOptions[0]);
  const [selectedEmployee, setSelectedEmployee] = useState(employeeOptions[0]);
  const [showSubjectsColumn, setShowSubjectsColumn] = useState(false);
  const [activeCollege, setActiveCollege] = useState(collegeOptions[0]);
  const [selectedUploadFileName, setSelectedUploadFileName] = useState('');

  useEffect(() => {
    if (!collegeOptions.length) return;

    const hasSelectedCollege = selectedCollege && collegeOptions.some((option) => option.id === selectedCollege.id);
    const hasActiveCollege = activeCollege && collegeOptions.some((option) => option.id === activeCollege.id);

    if (!hasSelectedCollege) {
      setSelectedCollege(collegeOptions[0]);
    }
    if (!hasActiveCollege) {
      setActiveCollege(collegeOptions[0]);
    }
  }, [collegeOptions, selectedCollege, activeCollege]);

  const uploadInputRef = useRef(null);

  useEffect(() => {
    document.title = 'Assign Subject - Academics Setup';
  }, []);

  return (
    <main className="min-h-screen w-full bg-slate-50 text-slate-950">
      <div className="mx-auto w-full max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
        <Breadcrumb
          items={[
            { label: 'Dashboard', to: '/' },
            { label: 'Academics Setup', to: '/settings/institute/academics' },
            { label: 'Assign Subject' },
          ]}
        />

        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div className="min-w-0">
            <p className="text-sm uppercase tracking-[0.24em] text-slate-500">Academics Setup</p>
            <h1 className="mt-2 text-3xl font-semibold tracking-tight text-slate-950">Assign Subject</h1>
            <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">Manage subject assignments across college programs with clean dropdown selection and quick actions.</p>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <button type="button" onClick={() => uploadInputRef.current?.click()} className="inline-flex items-center gap-2 rounded-2xl bg-white px-4 py-2.5 text-sm font-semibold text-slate-900 shadow-sm ring-1 ring-slate-200 transition hover:bg-slate-50">
              <Upload className="h-4 w-4" />
              Upload Excel
            </button>
            <button type="button" className="inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800">
              <HelpCircle className="h-4 w-4" />
              Need Help
            </button>
          </div>
          <input
            ref={uploadInputRef}
            type="file"
            accept=".csv,.xlsx,.xls"
            className="hidden"
            onChange={(event) => {
              const file = event.target.files?.[0];
              if (file) setSelectedUploadFileName(file.name);
              event.target.value = '';
            }}
          />
          {selectedUploadFileName ? (
            <p className="mt-2 text-sm text-slate-600">Selected file: {selectedUploadFileName}</p>
          ) : null}
        </div>

        <div className="grid gap-6 xl:grid-cols-[1.6fr_1fr]">
          <section className="rounded-[28px] border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex flex-col gap-6">
              <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-end">
                <div className="space-y-2">
                  <p className="text-xs uppercase tracking-[0.22em] text-slate-500">Select college</p>
                  <Dropdown
                    label="College"
                    selected={selectedCollege}
                    options={collegeOptions}
                    onSelect={setSelectedCollege}
                    renderOption={(option, isSelected) => (
                      <div className="space-y-0.5">
                        <p className="truncate text-sm font-semibold text-slate-950">{option.title}</p>
                        <p className="text-xs text-slate-500">{option.subtitle} · {option.extra}</p>
                      </div>
                    )}
                  />
                </div>

                <div className="flex items-center justify-between gap-3 rounded-2xl border border-slate-200 bg-slate-50 p-4">
                  <div>
                    <p className="text-xs uppercase tracking-[0.22em] text-slate-500">Action</p>
                    <p className="mt-2 text-sm font-semibold text-slate-900">Switch college view</p>
                  </div>
                  <button
                    type="button"
                    onClick={() => setActiveCollege(selectedCollege)}
                    className="inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800"
                  >
                    Go
                    <ArrowRight className="h-4 w-4" />
                  </button>
                </div>
              </div>

              <div className="grid gap-4 lg:grid-cols-2">
                <Dropdown
                  label="Select subject"
                  selected={selectedSubject}
                  options={subjectOptions}
                  onSelect={setSelectedSubject}
                  renderOption={(option) => <span className="text-sm text-slate-900">{option}</span>}
                />
                <Dropdown
                  label="Select employee"
                  selected={selectedEmployee}
                  options={employeeOptions}
                  onSelect={setSelectedEmployee}
                  renderOption={(option) => <span className="text-sm text-slate-900">{option}</span>}
                />
              </div>

              <div className="flex flex-col gap-4 rounded-2xl border border-slate-200 bg-slate-50 p-4 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <p className="text-xs uppercase tracking-[0.22em] text-slate-500">Display setting</p>
                  <p className="mt-2 text-sm text-slate-700">Show Subjects Column</p>
                </div>
                <button
                  type="button"
                  onClick={() => setShowSubjectsColumn((prev) => !prev)}
                  className={`relative inline-flex h-9 w-16 items-center rounded-full transition-colors ${showSubjectsColumn ? 'bg-slate-950' : 'bg-slate-300'}`}
                >
                  <span className={`absolute left-0.5 h-8 w-8 rounded-full bg-white shadow transition-transform ${showSubjectsColumn ? 'translate-x-7' : 'translate-x-0'}`} />
                </button>
              </div>
            </div>
          </section>

          <aside className="rounded-[28px] border border-slate-200 bg-white p-6 shadow-sm">
            <div className="space-y-4">
              <div>
                <p className="text-xs uppercase tracking-[0.22em] text-slate-500">Active selection</p>
                <p className="mt-2 text-sm font-semibold text-slate-950">{activeCollege.title}</p>
                <p className="mt-1 text-sm text-slate-600">{activeCollege.subtitle} · {activeCollege.extra}</p>
              </div>

              <div className="grid gap-3 rounded-3xl border border-slate-200 bg-slate-50 p-4">
                <div className="space-y-1">
                  <p className="text-[11px] uppercase tracking-[0.22em] text-slate-500">Selected subject</p>
                  <p className="text-sm font-semibold text-slate-950">{selectedSubject}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[11px] uppercase tracking-[0.22em] text-slate-500">Assigned employee</p>
                  <p className="text-sm font-semibold text-slate-950">{selectedEmployee}</p>
                </div>
              </div>

              <div className="rounded-3xl border border-slate-200 bg-white p-4 text-sm text-slate-600 shadow-sm">
                <p className="font-semibold text-slate-900">Subjects column</p>
                <p className="mt-2">{showSubjectsColumn ? 'Visible in the subject assignment table.' : 'Hidden from the subject assignment table.'}</p>
              </div>
            </div>
          </aside>
        </div>
      </div>
    </main>
  );
}

import { useMemo, useState } from 'react';
import { Download, Printer, Search } from 'lucide-react';
import { useResourceList } from '../hooks/useResourceHooks.js';
import Breadcrumb from '../components/ui/Breadcrumb.jsx';

const PAGE_SIZE_OPTIONS = [10, 20, 50];

export default function SubjectCombinationReportPage() {
  const [searchText, setSearchText] = useState('');
  const [selectedCourse, setSelectedCourse] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const { data: subjectsData, isLoading: isLoadingSubjects, error: subjectsError } = useResourceList('subjects', {
    page,
    page_size: pageSize,
  });

  const { data: coursesData } = useResourceList('courses', {
    page: 1,
    page_size: 200,
  });

  const subjects = subjectsData?.items || [];
  const courses = coursesData?.items || [];
  const total = subjectsData?.total || 0;
  const pages = subjectsData?.pages || 1;

  const subjectCourseMap = useMemo(() => {
    return courses.reduce((map, course) => {
      map[course.id] = course;
      return map;
    }, {});
  }, [courses]);

  const filteredSubjects = useMemo(() => {
    return subjects.filter((subject) => {
      const normalizedSearch = searchText.trim().toLowerCase();
      const courseName = subjectCourseMap[subject.course_id]?.name || '';
      const courseCode = subjectCourseMap[subject.course_id]?.code || '';
      const matchesSearch =
        !normalizedSearch ||
        [subject.name, subject.code, courseName, courseCode]
          .filter(Boolean)
          .some((value) => value.toString().toLowerCase().includes(normalizedSearch));

      const matchesCourse = !selectedCourse || String(subject.course_id) === selectedCourse;
      return matchesSearch && matchesCourse;
    });
  }, [subjects, searchText, selectedCourse, subjectCourseMap]);

  const courseOptions = courses.map((course) => ({
    id: course.id,
    label: `${course.name}${course.code ? ` (${course.code})` : ''}`,
  }));

  const pageFrom = subjects.length > 0 ? (pageSize * (page - 1)) + 1 : 0;
  const pageTo = subjects.length > 0 ? pageFrom + subjects.length - 1 : 0;

  const downloadCsv = (rows) => {
    const header = ['S.No', 'Subject Code', 'Subject Name', 'Course Name', 'Course Code'];
    const csvRows = [header.join(',')];

    rows.forEach((row, index) => {
      const course = subjectCourseMap[row.course_id] || {};
      const values = [
        index + 1,
        row.code || '',
        row.name || '',
        course.name || '',
        course.code || '',
      ];
      csvRows.push(values.map((value) => `"${String(value).replace(/"/g, '""')}"`).join(','));
    });

    const blob = new Blob([csvRows.join('\n')], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'subject-combination-report.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen bg-slate-50 py-6 text-slate-900">
      <div className="mb-8 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <Breadcrumb
            items={[
              { label: 'Dashboard', to: '/' },
              { label: 'Admission Reports', to: '/admissions/reports/summary' },
              { label: 'Subject Combination Report' },
            ]}
          />
          <h1 className="mt-3 text-3xl font-semibold text-primary-navy">Subject Combination Report</h1>
          <p className="mt-2 max-w-2xl text-sm text-slate-600">
            Explore subject combinations using live backend data. Filter by course, search by subject, and export or print the current report.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <button
            type="button"
            onClick={() => downloadCsv(filteredSubjects)}
            className="inline-flex items-center gap-2 rounded-2xl bg-primary-navy px-4 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-primary-navy-dark"
          >
            <Download size={16} /> Export
          </button>
          <button
            type="button"
            onClick={() => window.print()}
            className="inline-flex items-center gap-2 rounded-2xl bg-white border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-900 shadow-sm transition hover:bg-slate-50"
          >
            <Printer size={16} /> Print
          </button>
        </div>
      </div>

      <div className="mb-6 rounded-[28px] bg-white p-6 shadow-sm ring-1 ring-slate-200">
        <div className="grid gap-4 lg:grid-cols-[1.5fr_1fr]">
          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <label className="block text-xs uppercase tracking-[0.24em] text-slate-500">Search</label>
              <div className="mt-2 flex items-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2">
                <Search size={16} className="text-slate-500" />
                <input
                  type="text"
                  value={searchText}
                  onChange={(event) => setSearchText(event.target.value)}
                  placeholder="Search by subject code, name or course"
                  className="w-full bg-transparent text-sm text-slate-900 outline-none"
                />
              </div>
            </div>
            <div>
              <label className="block text-xs uppercase tracking-[0.24em] text-slate-500">Course</label>
              <select
                value={selectedCourse}
                onChange={(event) => {
                  setSelectedCourse(event.target.value);
                  setPage(1);
                }}
                className="mt-2 w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none focus:border-primary-navy focus:ring-2 focus:ring-primary-navy/10"
              >
                <option value="">All Courses</option>
                {courseOptions.map((course) => (
                  <option key={course.id} value={course.id}>{course.label}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <label className="block text-xs uppercase tracking-[0.24em] text-slate-500">Page size</label>
              <select
                value={pageSize}
                onChange={(event) => {
                  setPageSize(Number(event.target.value));
                  setPage(1);
                }}
                className="mt-2 w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none focus:border-primary-navy focus:ring-2 focus:ring-primary-navy/10"
              >
                {PAGE_SIZE_OPTIONS.map((size) => (
                  <option key={size} value={size}>{size} per page</option>
                ))}
              </select>
            </div>
            <div className="flex items-end justify-end">
              <div className="text-right text-sm text-slate-600">
                <div>Total subjects: <span className="font-semibold text-slate-900">{total}</span></div>
                <div>Current rows: <span className="font-semibold text-slate-900">{filteredSubjects.length}</span></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="overflow-hidden rounded-[28px] bg-white shadow-sm ring-1 ring-slate-200">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[960px] text-sm text-slate-700">
            <thead className="bg-primary-navy text-white">
              <tr>
                <th className="whitespace-nowrap px-4 py-4 text-left font-semibold uppercase tracking-[0.12em]">S.No</th>
                <th className="whitespace-nowrap px-4 py-4 text-left font-semibold uppercase tracking-[0.12em]">Subject Code</th>
                <th className="whitespace-nowrap px-4 py-4 text-left font-semibold uppercase tracking-[0.12em]">Subject Name</th>
                <th className="whitespace-nowrap px-4 py-4 text-left font-semibold uppercase tracking-[0.12em]">Course Name</th>
                <th className="whitespace-nowrap px-4 py-4 text-left font-semibold uppercase tracking-[0.12em]">Course Code</th>
              </tr>
            </thead>
            <tbody>
              {isLoadingSubjects ? (
                <tr>
                  <td colSpan="5" className="px-4 py-16 text-center text-slate-500">Loading subject combinations...</td>
                </tr>
              ) : subjectsError ? (
                <tr>
                  <td colSpan="5" className="px-4 py-16 text-center text-red-600">Failed to load subject data. Please refresh the page.</td>
                </tr>
              ) : filteredSubjects.length === 0 ? (
                <tr>
                  <td colSpan="5" className="px-4 py-16 text-center text-slate-500">No subject combinations found.</td>
                </tr>
              ) : (
                filteredSubjects.map((subject, index) => (
                  <tr key={subject.id} className={index % 2 === 0 ? 'bg-white' : 'bg-slate-50'}>
                    <td className="whitespace-nowrap px-4 py-4 text-slate-900">{pageFrom + index}</td>
                    <td className="whitespace-nowrap px-4 py-4 text-slate-900">{subject.code || '—'}</td>
                    <td className="px-4 py-4 text-slate-900">{subject.name || '—'}</td>
                    <td className="px-4 py-4 text-slate-700">{subjectCourseMap[subject.course_id]?.name || '—'}</td>
                    <td className="px-4 py-4 text-slate-700">{subjectCourseMap[subject.course_id]?.code || '—'}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <div className="flex flex-col gap-3 border-t border-slate-200 bg-slate-50 px-6 py-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="text-sm text-slate-600">
            Showing {pageFrom} to {pageTo} of {total} subjects.
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              disabled={page <= 1}
              onClick={() => setPage((current) => Math.max(1, current - 1))}
              className="rounded-2xl border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50"
            >
              Previous
            </button>
            <span className="text-sm text-slate-700">Page {page} of {pages}</span>
            <button
              type="button"
              disabled={page >= pages}
              onClick={() => setPage((current) => Math.min(pages, current + 1))}
              className="rounded-2xl border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50"
            >
              Next
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { useERP } from '../services/ERPContext.jsx';
import { useNavigate } from 'react-router-dom';
import Button from '../components/ui/Button.jsx';
import DataTable from '../components/ui/DataTable.jsx';
import ConfirmDialog from '../components/ui/ConfirmDialog.jsx';
import SearchableSelect from '../components/ui/SearchableSelect.jsx';
