          </div>
          <div className="flex items-center justify-end">
            <button type="button" onClick={submit} className="h-[38px] w-[90px] rounded-[6px] bg-sky-600 text-white">Add</button>
          </div>
        </div>
      </div>
    </div>
  );
}

