const weekdayHeaders = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

const scheduleOptions = ['BCA B', 'B.Tech. Hons. CSE', 'MCA A'];
