        <div className="rounded-xl border border-[#E2E8F0] bg-white p-6 shadow-sm">
          <h3 className="mb-5 text-xl font-semibold text-slate-900">Actions</h3>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {actionItems.map((item) => {
              const isFavorite = favoriteActions[item.id];
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => toggleFavorite(item.id)}
                  className="group flex flex-col items-start rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-left transition hover:bg-emerald-100 hover-gradient-border"
                >
                  <div
                    className="mb-3 inline-flex h-10 w-10 items-center justify-center rounded-2xl bg-emerald-100 text-emerald-700"
                    style={{ color: isFavorite ? item.favoriteColor : '#14532d', backgroundColor: isFavorite ? `${item.favoriteColor}20` : '#d1fae5' }}
                  >
                    <Star size={18} fill={isFavorite ? 'currentColor' : 'none'} />
                  </div>
                  <span className={`text-sm font-semibold ${isFavorite ? 'text-emerald-700' : 'text-slate-700'}`}>{item.label}</span>
                </button>
              );
            })}
          </div>
        </div>

        <div className="rounded-xl border border-[#E2E8F0] bg-white p-6 shadow-sm">
          <div className="mb-5 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <h3 className="text-xl font-semibold text-slate-900">Reports</h3>
            <input
              type="text"
              value={reportQuery}
              onChange={(event) => setReportQuery(event.target.value)}
              placeholder="Search reports..."
              className="w-full rounded-xl border border-[#E2E8F0] bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none sm:w-auto"
            />
          </div>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filteredReports.map((report) => (
              <div key={report.id} className="flex h-full flex-col rounded-2xl border border-emerald-200 bg-emerald-600 p-5 text-white transition hover:bg-emerald-700 hover-gradient-border">
                <div className="mb-4 inline-flex h-11 w-11 items-center justify-center rounded-2xl bg-white/20 text-white">
                  <FileText size={18} />
                </div>
                <div className="text-sm font-semibold break-words whitespace-normal">{report.label}</div>
              </div>
            ))}
            {filteredReports.length === 0 && (
              <div className="col-span-full rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center text-sm text-slate-500">
                No reports match your search.
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Edit3, Eye, Plus, Trash2 } from 'lucide-react';
import { toast } from 'react-toastify';
import Breadcrumb from '../../components/ui/Breadcrumb.jsx';
import Button from '../../components/ui/Button.jsx';
import DataTable from '../../components/ui/DataTable.jsx';
import Modal from '../../components/ui/Modal.jsx';
import SearchableSelect from '../../components/ui/SearchableSelect.jsx';
import { collegeOptions as sharedCollegeNames } from '../../services/subjectMappingTypes.js';
import { useResourceList, useCreateResource, useUpdateResource, useDeleteResource } from '../../hooks/useResourceHooks';

const INITIAL_FORM_STATE = {
  departmentId: '',
  courseId: '',
  semesterId: '',
  sectionId: '',
  assessmentName: '',
  assessmentModel: '',
  entryType: '',
  gradeSetupId: '',
  status: 'Active',
  description: '',
  subjectRows: [],
};

const DEFAULT_SUBJECT_ROW = () => ({ id: `new-${Date.now()}-${Math.random()}`, subjectId: '', subjectName: '' });

const assessmentNameOptions = [
  { value: 'Unit Test 1', label: 'Unit Test 1' },
  { value: 'Unit Test 2', label: 'Unit Test 2' },
  { value: 'Mid Term', label: 'Mid Term' },
  { value: 'Final Exam', label: 'Final Exam' },
  { value: 'Assignment', label: 'Assignment' },
  { value: 'Project', label: 'Project' },
];

const assessmentModelOptions = [
  { value: 'SCHOLASTIC', label: 'Scholastic' },
  { value: 'CO_SCHOLASTIC', label: 'Co-scholastic' },
  { value: 'DISCIPLINE', label: 'Discipline' },
  { value: 'SKILL', label: 'Skill' },
  { value: 'MAJOR', label: 'Major' },
  { value: 'MINOR', label: 'Minor' },
  { value: 'MDC', label: 'MDC' },
  { value: 'SEC', label: 'SEC' },
  { value: 'VAC', label: 'VAC' },
  { value: 'AEC', label: 'AEC' },
  { value: 'VOC', label: 'VOC' },
  { value: 'ASSIGNMENT', label: 'Assignment' },
  { value: 'PROJECT', label: 'Project' },
];

const statusOptions = [
  { value: 'Active', label: 'Active' },
  { value: 'Inactive', label: 'Inactive' },
];

const entryTypeOptions = [
  { value: 'MARKS', label: 'Marks' },
  { value: 'GRADE', label: 'Grade' },
];

export default function AssessmentConfigPage() {
  const [showModal, setShowModal] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [showFilterModal, setShowFilterModal] = useState(false);
  const [filters, setFilters] = useState({ department: 'ALL', course: '', semester: '', section: '', assessment: '', lockMarksEntry: '' });
  const [formValues, setFormValues] = useState({ ...INITIAL_FORM_STATE, subjectRows: [DEFAULT_SUBJECT_ROW()] });

  const { data: configsData, isLoading: configsLoading } = useResourceList('assessmentConfigs', { page: 1, pageSize: 200 });
  const { data: departmentsData } = useResourceList('departments', { page: 1, pageSize: 200 });
  const { data: coursesData } = useResourceList('courses', { page: 1, pageSize: 200 });
  const { data: semestersData } = useResourceList('semesters', { page: 1, pageSize: 200 });
  const { data: classesData } = useResourceList('classes', { page: 1, pageSize: 200 });
  const { data: sectionsData } = useResourceList('sections', { page: 1, pageSize: 200 });
  const { data: subjectsData } = useResourceList('subjects', { page: 1, pageSize: 200 });
  const { data: gradeSetupsData } = useResourceList('assessmentGradeSetups', { page: 1, pageSize: 200 });

  const createMutation = useCreateResource('assessmentConfigs');
  const updateMutation = useUpdateResource('assessmentConfigs');
  const deleteMutation = useDeleteResource('assessmentConfigs');

  useEffect(() => {
    document.title = 'Assessment Config - Academics';
  }, []);

  const departments = departmentsData?.items || [];
  const courses = coursesData?.items || [];
  const semesters = semestersData?.items || [];
  const classes = classesData?.items || [];
  const sections = sectionsData?.items || [];
  const subjects = subjectsData?.items || [];
  const gradeSetups = gradeSetupsData?.items || [];

  const selectedDepartmentId = formValues.departmentId ? Number(formValues.departmentId) : null;
  const selectedCourseId = formValues.courseId ? Number(formValues.courseId) : null;

  const departmentOptions = useMemo(
    () => sharedCollegeNames.map((college) => ({ value: college, label: college })),
    [],
  );

  const courseOptions = useMemo(
    () => courses
      .filter((course) => !selectedDepartmentId || Number(course.department_id) === selectedDepartmentId)
      .map((course) => ({ value: String(course.id), label: `${course.name}${course.code ? ` (${course.code})` : ''}` })),
    [courses, selectedDepartmentId],
  );

  const semesterOptions = useMemo(
    () => semesters.map((semester) => ({ value: String(semester.id), label: semester.name })),
    [semesters],
  );

  const sectionOptions = useMemo(() => {
    const filteredClassIds = classes
      .filter((academicClass) => !selectedCourseId || Number(academicClass.course_id) === selectedCourseId)
      .map((academicClass) => Number(academicClass.id));
    return sections
      .filter((section) => !selectedCourseId || filteredClassIds.includes(Number(section.academic_class_id)))
      .map((section) => ({ value: String(section.id), label: section.name }));
  }, [classes, sections, selectedCourseId]);

  const subjectOptions = useMemo(
    () => subjects
      .filter((subject) => !selectedCourseId || Number(subject.course_id) === selectedCourseId)
      .map((subject) => ({ value: String(subject.id), label: subject.name })),
    [subjects, selectedCourseId],
  );

  const gradeSetupOptions = useMemo(() => {
    const apiOptions = (gradeSetups || []).map((setup) => ({ value: String(setup.id), label: setup.name }));
    const defaultGradeSetups = [
      'External exams',
      'B.TECH',
      'B.TECH. HONOURS',
      'BCA',
      'MCA',
      'BBA/B.COM/MBA EXAMS',
      'M.TECH',
      'B.SC/M.SC./AGRICULTURE',
      'B.PHARM/M.PHARM',
      'B.SC NURSING',
      'D.PHARM',
    ].map((v) => ({ value: v, label: v }));

    // Merge API options with defaults, preferring API entries when labels clash
    const merged = [...apiOptions];
    defaultGradeSetups.forEach((def) => {
      if (!merged.some((m) => String(m.label).toLowerCase() === String(def.label).toLowerCase())) merged.push(def);
    });
    return merged;
  }, [gradeSetups]);

  const tableColumns = useMemo(
    () => ['Assessment Name', 'Assessment Model', 'Scope', 'Subjects', 'Grade Setup', 'Status', 'Actions'],
    [],
  );

  const openCreate = () => {
    setEditItem(null);
    setFormValues({ ...INITIAL_FORM_STATE, subjectRows: [DEFAULT_SUBJECT_ROW()] });
    setShowModal(true);
  };

  const handleFilterChange = (field, value) => {
    setFilters((prev) => ({ ...prev, [field]: value }));
  };

  const resetFilters = () => setFilters({ department: 'ALL', course: '', semester: '', section: '', assessment: '', lockMarksEntry: '' });

  const applyFilters = () => {
    setShowFilterModal(false);
  };

  const openEdit = (item) => {
    const [departmentName, courseName, semesterName, sectionName] = (item.key || '').split(' / ');
    const department = departments.find((dept) => dept.name === departmentName);
    const course = courses.find((courseItem) => courseItem.name === courseName);
    const semester = semesters.find((semesterItem) => semesterItem.name === semesterName);
    const section = sections.find((sectionItem) => sectionItem.name === sectionName);

    const parsedSubjects = (item.value || '').split(',').map((subjectText) => {
      const trimmed = subjectText.trim();
      const found = subjects.find((subject) => subject.name === trimmed);
      return {
        id: `edit-${trimmed}-${Math.random()}`,
        subjectId: found ? String(found.id) : '',
        subjectName: trimmed,
      };
    }).filter((row) => row.subjectName);

    setEditItem(item);
    setFormValues({
      departmentId: department ? String(department.id) : '',
      courseId: course ? String(course.id) : '',
      semesterId: semester ? String(semester.id) : '',
      sectionId: section ? String(section.id) : '',
      assessmentName: item.name || '',
      assessmentModel: item.assessment_type || '',
      entryType: item.entry_type || '',
      gradeSetupId: gradeSetups.find((setup) => String(setup.id) === String(item.code)) ? String(item.code) : '',
      status: item.status || 'Active',
      description: item.description || '',
      subjectRows: parsedSubjects.length ? parsedSubjects : [DEFAULT_SUBJECT_ROW()],
    });
    setShowModal(true);
  };

  const resetForm = () => {
    setEditItem(null);
    setFormValues({ ...INITIAL_FORM_STATE, subjectRows: [DEFAULT_SUBJECT_ROW()] });
  };

  const handleFormChange = (field, value) => {
    setFormValues((current) => ({ ...current, [field]: value }));
  };

  const handleSubjectChange = (rowId, field, value) => {
    setFormValues((current) => ({
      ...current,
      subjectRows: current.subjectRows.map((row) => {
        if (row.id !== rowId) return row;
        if (field === 'subjectId') {
          const subject = subjects.find((item) => String(item.id) === String(value));
          return {
            ...row,
            subjectId: value,
            subjectName: subject?.name || row.subjectName,
          };
        }
        return { ...row, [field]: value };
      }),
    }));
  };

  const addSubjectRow = () => {
    setFormValues((current) => ({
      ...current,
      subjectRows: [...current.subjectRows, DEFAULT_SUBJECT_ROW()],
    }));
  };

  const removeSubjectRow = (rowId) => {
    setFormValues((current) => ({
      ...current,
      subjectRows: current.subjectRows.filter((row) => row.id !== rowId),
    }));
  };

  const buildPayload = () => {
    const department = departments.find((item) => String(item.id) === String(formValues.departmentId));
    const course = courses.find((item) => String(item.id) === String(formValues.courseId));
    const semester = semesters.find((item) => String(item.id) === String(formValues.semesterId));
    const section = sections.find((item) => String(item.id) === String(formValues.sectionId));
    const gradeSetup = gradeSetups.find((item) => String(item.id) === String(formValues.gradeSetupId));

    return {
      name: formValues.assessmentName || 'Untitled assessment',
      code: gradeSetup?.name || formValues.assessmentModel || '',
      assessment_type: formValues.assessmentModel || 'General',
      entry_type: formValues.entryType || '',
      key: [department?.name, course?.name, semester?.name, section?.name].filter(Boolean).join(' / '),
      value: formValues.subjectRows
        .map((row) => row.subjectName || '')
        .filter(Boolean)
        .join(', '),
      status: formValues.status,
      description: formValues.description || gradeSetup?.description || '',
    };
  };

  const handleModalSubmit = async (event) => {
    event.preventDefault();
    try {
      const payload = buildPayload();
      if (editItem) {
        await updateMutation.mutateAsync({ id: editItem.id, payload });
        toast.success('Assessment config updated');
      } else {
        await createMutation.mutateAsync(payload);
        toast.success('Assessment config created');
      }
      setShowModal(false);
      resetForm();
    } catch (error) {
      toast.error(error?.message || 'Could not save assessment config');
    }
  };

  const handleDelete = async (item) => {
    if (!window.confirm('Delete this assessment config?')) return;
    try {
      await deleteMutation.mutateAsync(item.id);
      toast.success('Assessment config deleted');
    } catch (error) {
      toast.error(error?.message || 'Could not delete assessment config');
    }
  };

  const tableRows = useMemo(() => {
    const records = configsData?.items || [];
    // Apply simple client-side filters based on selected filter form
    const filtered = records.filter((item) => {
      if (filters.department && filters.department !== 'ALL') {
        const deptName = (item.key || '').split(' / ')[0];
        if (!deptName || String(deptName) !== String(filters.department)) return false;
      }
      if (filters.course) {
        const courseName = (item.key || '').split(' / ')[1];
        if (!courseName || String(courseName) !== String(filters.course)) return false;
      }
      if (filters.semester) {
        const semName = (item.key || '').split(' / ')[2];
        if (!semName || String(semName) !== String(filters.semester)) return false;
      }
      if (filters.section) {
        const secName = (item.key || '').split(' / ')[3];
        if (!secName || String(secName) !== String(filters.section)) return false;
      }
      if (filters.assessment) {
        if (!item.name || String(item.name) !== String(filters.assessment)) return false;
      }
      // lockMarksEntry filtering requires backend field; check if present
      if (filters.lockMarksEntry) {
        if (typeof item.lock_marks_entry !== 'undefined' && String(item.lock_marks_entry) !== String(filters.lockMarksEntry)) return false;
      }
      return true;
    });

    return filtered.map((item) => {
      const scopeValue = item.key || '—';
      const subjectsValue = item.value || '—';
      const gradeSetupRecord = gradeSetups.find((setup) => String(setup.id) === String(item.code)) || gradeSetups.find((setup) => setup.name === item.code);
      const gradeSetupLabel = gradeSetupRecord?.name || item.code || '—';

      return [
        item.name || '—',
        item.assessment_type || '—',
        scopeValue,
        subjectsValue,
        gradeSetupLabel,
        item.status || '—',
        <div key={`actions-${item.id}`} className="flex flex-wrap items-center justify-center gap-1.5">
          <button
            type="button"
            title="View"
            aria-label="View"
            onClick={() => openEdit(item)}
            className="inline-flex h-8 w-8 items-center justify-center rounded-full border border-sky-200 bg-sky-50 text-sky-700 transition hover:bg-sky-100 hover-gradient-border"
          >
            <Eye className="h-4 w-4" />
          </button>
          <button
            type="button"
            title="Edit"
            aria-label="Edit"
            onClick={() => openEdit(item)}
            className="inline-flex h-8 w-8 items-center justify-center rounded-full border border-emerald-200 bg-emerald-50 text-emerald-700 transition hover:bg-emerald-100 hover-gradient-border"
          >
            <Edit3 className="h-4 w-4" />
          </button>
          <button
            type="button"
            title="Delete"
            aria-label="Delete"
            onClick={() => handleDelete(item)}
            className="inline-flex h-8 w-8 items-center justify-center rounded-full border border-rose-200 bg-rose-50 text-rose-700 transition hover:bg-rose-100 hover-gradient-border"
          >
            <Trash2 className="h-4 w-4" />
          </button>
        </div>,
      ];
    });
    // Dependencies intentionally include gradeSetups so the table updates when the lookup list is available.
  }, [configsData?.items, gradeSetups, departments, courses, semesters, sections, subjects]);

  const tableDataRows = tableRows;

  return (
    <div className="min-h-screen w-full min-w-0 px-[12px] pb-8 pt-4 lg:px-6">
      <div className="mb-6">
        <Breadcrumb
          items={[
            { label: 'Dashboard', to: '/' },
            { label: 'Institute Setup', to: '/settings/institute' },
            { label: 'Academics', to: '/settings/institute/academics' },
            { label: 'Assessment Config' },
          ]}
        />
        <div className="mt-3">
          <h1 className="text-3xl font-semibold tracking-tight text-slate-900">Assessment Config</h1>
          <p className="mt-2 max-w-2xl text-sm text-slate-500">Manage academic assessment settings for institution configuration and subject assignment workflows.</p>
        </div>
      </div>

      <div className="rounded-[24px] border border-slate-200/70 bg-white/95 p-4 shadow-sm">
        <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-lg font-semibold text-slate-950">Assessment configurations</h2>
            <p className="text-sm text-slate-500">Use the table below to review existing configs and add new assessment settings.</p>
          </div>
          <div className="flex items-center gap-3">
            <Button type="button" onClick={() => setShowFilterModal(true)} className="inline-flex items-center gap-2 px-4 py-3 text-sm" variant="secondary">
              Filter
            </Button>
            <Button type="button" onClick={openCreate} className="inline-flex items-center gap-2 px-4 py-3 text-sm" variant="primary">
              <Plus className="h-4 w-4" /> Add assessment config
            </Button>
          </div>
        </div>

        <DataTable
          columns={tableColumns}
          rows={tableDataRows}
          loading={configsLoading}
          placeholder="Search assessment config records..."
        />
      </div>

      <Modal
        title={editItem ? 'Edit assessment config' : 'Add assessment config'}
        isOpen={showModal}
        onClose={() => { setShowModal(false); resetForm(); }}
        footer={
          <>
            <button
              type="button"
              onClick={() => { setShowModal(false); resetForm(); }}
              className="rounded-2xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700"
            >
              Cancel
            </button>
            <button type="submit" form="assessment-config-form" className="rounded-2xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white hover-gradient-border">
              Save assessment config
            </button>
          </>
        }
      >
        <form id="assessment-config-form" onSubmit={handleModalSubmit} className="space-y-6">
          <div className="grid gap-4 md:grid-cols-3">
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">College</label>
              <SearchableSelect
                options={departmentOptions}
                value={formValues.departmentId}
                onChange={(value) => handleFormChange('departmentId', value)}
                placeholder="Select college"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Course</label>
              <SearchableSelect
                options={courseOptions}
                value={formValues.courseId}
                onChange={(value) => handleFormChange('courseId', value)}
                placeholder="Select course"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Semester</label>
              <SearchableSelect
                options={semesterOptions}
                value={formValues.semesterId}
                onChange={(value) => handleFormChange('semesterId', value)}
                placeholder="Select semester"
              />
            </div>
          </div>

          <div className="grid gap-4 md:grid-cols-3">
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Section</label>
              <SearchableSelect
                options={sectionOptions}
                value={formValues.sectionId}
                onChange={(value) => handleFormChange('sectionId', value)}
                placeholder="Select section"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Assessment name</label>
              <SearchableSelect
                options={assessmentNameOptions}
                value={formValues.assessmentName}
                onChange={(value) => handleFormChange('assessmentName', value)}
                placeholder="Select assessment name"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Assessment model</label>
              <SearchableSelect
                options={assessmentModelOptions}
                value={formValues.assessmentModel}
                onChange={(value) => handleFormChange('assessmentModel', value)}
                placeholder="Select assessment model"
              />
            </div>
          </div>

          <div className="grid gap-4 md:grid-cols-4">
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Grade setup</label>
              <SearchableSelect
                options={gradeSetupOptions}
                value={formValues.gradeSetupId}
                onChange={(value) => handleFormChange('gradeSetupId', value)}
                placeholder="Select grade setup"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Entry Type</label>
              <SearchableSelect
                options={entryTypeOptions}
                value={formValues.entryType}
                onChange={(value) => handleFormChange('entryType', value)}
                placeholder="Select entry type"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Status</label>
              <SearchableSelect
                options={statusOptions}
                value={formValues.status}
                onChange={(value) => handleFormChange('status', value)}
                placeholder="Select status"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Description</label>
              <textarea
                rows={3}
                value={formValues.description}
                onChange={(event) => handleFormChange('description', event.target.value)}
                placeholder="Optional description"
                className="w-full rounded-2xl border border-slate-200/80 bg-slate-50 px-3 py-3 text-sm text-slate-900 outline-none hover-gradient-border"
              />
            </div>
          </div>

          <div className="rounded-2xl border border-slate-200/80 bg-slate-50 p-4">
            <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <h3 className="text-sm font-semibold text-slate-900">Subject rows</h3>
                <p className="text-xs text-slate-500">Select subjects for this assessment configuration. Subjects are filtered by the selected course.</p>
              </div>
              <button type="button" onClick={addSubjectRow} className="inline-flex items-center gap-2 rounded-2xl bg-slate-900 px-4 py-2 text-sm font-semibold text-white transition hover:bg-slate-800 hover-gradient-border">
                <Plus className="h-4 w-4" /> Add subject
              </button>
            </div>

            <div className="space-y-3">
              {formValues.subjectRows.map((row) => (
                <div key={row.id} className="grid gap-3 md:grid-cols-[1.6fr_1fr_auto] items-end rounded-2xl border border-slate-200 bg-white p-3">
                  <div>
                    <label className="mb-2 block text-sm font-medium text-slate-700">Subject</label>
                    <SearchableSelect
                      options={subjectOptions}
                      value={row.subjectId}
                      onChange={(value) => handleSubjectChange(row.id, 'subjectId', value)}
                      placeholder="Choose subject"
                    />
                  </div>
                  <div>
                    <label className="mb-2 block text-sm font-medium text-slate-700">Subject label</label>
                    <input
                      type="text"
                      value={row.subjectName}
                      onChange={(event) => handleSubjectChange(row.id, 'subjectName', event.target.value)}
                      placeholder="Custom label"
                      className="w-full rounded-2xl border border-slate-200/80 bg-slate-50 px-3 py-3 text-sm text-slate-900 outline-none hover-gradient-border"
                    />
                  </div>
                  <button
                    type="button"
                    onClick={() => removeSubjectRow(row.id)}
                    className="inline-flex h-10 w-10 items-center justify-center rounded-full border border-rose-200 bg-rose-50 text-rose-700 transition hover:bg-rose-100 hover-gradient-border"
                    title="Remove subject"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        </form>
      </Modal>

      <Modal
        title="Filter"
        isOpen={showFilterModal}
        onClose={() => { setShowFilterModal(false); }}
        footer={
          <>
            <button
              type="button"
              onClick={() => { resetFilters(); setShowFilterModal(false); }}
              className="rounded-2xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700"
            >
              Cancel
            </button>
            <button type="button" onClick={applyFilters} className="rounded-2xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white hover-gradient-border">
              Go
            </button>
          </>
        }
      >
        <form id="assessment-filter-form" onSubmit={(e) => { e.preventDefault(); applyFilters(); }} className="space-y-6">
          <div className="grid gap-4 md:grid-cols-3">
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Select College</label>
              <SearchableSelect
                options={[{ value: 'ALL', label: 'ALL, ROORKEE COLLEGE ...' }, ...departmentOptions]}
                value={filters.department}
                onChange={(value) => handleFilterChange('department', value)}
                placeholder="Select college"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Select Course</label>
              <SearchableSelect
                options={courseOptions}
                value={filters.course}
                onChange={(value) => handleFilterChange('course', value)}
                placeholder="Select course"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Select Semester</label>
              <SearchableSelect
                options={semesterOptions}
                value={filters.semester}
                onChange={(value) => handleFilterChange('semester', value)}
                placeholder="Select semester"
              />
            </div>
          </div>

          <div className="grid gap-4 md:grid-cols-3">
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Select Section</label>
              <SearchableSelect
                options={sectionOptions}
                value={filters.section}
                onChange={(value) => handleFilterChange('section', value)}
                placeholder="Select section"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Select Assessment</label>
              <SearchableSelect
                options={assessmentNameOptions}
                value={filters.assessment}
                onChange={(value) => handleFilterChange('assessment', value)}
                placeholder="Select assessment"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm font-medium text-slate-700">Lock Marks Entry</label>
              <SearchableSelect
                options={[{ value: '', label: 'Any' }, { value: 'LOCKED', label: 'Locked' }, { value: 'OPEN', label: 'Open' }]}
                value={filters.lockMarksEntry}
                onChange={(value) => handleFilterChange('lockMarksEntry', value)}
                placeholder="Lock Marks Entry"
              />
            </div>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Copy, Pencil, Plus, Trash2 } from 'lucide-react';
import { toast } from 'react-toastify';
import Breadcrumb from '../../components/ui/Breadcrumb.jsx';
import { useResourceList, useCreateResource, useUpdateResource, useDeleteResource } from '../../hooks/useResourceHooks';

const GRADE_BANDS = ['A+', 'A', 'B+', 'B', 'C+', 'C', 'D', 'E', 'F'];
const STATUS_OPTIONS = ['All', 'Active', 'Inactive'];
const PAGE_SIZE_OPTIONS = [10, 20, 50];

export default function AssessmentGradeSetupPage() {
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [createdDateFilter, setCreatedDateFilter] = useState('');
  const [isExpanded, setIsExpanded] = useState(true);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [submitting, setSubmitting] = useState(false);
  const [form, setForm] = useState({ id: null, name: '', code: '', grade_band: '', min_score: '', max_score: '', grade_point: '', status: 'Active', description: '' });
  const [editingId, setEditingId] = useState(null);

  const { data: gradeSetupData = {} } = useResourceList('assessmentGradeSetups', { page: 1, pageSize: 200 });
  const createGradeSetup = useCreateResource('assessmentGradeSetups');
  const updateGradeSetup = useUpdateResource('assessmentGradeSetups');
  const deleteGradeSetup = useDeleteResource('assessmentGradeSetups');

  useEffect(() => {
    document.title = 'Assessment Grade Setup - Academics';
  }, []);

  const rows = gradeSetupData?.items || [];

  const filteredRows = useMemo(() => {
    const term = query.trim().toLowerCase();

    return rows.filter((row) => {
      const matchesSearch = [row.name, row.code, row.grade_band, row.description, row.status]
        .some((value) => value?.toString().toLowerCase().includes(term));

      const matchesStatus = statusFilter === 'All' || row.status === statusFilter;
      const matchesDate = !createdDateFilter || new Date(row.created_at).toISOString().slice(0, 10) === createdDateFilter;

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [query, rows, statusFilter, createdDateFilter]);

  const handleQueryChange = (event) => {
    setQuery(event.target.value);
    setPage(1);
  };

  const handleStatusChange = (event) => {
    setStatusFilter(event.target.value);
    setPage(1);
  };

  const handleDateChange = (event) => {
    setCreatedDateFilter(event.target.value);
    setPage(1);
  };

  const pageCount = Math.max(1, Math.ceil(filteredRows.length / pageSize));
  const displayedRows = filteredRows.slice((page - 1) * pageSize, page * pageSize);

  const resetForm = () => {
    setForm({ id: null, name: '', code: '', grade_band: '', min_score: '', max_score: '', grade_point: '', status: 'Active', description: '' });
    setEditingId(null);
  };

  const saveRow = async (event) => {
    event.preventDefault();
    if (!form.name || !form.grade_band) {
      toast.error('Assessment Grade Name and Grade Band are required.');
      return;
    }

    const payload = {
      name: form.name,
      code: form.code || form.grade_band,
      grade_band: form.grade_band,
      min_score: form.min_score ? Number(form.min_score) : null,
      max_score: form.max_score ? Number(form.max_score) : null,
      grade_point: form.grade_point ? Number(form.grade_point) : null,
      status: form.status,
      description: form.description,
    };

    setSubmitting(true);
    try {
      if (editingId) {
        await updateGradeSetup.mutateAsync({ id: editingId, payload });
        toast.success('Assessment grade setup updated successfully.');
      } else {
        await createGradeSetup.mutateAsync(payload);
        toast.success('Assessment grade setup created successfully.');
      }
      resetForm();
      setIsExpanded(false);
    } catch (error) {
      console.error('Failed to save grade setup', error);
      toast.error(error?.message || 'Failed to save grade setup. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const editRow = (row) => {
    setEditingId(row.id);
    setForm({
      id: row.id,
      name: row.name,
      code: row.code,
      grade_band: row.grade_band,
      min_score: row.min_score ?? '',
      max_score: row.max_score ?? '',
      grade_point: row.grade_point ?? '',
      status: row.status,
      description: row.description,
    });
    setIsExpanded(true);
  };

  const deleteRow = async (id) => {
    if (!window.confirm('Delete this grade setup entry?')) return;
    setSubmitting(true);
    try {
      await deleteGradeSetup.mutateAsync(id);
      toast.success('Assessment grade setup deleted successfully.');
      if (editingId === id) resetForm();
    } catch (error) {
      console.error('Failed to delete grade setup', error);
      toast.error(error?.message || 'Failed to delete grade setup. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen w-full min-w-0 px-[12px] pb-8 pt-4 lg:px-6">
      <div className="flex items-start justify-between gap-4 mb-6">
        <div>
          <Breadcrumb items={[{ label: 'Dashboard', to: '/' }, { label: 'Institute Setup', to: '/settings/institute' }, { label: 'Academics', to: '/settings/institute/academics' }, { label: 'Assessment Grade Setup' }]} />
          <div className="mt-3">
            <h1 className="text-3xl font-semibold tracking-tight text-slate-900">Assessment Grade Setup</h1>
            <p className="mt-2 max-w-2xl text-sm text-slate-500">Create grade scale rules and achievement bands for academic assessments.</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button type="button" onClick={() => setIsExpanded((prev) => !prev)} className="inline-flex items-center gap-2 rounded-[10px] border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50 transition">
            <Plus className="h-4 w-4" /> {isExpanded ? 'Hide Form' : 'Add Grade Setup'}
          </button>
          <button type="button" onClick={() => navigator.clipboard.writeText(JSON.stringify(rows, null, 2))} className="inline-flex items-center gap-2 rounded-[10px] bg-slate-900 px-4 py-2 text-sm font-semibold text-white hover:bg-slate-800 transition">
            <Copy className="h-4 w-4" /> Copy JSON
          </button>
        </div>
      </div>

      <div className="rounded-[16px] border border-slate-200 bg-white p-5 shadow-sm">
        <div className={`overflow-hidden transition-all duration-300 ${isExpanded ? 'max-h-[620px] opacity-100' : 'max-h-0 opacity-0'}`}>
          <form onSubmit={saveRow} className="grid gap-4 lg:grid-cols-[1.2fr_1fr]">
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-slate-700">Grade Name</label>
                <input value={form.name} onChange={(e) => setForm((prev) => ({ ...prev, name: e.target.value }))} placeholder="Enter grade name" className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
              </div>
              <div>
                <label className="text-sm font-medium text-slate-700">Grade Code</label>
                <input value={form.code} onChange={(e) => setForm((prev) => ({ ...prev, code: e.target.value }))} placeholder="Enter grade code" className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
              </div>
              <div>
                <label className="text-sm font-medium text-slate-700">Grade Band</label>
                <select value={form.grade_band} onChange={(e) => setForm((prev) => ({ ...prev, grade_band: e.target.value }))} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500">
                  <option value="">Select band</option>
                  {GRADE_BANDS.map((band) => <option key={band} value={band}>{band}</option>)}
                </select>
              </div>
              <div className="grid gap-4 sm:grid-cols-2">
                <div>
                  <label className="text-sm font-medium text-slate-700">Min Score</label>
                  <input value={form.min_score} onChange={(e) => setForm((prev) => ({ ...prev, min_score: e.target.value }))} type="number" min="0" max="100" placeholder="Min" className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
                </div>
                <div>
                  <label className="text-sm font-medium text-slate-700">Max Score</label>
                  <input value={form.max_score} onChange={(e) => setForm((prev) => ({ ...prev, max_score: e.target.value }))} type="number" min="0" max="100" placeholder="Max" className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-slate-700">Grade Point</label>
                <input value={form.grade_point} onChange={(e) => setForm((prev) => ({ ...prev, grade_point: e.target.value }))} type="number" step="0.1" min="0" max="5" placeholder="e.g. 4.0" className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
              </div>
              <div>
                <label className="text-sm font-medium text-slate-700">Status</label>
                <select value={form.status} onChange={(e) => setForm((prev) => ({ ...prev, status: e.target.value }))} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500">
                  {STATUS_OPTIONS.map((status) => <option key={status} value={status}>{status}</option>)}
                </select>
              </div>
              <div>
                <label className="text-sm font-medium text-slate-700">Description</label>
                <textarea value={form.description} onChange={(e) => setForm((prev) => ({ ...prev, description: e.target.value }))} rows="4" placeholder="Optional details about this grade band" className="mt-2 w-full rounded-xl border border-slate-200 px-3 py-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
              </div>
              <div className="flex flex-wrap gap-3 pt-2">
                <button type="submit" className="inline-flex items-center justify-center rounded-xl bg-emerald-600 px-5 py-3 text-sm font-semibold text-white hover:bg-emerald-700 transition">{editingId ? 'Update Setup' : 'Save Setup'}</button>
                <button type="button" onClick={resetForm} className="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-50 transition">Reset</button>
              </div>
            </div>
          </form>
        </div>

        <div className="mt-8 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex-1">
            <p className="text-xs font-medium uppercase tracking-[0.24em] text-slate-500">Grade setup entries</p>
            <h2 className="mt-2 text-xl font-semibold text-slate-900">{filteredRows.length} entries</h2>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <input value={query} onChange={handleQueryChange} placeholder="Search grade setup..." className="h-11 min-w-[240px] rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
            <select value={statusFilter} onChange={handleStatusChange} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500">
              {STATUS_OPTIONS.map((status) => <option key={status} value={status}>{status}</option>)}
            </select>
            <input type="date" value={createdDateFilter} onChange={handleDateChange} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500" />
          </div>
        </div>

        <div className="mt-6 overflow-x-auto">
          <table className="min-w-full border-separate border-spacing-0 text-sm">
            <thead>
              <tr className="bg-slate-900 text-left text-xs uppercase tracking-[0.18em] text-white">
                <th className="px-4 py-3">S.No</th>
                <th className="px-4 py-3">Name</th>
                <th className="px-4 py-3">Grade Band</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">Created On</th>
                <th className="px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody className="bg-white">
              {displayedRows.map((row, index) => (
                <tr key={row.id} className="border-t border-slate-200">
                  <td className="px-4 py-4 text-slate-600">{(page - 1) * pageSize + index + 1}</td>
                  <td className="px-4 py-4 font-semibold text-slate-900">{row.name}</td>
                  <td className="px-4 py-4 text-slate-600">{row.grade_band || '–'}</td>
                  <td className="px-4 py-4">
                    <span className={`inline-flex rounded-full px-3 py-1 text-xs font-semibold ${row.status === 'Active' ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-700'}`}>
                      {row.status}
                    </span>
                  </td>
                  <td className="px-4 py-4 text-slate-600">{row.created_at ? new Date(row.created_at).toLocaleDateString() : '–'}</td>
                  <td className="px-4 py-4">
                    <div className="inline-flex items-center gap-2">
                      <button type="button" onClick={() => editRow(row)} disabled={submitting} className="inline-flex h-10 w-10 items-center justify-center rounded-xl border border-slate-200 bg-white text-slate-700 hover:bg-slate-50 transition disabled:cursor-not-allowed disabled:opacity-60">
                        <Pencil className="h-4 w-4" />
                      </button>
                      <button type="button" onClick={() => deleteRow(row.id)} disabled={submitting} className="inline-flex h-10 w-10 items-center justify-center rounded-xl border border-slate-200 bg-white text-rose-600 hover:bg-rose-50 transition disabled:cursor-not-allowed disabled:opacity-60">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {displayedRows.length === 0 && (
                <tr>
                  <td colSpan="6" className="px-4 py-14 text-center text-sm text-slate-500">
                    No assessment grade setups match the current filters. Add a grade setup to get started.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        <div className="mt-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="text-sm text-slate-600">
            Showing {displayedRows.length} of {filteredRows.length} filtered records
          </div>
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
            <label className="flex items-center gap-2 text-sm text-slate-600">
              Items per page
              <select value={pageSize} onChange={(e) => { setPageSize(Number(e.target.value)); setPage(1); }} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500">
                {PAGE_SIZE_OPTIONS.map((size) => <option key={size} value={size}>{size}</option>)}
              </select>
            </label>
            <div className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700">
              <button type="button" onClick={() => setPage((current) => Math.max(1, current - 1))} disabled={page === 1} className="rounded-lg px-3 py-2 hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50">Previous</button>
              <span>Page {page} of {pageCount}</span>
              <button type="button" onClick={() => setPage((current) => Math.min(pageCount, current + 1))} disabled={page === pageCount} className="rounded-lg px-3 py-2 hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50">Next</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { Plus, Trash2, Edit3, ToggleLeft, ToggleRight } from 'lucide-react';
import Breadcrumb from '../../components/ui/Breadcrumb.jsx';
import Button from '../../components/ui/Button.jsx';
import DataTable from '../../components/ui/DataTable.jsx';
import Modal from '../../components/ui/Modal.jsx';
import SearchableSelect from '../../components/ui/SearchableSelect.jsx';
import { collegeOptions as sharedCollegeNames } from '../../services/subjectMappingTypes.js';
import { useResourceList, useCreateResource, useUpdateResource, useDeleteResource } from '../../hooks/useResourceHooks';

const INITIAL_FORM = {
  name: '',
  collegeId: '',
  courseId: '',
  batchId: '',
  gradeSetupId: '',
  weightage: '',
  editResult: false,
  items: [],
};

const DEFAULT_ITEM = () => ({ id: `new-${Date.now()}-${Math.random()}`, assessment_name: '', assessment_model: '', display_name: '', sequence_no: '', result_declared: false, include_in_total: false, display_value: false, show_graph: false, passing_required: false });

export default function AssessmentGroupPage() {
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [selectedRowId, setSelectedRowId] = useState(null);
  const [form, setForm] = useState({ ...INITIAL_FORM, items: [DEFAULT_ITEM()] });
  const [filters, setFilters] = useState({ college: 'ALL' });

  const { data: groupsData, isLoading } = useResourceList('assessmentGroup', { page: 1, pageSize: 200 });
  const { data: coursesData } = useResourceList('courses', { page: 1, pageSize: 200 });
  const { data: classesData } = useResourceList('classes', { page: 1, pageSize: 200 });
  const { data: gradeSetupsData } = useResourceList('assessmentGradeSetups', { page: 1, pageSize: 200 });

  const createMutation = useCreateResource('assessmentGroup');
  const updateMutation = useUpdateResource('assessmentGroup');
  const deleteMutation = useDeleteResource('assessmentGroup');
  const qc = useQueryClient();

  useEffect(() => { document.title = 'AssessmentGroup - Academics'; }, []);

  const departmentOptions = useMemo(() => sharedCollegeNames.map((c) => ({ value: c, label: c })), []);
  const courseOptions = useMemo(() => (coursesData?.items || []).map((c) => ({ value: String(c.id), label: c.name })), [coursesData]);
  const batchOptions = useMemo(() => (classesData?.items || []).map((c) => ({ value: String(c.id), label: c.name })), [classesData]);
  const gradeSetupOptions = useMemo(() => (gradeSetupsData?.items || []).map((g) => ({ value: String(g.id), label: g.name })), [gradeSetupsData]);

  const openCreate = () => { setEditing(null); setForm({ ...INITIAL_FORM, items: [DEFAULT_ITEM()] }); setShowModal(true); };

  const openEdit = (row) => {
    setEditing(row);
    setForm({
      name: row.name || '',
      collegeId: row.college_id || '',
      courseId: row.course_id || '',
      batchId: row.batch_id || '',
      gradeSetupId: row.grade_setup_id || '',
      weightage: row.weightage || '',
      editResult: row.edit_result || false,
      items: (row.items || []).map((it) => ({ ...it })),
    });
    setShowModal(true);
  };

  const handleFormChange = (k, v) => setForm((s) => ({ ...s, [k]: v }));

  const addItem = () => setForm((s) => ({ ...s, items: [...s.items, DEFAULT_ITEM()] }));
  const removeItem = (id) => setForm((s) => ({ ...s, items: s.items.filter((it) => it.id !== id) }));

  const buildPayload = () => ({
    name: form.name,
    college_id: form.collegeId,
    course_id: form.courseId,
    batch_id: form.batchId,
    grade_setup_id: form.gradeSetupId,
    weightage: Number(form.weightage || 0),
    edit_result: !!form.editResult,
    items: form.items.map((it) => ({
      assessment_name: it.assessment_name,
      assessment_model: it.assessment_model,
      display_name: it.display_name,
      sequence_no: it.sequence_no ? Number(it.sequence_no) : null,
      result_declared: !!it.result_declared,
      include_in_total: !!it.include_in_total,
      display_value: !!it.display_value,
      show_graph: !!it.show_graph,
      passing_required: !!it.passing_required,
    })),
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    const payload = buildPayload();
    try {
      if (editing) await updateMutation.mutateAsync({ id: editing.id, payload });
      else await createMutation.mutateAsync(payload);
      setShowModal(false);
    } catch (err) { console.error(err); }
  };

  const handleDelete = async (row) => { if (!window.confirm('Delete record?')) return; await deleteMutation.mutateAsync(row.id); };

  const rows = (groupsData?.items || []).map((g, idx) => ([
    <input type="checkbox" key={`cb-${g.id}`} checked={selectedRowId === g.id} onChange={(e) => setSelectedRowId(e.target.checked ? g.id : null)} className="h-4 w-4 rounded border-slate-300 text-sky-600" />,
    idx + 1,
    g.name || '—',
    g.college_id || '—',
    g.course_id || '—',
    g.batch_id || '—',
    g.grade_setup_id || '—',
    g.weightage ?? '—',
    <div key={`actions-${g.id}`} className="flex gap-2">
      <button onClick={() => openEdit(g)} className="btn"> <Edit3 /> </button>
      <button onClick={() => handleDelete(g)} className="btn"> <Trash2 /> </button>
    </div>,
  ]));

  const columns = ['','S No.', 'Name', 'College', 'Course', 'Batch', 'Grade Setup', 'Weightage', 'Actions'];

  return (
    <div className="min-h-screen w-full px-[12px] pb-8 pt-4 lg:px-6">
      <div className="mb-6">
        <Breadcrumb items={[{ label: 'Dashboard', to: '/' }, { label: 'Academics Setup', to: '/settings/institute/academics' }, { label: 'AssessmentGroup' }]} />
        <div className="mt-3 flex items-center justify-between">
          <h1 className="text-3xl font-semibold tracking-tight text-slate-900">AssessmentGroup</h1>
          <div className="flex items-center gap-3">
            <Button variant="dark" onClick={async () => {
              let idToCopy = selectedRowId;
              if (!idToCopy) {
                const pick = window.prompt('Enter the ID of the AssessmentGroup to copy (or Cancel)');
                if (!pick) return;
                idToCopy = Number(pick);
              }
              if (!idToCopy || Number.isNaN(Number(idToCopy))) {
                alert('Invalid ID');
                return;
              }
              if (!window.confirm('Are you sure you want to copy this AssessmentGroup?')) return;
              try {
                // Use configured API client so production uses VITE_API_BASE_URL
                const { default: api } = await import('../../api/axios.js');
                const resp = await api.post(`/assessment-group/${idToCopy}/copy`);
                if (!resp || resp.status >= 400) throw new Error('Copy failed');
                // invalidate list so it refreshes via React Query
                qc.invalidateQueries({ queryKey: ['assessmentGroup'], exact: false });
              } catch (err) { console.error(err); alert('Copy failed'); }
            }}>Copy</Button>
            <Button variant="primary" onClick={openCreate}><Plus className="h-4 w-4" /> Add New AssessmentGroup</Button>
          </div>
        </div>
      </div>

      <div className="rounded-[24px] border border-slate-200/70 bg-white/95 p-4 shadow-sm mb-4">
        <div className="grid grid-cols-2 items-center">
          <div>
            <SearchableSelect options={[{ value: 'ALL', label: 'Select College' }, ...departmentOptions]} value={filters.college} onChange={(v) => setFilters((s) => ({ ...s, college: v }))} />
          </div>
          <div className="flex justify-end">
            <Button variant="dark">Go →</Button>
          </div>
        </div>
      </div>

      <div className="rounded-[24px] border border-slate-200/70 bg-white/95 p-4 shadow-sm">
        <DataTable columns={columns} rows={rows} loading={isLoading} placeholder="No Records found !" />
      </div>

      <Modal title={editing ? 'Edit AssessmentGroup' : 'Add New AssessmentGroup'} isOpen={showModal} onClose={() => setShowModal(false)} footer={<><Button onClick={() => setShowModal(false)}>Cancel</Button><Button onClick={handleSubmit} variant="primary">{editing ? 'Update' : 'Add'}</Button></>}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-4 gap-4">
            <div>
              <label className="block text-sm">Enter Name</label>
              <input required value={form.name} onChange={(e) => handleFormChange('name', e.target.value)} className="w-full rounded-2xl border px-3 py-2" />
            </div>
            <div>
              <label className="block text-sm">College</label>
              <SearchableSelect options={departmentOptions} value={form.collegeId} onChange={(v) => handleFormChange('collegeId', v)} required />
            </div>
            <div>
              <label className="block text-sm">Select Course</label>
              <SearchableSelect options={courseOptions} value={form.courseId} onChange={(v) => handleFormChange('courseId', v)} required />
            </div>
            <div>
              <label className="block text-sm">Batch</label>
              <SearchableSelect options={batchOptions} value={form.batchId} onChange={(v) => handleFormChange('batchId', v)} required />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm">Select Grade Setup</label>
              <SearchableSelect options={gradeSetupOptions} value={form.gradeSetupId} onChange={(v) => handleFormChange('gradeSetupId', v)} required />
            </div>
            <div>
              <label className="block text-sm">Enter Weightage</label>
              <input type="number" min={0} max={100} value={form.weightage} onChange={(e) => handleFormChange('weightage', e.target.value)} className="w-full rounded-2xl border px-3 py-2" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            <label className="flex items-center gap-2"><input type="checkbox" checked={form.editResult} onChange={(e) => handleFormChange('editResult', e.target.checked)} /> Edit Result</label>
          </div>

          <div>
            <div className="flex items-center gap-6">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">Result Declared</span>
                  <button type="button" className="ml-2 mt-0 inline-flex items-center rounded-full px-2 py-1" onClick={() => { /* read-only summary */ }}>
                    { form.items.find((i) => i.result_declared) ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }
                  </button>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">Include In Total</span>
                  <button type="button" className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ form.items.find((i) => i.include_in_total) ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">Display Value</span>
                  <button type="button" className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ form.items.find((i) => i.display_value) ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">Show Graph</span>
                  <button type="button" className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ form.items.find((i) => i.show_graph) ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">Passing Required</span>
                  <button type="button" className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ form.items.find((i) => i.passing_required) ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                </div>
              </div>
          </div>

          <div className="border-t pt-3">
            <div className="mb-2 flex justify-between items-center">
              <div className="text-sm font-semibold">Assessment Items</div>
              <Button onClick={addItem} variant="dark"><Plus /> ADD FORMULAE</Button>
            </div>
            <div className="space-y-3">
              {form.items.map((it) => (
                <div key={it.id} className="grid grid-cols-12 gap-2 items-center">
                  <div className="col-span-1"><input type="checkbox" /></div>
                  <div className="col-span-2"><input value={it.assessment_name} onChange={(e) => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, assessment_name: e.target.value } : x) })); }} className="w-full rounded-2xl border px-2 py-1" /></div>
                  <div className="col-span-2"><input value={it.assessment_model} onChange={(e) => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, assessment_model: e.target.value } : x) })); }} className="w-full rounded-2xl border px-2 py-1" /></div>
                  <div className="col-span-2"><input value={it.display_name} onChange={(e) => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, display_name: e.target.value } : x) })); }} className="w-full rounded-2xl border px-2 py-1" /></div>
                  <div className="col-span-1"><input type="number" value={it.sequence_no} onChange={(e) => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, sequence_no: e.target.value } : x) })); }} className="w-full rounded-2xl border px-2 py-1" /></div>
                  <div className="col-span-4 flex gap-4 items-center">
                    <div className="flex items-center gap-2">
                      <span className="text-sm">Result Declared</span>
                      <button type="button" onClick={() => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, result_declared: !x.result_declared } : x) })); }} className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ it.result_declared ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm">Include In Total</span>
                      <button type="button" onClick={() => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, include_in_total: !x.include_in_total } : x) })); }} className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ it.include_in_total ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm">Display Value</span>
                      <button type="button" onClick={() => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, display_value: !x.display_value } : x) })); }} className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ it.display_value ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm">Show Graph</span>
                      <button type="button" onClick={() => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, show_graph: !x.show_graph } : x) })); }} className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ it.show_graph ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm">Passing Required</span>
                      <button type="button" onClick={() => { setForm((s) => ({ ...s, items: s.items.map((x) => x.id === it.id ? { ...x, passing_required: !x.passing_required } : x) })); }} className="ml-2 inline-flex items-center rounded-full px-2 py-1">{ it.passing_required ? <ToggleRight className="h-5 w-5 text-emerald-600" /> : <ToggleLeft className="h-5 w-5 text-slate-400" /> }</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Check, Edit3, Eye, Plus, Search, Trash2, X } from 'lucide-react';
import { toast } from 'react-toastify';
import Breadcrumb from '../../components/ui/Breadcrumb.jsx';
import Button from '../../components/ui/Button.jsx';
import {
  useCreateResource,
  useDeleteResource,
  useResourceList,
  useUpdateResource,
} from '../../hooks/useResourceHooks';

const createAttendanceRemarkRow = () => ({
  id: `attendance-remark-${Date.now()}-${Math.random()}`,
  text: '',
  isEditing: true,
});

const formatDate = (value) => (value ? new Date(value).toLocaleDateString('en-GB') : '—');

export default function AttendanceRemarksPage() {
  const [inputRows, setInputRows] = useState([]);
  const [savedDrafts, setSavedDrafts] = useState({});
  const [editStates, setEditStates] = useState({});
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);
  const [viewRemark, setViewRemark] = useState(null);

  const { data, isLoading } = useResourceList('remarks', { page: 1, pageSize: 200 });
  const savedRemarks = data?.items || [];
  const createRemark = useCreateResource('remarks');
  const updateRemark = useUpdateResource('remarks');
  const deleteRemark = useDeleteResource('remarks');

  const filteredRemarks = useMemo(() => {
    const normalizedQuery = searchQuery.trim().toLowerCase();
    if (!normalizedQuery) return savedRemarks;
    return savedRemarks.filter((item) =>
      String(item.text || '')
        .trim()
        .toLowerCase()
        .includes(normalizedQuery)
    );
  }, [savedRemarks, searchQuery]);

  const pageCount = Math.max(1, Math.ceil(filteredRemarks.length / itemsPerPage));
  const pageItems = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredRemarks.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredRemarks, currentPage, itemsPerPage]);

  const handleAddAttendanceRemarkRow = () => {
    setInputRows((current) => [...current, createAttendanceRemarkRow()]);
  };

  const handleChangeInputRow = (id, value) => {
    setInputRows((current) =>
      current.map((row) => (row.id === id ? { ...row, text: value } : row))
    );
  };

  const handleEnableInputRowEdit = (id) => {
    setInputRows((current) =>
      current.map((row) => (row.id === id ? { ...row, isEditing: true } : row))
    );
  };

  const handleRemoveInputRow = (id) => {
    setInputRows((current) => current.filter((row) => row.id !== id));
  };

  const handleSaveAttendanceRemarks = async () => {
    const validRows = inputRows
      .map((row) => ({ ...row, text: row.text.trim() }))
      .filter((row) => row.text.length > 0);

    const existingTexts = new Set(
      savedRemarks.map((item) => String(item.text || '').trim().toLowerCase())
    );

    const normalizedSeen = new Set();
    const uniqueRows = [];
    let duplicateCount = 0;

    validRows.forEach((row) => {
      const normalized = row.text.toLowerCase();
      if (normalizedSeen.has(normalized) || existingTexts.has(normalized)) {
        duplicateCount += 1;
        return;
      }
      normalizedSeen.add(normalized);
      uniqueRows.push(row);
    });

    if (!uniqueRows.length) {
      toast.error('Please add at least one valid unique Attendance Remark.');
      return;
    }

    if (duplicateCount > 0) {
      toast.error('Duplicate Attendance Remarks were removed before saving.');
    }

    const now = new Date().toISOString();

    try {
      await Promise.all(
        uniqueRows.map((row) =>
          createRemark.mutateAsync({ text: row.text, status: 'Active', createdDate: now })
        )
      );
      setInputRows([]);
      setSavedDrafts({});
      setCurrentPage(1);
      toast.success(`${uniqueRows.length} attendance remark${uniqueRows.length === 1 ? '' : 's'} created`);
    } catch (error) {
      toast.error(error?.message || 'Could not save attendance remarks');
    }
  };

  const handleToggleSavedEdit = (id) => {
    const remark = savedRemarks.find((item) => item.id === id);
    if (!remark) return;

    setSavedDrafts((current) => ({
      ...current,
      [id]: current[id] ?? remark.text,
    }));
    setEditStates((current) => ({
      ...current,
      [id]: !current[id],
    }));
  };

  const handleChangeSavedDraft = (id, value) => {
    setSavedDrafts((current) => ({ ...current, [id]: value }));
  };

  const handleConfirmSavedEdit = async (id) => {
    const draft = (savedDrafts[id] ?? '').trim();
    if (!draft) {
      toast.error('Attendance Remark cannot be blank.');
      return;
    }

    try {
      await updateRemark.mutateAsync({ id, payload: { text: draft } });
      setSavedDrafts((current) => {
        const next = { ...current };
        delete next[id];
        return next;
      });
      setEditStates((current) => {
        const next = { ...current };
        delete next[id];
        return next;
      });
      toast.success('Attendance Remark updated');
    } catch (error) {
      toast.error(error?.message || 'Could not update attendance remark');
    }
  };

  const handleDeleteSavedRemark = async (id) => {
    if (!window.confirm('Delete this attendance remark?')) return;

    try {
      await deleteRemark.mutateAsync(id);
      setSavedDrafts((current) => {
        const next = { ...current };
        delete next[id];
        return next;
      });
      setEditStates((current) => {
        const next = { ...current };
        delete next[id];
        return next;
      });
      if (viewRemark?.id === id) setViewRemark(null);
      toast.success('Attendance Remark deleted');
    } catch (error) {
      toast.error(error?.message || 'Could not delete attendance remark');
    }
  };

  const handleViewSavedRemark = (id) => {
    const remark = savedRemarks.find((item) => item.id === id);
    if (!remark) return;
    setViewRemark(remark);
  };

  const hasSavedRemarks = savedRemarks.length > 0;

  return (
    <div className="no-hover-border min-h-[calc(100vh-7rem)] overflow-hidden rounded-[24px] border border-slate-200/80 bg-[linear-gradient(135deg,#f8fafc_0%,#ffffff_55%,#f8fafc_100%)] p-2.5 shadow-[0_18px_45px_rgba(15,23,42,0.06)] sm:p-3 lg:p-4">
      <div className="no-hover-border flex h-full flex-col rounded-[22px] border border-slate-200/70 bg-white/90 p-3 shadow-inner sm:p-4 lg:p-5">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
          <div className="space-y-3">
            <Breadcrumb
              items={[
                { label: 'Dashboard', to: '/' },
                { label: 'Academics Setup', to: '/settings/institute' },
                { label: 'Attendance Remarks' },
              ]}
            />
            <div className="flex flex-wrap items-center gap-3">
              <h1 className="text-3xl font-semibold tracking-tight text-slate-950">Attendance Remarks</h1>
              <span className="text-sm text-slate-500">Attendance Remarks List</span>
            </div>
          </div>

          <Button
            type="button"
            variant="primary"
            onClick={handleAddAttendanceRemarkRow}
            className="inline-flex h-11 items-center gap-2 rounded-[20px] bg-emerald-600 px-5 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-700"
          >
            <Plus className="h-4 w-4" />
            New Attendance Remark
          </Button>
        </div>

        <div className="mt-5 rounded-[20px] border border-slate-200 bg-slate-50 p-4 shadow-sm">
          <div className="space-y-4">
            {inputRows.length === 0 ? (
              <div className="rounded-[18px] border border-dashed border-slate-300 bg-white/80 px-4 py-7 text-sm text-slate-500">
                Click <span className="font-semibold text-slate-900">New Attendance Remark</span> to add an attendance remark.
              </div>
            ) : (
              <div className="space-y-3">
                {inputRows.map((row) => (
                  <div
                    key={row.id}
                    className="grid gap-3 rounded-2xl border border-slate-200 bg-white px-3 py-2 shadow-sm sm:grid-cols-[1fr_auto_auto] sm:items-center"
                  >
                    <div className="min-w-0">
                      <input
                        type="text"
                        value={row.text}
                        onChange={(event) => handleChangeInputRow(row.id, event.target.value)}
                        placeholder="Add Attendance Remark"
                        disabled={!row.isEditing}
                        className={`w-full rounded-2xl border ${row.isEditing ? 'border-slate-200 bg-white' : 'border-slate-200 bg-slate-100'} px-3 py-2 text-sm text-slate-900 outline-none transition focus:border-emerald-400 focus:ring-2 focus:ring-emerald-100 ${row.isEditing ? '' : 'opacity-80'}`}
                      />
                    </div>
                    <button
                      type="button"
                      onClick={() => handleEnableInputRowEdit(row.id)}
                      className="inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-600 transition hover:border-slate-300 hover:bg-slate-100"
                      aria-label="Edit attendance remark"
                    >
                      <Edit3 className="h-4 w-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => handleRemoveInputRow(row.id)}
                      className="inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-600 transition hover:border-rose-300 hover:bg-rose-50 hover:text-rose-700"
                      aria-label="Delete attendance remark"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div className="flex items-center gap-2 rounded-2xl border border-slate-200 bg-white/90 px-3 py-2 shadow-sm">
                <Search className="h-4 w-4 text-slate-400" />
                <input
                  type="search"
                  value={searchQuery}
                  onChange={(event) => {
                    setSearchQuery(event.target.value);
                    setCurrentPage(1);
                  }}
                  placeholder="Search Attendance Remarks"
                  className="w-full border-0 bg-transparent px-1 text-sm text-slate-900 outline-none placeholder:text-slate-400"
                />
              </div>

              <div className="flex justify-end">
                <Button
                  type="button"
                  variant="primary"
                  onClick={handleSaveAttendanceRemarks}
                  className="inline-flex h-11 items-center gap-2 rounded-[20px] bg-emerald-600 px-5 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-700"
                >
                  <Check className="h-4 w-4" />
                  Save
                </Button>
              </div>
            </div>
          </div>
        </div>

        {hasSavedRemarks && (
          <div className="mt-6 overflow-hidden rounded-[20px] border border-slate-200 bg-white shadow-sm">
            <div className="flex flex-col gap-4 border-b border-slate-200 p-4 sm:flex-row sm:items-center sm:justify-between">
              <div className="text-sm text-slate-500">Showing attendance remarks list</div>
              <div className="flex flex-wrap items-center gap-3 text-sm">
                <label className="flex items-center gap-2 text-slate-600">
                  Items Per Page:
                  <select
                    value={itemsPerPage}
                    onChange={(event) => {
                      setItemsPerPage(Number(event.target.value));
                      setCurrentPage(1);
                    }}
                    className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-900 outline-none"
                  >
                    {[5, 10, 20, 50].map((size) => (
                      <option key={size} value={size}>{size}</option>
                    ))}
                  </select>
                </label>
              </div>
            </div>

            {viewRemark && (
              <div className="mb-4 rounded-[18px] border border-slate-200 bg-slate-50 p-4 shadow-sm sm:flex sm:items-start sm:justify-between">
                <div className="space-y-2 text-sm text-slate-700">
                  <p className="font-semibold text-slate-900">View Attendance Remark</p>
                  <p>{viewRemark.text}</p>
                  <p className="text-slate-500">Created: {formatDate(viewRemark.createdDate)}</p>
                  <p className="text-slate-500">Status: {viewRemark.status}</p>
